window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"○○○○○는 아미타부처가 극락세계에서 여러 청중들에게 설법하는 장면을 그린 그림이다. ○○○○○는 중앙의 아미타부처를 중심으로 대세지보살과 관세음보살이 양 옆에 협시하고 있고, 그 앞에는 호법신중인 사대천왕이, 그 뒤에는 부처의 제자들을 비롯한 청중들이 배치되어 있다. 조선후기 19세기 후반의 작품으로 채색과 화면구성법 등에서 조선후기 불화 양식을 잘 반영하고 있다.","a":"수원 청련암 아미타회상도","c":"문화유산자료","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660284.jpg"},{"q":"영덕에 있는 수안 김씨의 사당이다. 조선 중기 유학자로 어려운 사람을 많이 도왔던 김덕유(1694∼1767)을 추모하는 뜻에서 순조 4년(1804) 후손들이 세웠다. 구조는 영덕지방에서 흔히 볼 수 있는 ㅁ자형 주택인데 가운데 문을 중심으로 왼쪽에 사랑채를 오른쪽에는 문간방과 아랫방을 두었다. 뒤쪽에는 사람이 생활하지는 않고 제사를 지내는 따위의 일을 보는 방이 있다. 1980년에 보수하여 현재 보존상태는 양호한 편이고 앞면이 6칸으로 되어 있어 앞에서 보면 제법 당당한 모습을 하고 있다.","a":"돈수재","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663130.jpg"},{"q":"서계(西溪) ○○○은 조선 후기 문관으로 본관은 반남(潘南)이다. 여러 차례에 걸친 출사 권유에도 불구하고 석천동에서 농사지으며 학문 연구와 제자 양성에만 힘썼다. ○○○의 묘는 의령남씨(宜寧南氏), 광주정씨(光州鄭氏) 두 부인과 합장(合葬)된 단분(單墳)이다. 봉분은 4각형으로 호석(護石)을 둘렀는데 이러한 대형의 4각 호석은 조선 후기 사대부묘 석물 조성의 기술력이 대단했음을 보여주는 사례이다. 봉분 앞에 석상과 향로석이 놓여 있으며, 석상의 받침으로 고석(鼓石, 북 형태의 돌)이 아닌 사각형 석재를 사용했는데 이 ○○○ 묘역의 여러 석상에서 동일하게 나타난다.","a":"서계박세당묘역","c":"문화유산자료","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660239.jpg"},{"q":"임진왜란 때 선조를 호종한 공로로 호성공신(扈聖功臣) 2등에 녹훈된 홍진(洪進, 1541∼1616)의 공신도상이다. 홍진은 본관이 남양(南陽), 자는 희고(希古), 호는 인재(認齋), 퇴촌(退村)이다. 현존하는 홍진의 영정은 1604년 호성공신에 녹훈되면서 받은 공신초상화로 판단된다. 사모에 구름문양의 단령을 입고 공수(拱手) 자세로 의자에 앉은 반측면의 모습이다. 얼굴 묘사는 선묘로 이목구비를 그렸고, 돌출한 관골 부분을 조금 짙게 채색한 전형적인 17세기 초상화법을 띠고 있다. 얼굴 묘사에 입체감을 시도한 표현은 보이지 않는다.","a":"인재홍진영정","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637729.jpg"},{"q":"- 지정현황 : 전라남도 유형문화유산(2018년 4월 19일 지정) - 명 칭 : ○○○○○ - 규격/수량 : 높이 253cm, 너비 93cm / 1기 - 시 대 : 조선시대(1713년, 숙종 39) - 내 용 : ○○○○는 이이명(李頣命)이 비문을 짓고, 이우항(李宇恒)이 글씨를 썼다. 비는 관왕묘의 건립 시기와 배경·유지 관리 과정 등을 밝혀주는 중요한 자료이며, 정유재란을 승전으로 이끌었던 이순신과 진린 장군의 행적을 담은 기록물로 역사적·학술적으로 중요한 가치가 있다.","a":"완도 고금도 관왕묘비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102217254500.jpg"},{"q":"경상남도 ○○군 생비량면 ○○○ 부처덤이라 불리우는 구릉 남쪽의 자연석 암벽에 새겨진 것으로 현재 약 29구가 남아 있다. 이들은 절벽에 4층으로 줄을 지어 새겨졌는데 1층 14구, 2층 9구, 3층 3구, 4층 3구 등으로 배치되었고 크기는 30㎝ 내외이다. 대개 연꽃이 새겨진 대좌(臺座)위에 앉아 있고 얼굴은 둥글며 단아하지만 눈·코 ·입의 마멸이 심하다. 몸은 사각형이면서도 단정하고, 양 어깨를 가리며 입은 옷은 밀집되게 나타내어 신라말 고려초 특히 고려시대 불상의 특징이 강하게 엿보인다.","a":"산청 도전리 마애불상군","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641854.jpg"},{"q":"○○ 사인암 바로 옆에 있는 사찰인 ○○○의 본존불로 봉안되어 있는 상이다. 이 불상은 원래 ○○○이 ○○군 황정리 산 28에 소재했었을 때 봉안했던 아미타삼존불의 하나로 대세지보살상이다. 1954년 ○○○이 이곳으로 옮겨지면서 본존상은 없어졌고, 관음보살상은 제천 원각사로 그리고 대세지보살상은 이곳으로 봉안되었다 한다. 복장은 얼마 전까지 있었으나 지금은 도난되어 없다고 한다. 불신과 보관 전면에 도틀거리는 금칠이 두텁게 되어 있어서 재질이나 상의 양식을 파악하기 어려웠다.","a":"단양 청련암 목조보살좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638951.jpg"},{"q":"나주 ○○○○○는 석가모니부처가 주재하는 영축산 설법장면을 그린 것이다. 세로로 긴 화면 중앙에 대좌에 앉은 부처의 모습을 크게 그리고 그 주위에 문수· 보현· 미륵· 제화갈라보살과 10대 제자· 범천· 제석천· 사천왕· 용왕과 용녀, 건달바와 긴나라 등이 둘러싸고 있는 구도이다. ○○○○○는 18세기 중엽의 작품이다. 광배 등 초록색을 사용한 부분이 약간 훼손된 상태이기는 하나 전체적인 색감과 화면구성은 18세기 전라도 지방의 불화의 특성을 잘 보여주는 좋은 작품이다.","a":"나주죽림사극락전영산회상도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051719185100.jpg"},{"q":"이 일대는 울릉도에서 밀집 분포하고 있는 무덤 중 하나이다. 무덤은 산록경사면에 괴석을 이용하여 축대 또는 기단을 쌓아 평평하게 하고, 그 위에 시신을 모시는 돌덧널무덤(석곽묘)을 만들었으며, 그 위에 돌로 봉분을 만들은 적석총 형태이다. 돌덧널(석곽) 입구의 앞은 수직벽으로 되어 있어 마치 신전의 정면처럼 보이는데 이러한 형식은 삼국시대 울릉도에서만 나타나는 특징이다.","a":"울릉남서동고분군","c":"시도기념물","nc":"","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654518.jpg"},{"q":"탱화는 액자나 족자 형태로 만든 불화를 이른다. ○○○ 대웅전 내에 있는 이 후불탱화는 석가여래가 법화경을 설파한 영산회상의 장면을 묘사한 것으로, 가로 140㎝, 세로 180㎝ 크기이다. 비단에 채색하였고, 중앙의 석가여래상을 중심으로 아래쪽 좌우에 협시보살인 문수보살과 보현보살을 배치하였다. 석가여래의 머리 위쪽에는 관음보살과 지장보살을 왼쪽에, 그리고 10대 제자와 화불 2위를 오른쪽에 배열하였다. 화면 사방에는 4천왕상을 배열하였다. 4대 보살과 4천왕상은 모두 두광을 표현하고 붉은색을 많이 사용하였는데, 이는 이 시대 불화의 특징이다.","a":"보문사 석가불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587787.jpg"},{"q":"남명집 삭판과 관련하여 하홍도 등을 논죄하는 내용. 최백년 등의 죄상에 대한 논죄. 교적에 입록되려면 강학례를 거쳐야 함을 통고. 하명,하달한의 징벌문제와 남명집 이정 문제 언급. 하명, 하달한의 부황벌 해제 통고.","a":"통문","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642941.JPG"},{"q":"중앙에 앉아 있는 본존불을 중심으로 오른쪽에 지장보살, 왼쪽에 관음보살이 서 있는 삼존불(三尊佛)이다. 모두 머리와 손, 발 등이 없어진 채로 흩어져 있던 것을 석고로 복원해 놓은 것이다. 본존불은 왼쪽 어깨에 옷을 걸치고 있으며 옷주름을 부드럽게 새겼고, 두 팔은 모두 내려 무릎 부근에 대고 있다. 수염의 표현과 꼭 다문 작은 입이 인상적이며 귀는 길지 않다. 지장보살은 민머리에 본존불과 같은 얼굴이며, 옷은 양 어깨를 감싸고 입었다. 관음보살은 주먹을 쥔 오른손을 가슴에 대고 있으며 머리에는 관을 썼다.","a":"고성 교사리 삼존석불","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641623.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 학익지석묘는 원래 인천구치소(구 소년교도소) 안에 위치하고 있었으나 현재는 인천광역시립박물관 야외전시장에 옮겨 전시하고 있다.","a":"학익동 고인돌","c":"시도기념물","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112113342800.JPG"},{"q":"충장공(忠壯公) 원호(元豪, 1533~1592)는 임진왜란 때 순절(殉節)한 무관이다. 원호는 이탕개(尼蕩介)를 소탕하는 등의 전공을 새웠으며, 임진왜란 때는 여주 신륵사에서 적을 크게 무찔렀다. 원호의 묘는 부인 상주 김씨(尙州金氏)와 합장묘로 조성되었으며, 묘표, 상석, 향로석, 문인석 등의 석물이 있다. 개석방부(蓋石方趺; 지붕돌과 네모난 비석 받침) 형태의 묘표는 1708년에 건립된 것으로 권상하(權尙夏)가 글을 지었다.","a":"원호원두표묘역","c":"문화유산자료","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660258.jpg"},{"q":"○○○○○은 동서로 마주 보고 있는 두 개의 탑이다. 두 개의 탑은 처음부터 함께 만든 것처럼 크기와 모양이 매우 비슷하다. 원래 ○○○에서 동쪽으로 200m 정도 떨어진 절터에 있었는데, 1966년에 현재 위치로 옮겨 왔다. ○○○○○은 무량수전 옆에 있는 보물 제249호 영주 ○○○○○과도 크기와 모양이 비슷하다. 다만 지붕돌받침이 4단이고 바닥돌 크기가 작다는 점에서 무량수전 옆의 ○○○○보다 조금 늦게 만들어졌다고 판단된다. 바닥돌은 각 면의 모서리와 중앙에, 몸돌은 모서리에 기둥 모양 장식을 하였다.","a":"부석사삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640506.jpg"},{"q":"고려 후기 판전의사 좌시중을 지낸 창성부원군 ○○○ 선생과 조선 초기 경상도 병마절도사, 초토안무사를 지낸 ○○○ 선생의 묘이다. 봉분 아래에는 둘레석을 두르고 있으며, 비석은 높이 1m 정도이다. 이 묘들은 고려와 조선 초기의 전형적인 양식을 띠고 있어 당시의 묘제 연구에 귀중한 자료가 되고 있다.","a":"창녕 조우희, 조익수 묘","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655046.jpg"},{"q":"이 서원은 마을 사림들이 후진양성을 위해 광해군 2년(1610)에 성곡 2리 의산마을(분지거릉골) 행의사 터에 ○○○당을 건립한데서 시작한다. 현종 5년(1664) 사당을 건립하여 성오당 이개립(省吾堂 李介立)의 위패를 봉안하면서 절효사(節孝祠)라 불리다가, 숙종 5년(1679) 학사 김응조(鶴沙 金應祖)를 배향하면서 서원으로 승격되었다. 고종 때 철폐되었으나 1970년에 현 위치에 복원하면서 절효사를 경덕사(景德祠)로 바꾸었다. 서원은 양졸당(養拙堂)·○○○당·내삼문·사당이 일직선상으로 배치되어 있고, 각 건물은 조금씩 비켜 앉아 있다.","a":"영주 의산서원","c":"시도기념물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016121917284200.JPG"},{"q":"사마소는 조선시대 과거에 합격한 그 지방의 생원(生員)과 진사(進士)들이 이곳에서 유학(儒學)을 가르치거나 정치(政治)를 토론하던 건물이다. 지위가 높은 사람도 자기 수양을 위해 이곳을 찾아왔다고 한다. 연산군 때에는 생원 · 진사들이 모여 학문을 토론하고 백성에게 양식을 빌려주기도 하였다는 곳이다. 처음 세워진 연대는 확실치 않으나 선조(宣祖) 25년(1592) 임진왜란으로 불타 없어진 뒤 영조(英祖) 17년(1741)에 다시 지어 풍영정(風詠亭)이라 불렀다. 옆면의 사마소라는 현판은 영조 38년(1762) 당시의 부윤(府尹) 홍양한(洪良漢)이 쓴 것이다.","a":"경주사마소","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662347.jpg"},{"q":"『○○○○○』은 부모의 은혜에 보답할 것을 가르치는 불교 경전으로, 이 책은 한 권의 목판본이다. 간행기록에 의하면 명종 17년(1562)에 안동 광흥사에서 여러 경전과 함께 간행되었다. 내용을 보면 크게 4가지로 나눌 수 있다. 첫째, 부모의 은혜를 10가지로 나누어 설명하였다. 둘째, 어머니가 자식을 낳을 때까지 10개월의 과정을 1개월씩으로 나누어 서술하고 있다. 셋째, 아버지보다 어머니의 은혜를 강조하고 있다. 넷째, 은혜를 강조하고 있다. 이 책은 그림을 곁들인 조선 전기의 판본으로 불경간행의 역사, 국어사 및 판화 연구에 중요한 자료이다.","a":"범어사 불설대보부모은중경","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636668.jpg"},{"q":"○○○은 선산김씨로, 아버지는 고려 공민왕대 좌대언(左代言)을 역임하고 신축호종공신(辛丑扈從功臣, 공민왕 12년)에 책봉된 김군정(金君鼎)이고, 조부는 충숙왕대부터 벼슬하여 공민왕대에 지밀직사사(知密直司事)를 역임한 후 화의군(和義君)에 봉군된 김달상(金達祥)이다. 아들은 현감을 역임한 김상기(金尙琦)임.","a":"창원 김가행 묘역","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017081616532200.jpg"},{"q":"기룡리 마을입구에 자리하고 있는 비로, 효성이 지극했던 홍씨집안을 기리기 위해 후손들이 세운 것이다. 이 마을에는 조선시대 공조참의를 지낸 홍연경의 손자 우구의 후손들이 모여 살았는데 연경의 효성이 지극하였고 그 후손들에게서 5대에 걸쳐 9명의 효자가 나왔다. 이들에 얽힌 한 일화에 의하면 영조 때 연경의 후손인 득후가 상직이라는 양자를 들였다. 상직은 대사헌 벼슬에 있으면서 때때로 대궐에 오지 않는 일이 있었는데, 이를 이상하게 여긴 영조가 그 사연을 묻자 고향의 조상묘에 성묘하느라 오지 못하였다고 하였다.","a":"연서 효교비","c":"시도유형문화유산","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643363.jpg"},{"q":"조선 정조가 명릉(숙종의 묘:현재 사적)을 참배하고 돌아오는 길에 할아버지인 영조의 옛 일을 회상하면서 친히 글을 짓고 세운 비이다. 네모난 받침돌 위에 비몸을 세우고, 옆면에서 볼때 지붕선이 여덞팔(八)자와 비슷한 팔작지붕을 모방한 지붕돌을 올리고 있다. 비문의 내용은 영조가 왕자인 연잉군으로 있을 때 부왕인 숙종의 탄신일을 맞아 명릉을 참배하고 돌아오는 길에 이곳 금암발참(黔巖撥站)에서 쉬게 되었다고 한다.","a":"금암기적비","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636124.jpg"},{"q":"○○○의 사적을 기록한 비로, 대웅전 동쪽 약 30m 위치에 건립되어 있다. 비는 화강암 석재로 만들어졌으며, 비좌․비신․개석을 갖춘 형식이다. 비문에는 ‘신라 원효(元曉) 스님이 창건하고 도선국사(道詵國師)가 중건하여 관음사(觀音寺)라고 개칭하였고, 고려 태조(太祖)가 중수하여 ○○○라고 하였다’는 기록이 있다. 여말선초(麗末鮮初)에는 나옹(懶翁)ㆍ무학(無學) 등의 고승이 오래 머물면서 선풍(禪風)을 드날렸다. 조선 태조(太祖) 때 왕명으로 비가 중수된 사실이 기록되어 있다. 비문의 뒷면 음기에는 시주자의 명단이 새겨져 있다.","a":"삼막사사적비","c":"시도유형문화유산","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637582.jpg"},{"q":"○○○터는 봉림산 중턱에 있는 주머니 모양의 분지에 있다. 통일신라 진성여왕 7년(894)에 심희(854∼923)가 지었고, 통일신라시대 구산선문(九山禪門)의 하나로 번창하였으나, 이후의 내력에 대하여 상세히 전하는 바가 없으며 임진왜란 때 없어진 것으로 추측되고 있다. 절의 규모나 구조에 대해 자세히 알 수 없지만 이곳에는 건물터, 연못, 탑의 흔적이 남아있다. 또한 경복궁내에 있는 진경대사 보월능공탑(보물 제362호)과 탑비(보물 제363호)는 물론 상북초등학교내의 삼층석탑이 여기에서 반출된 것으로 알려있다.","a":"창원 봉림사지","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655669.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○○○에 있는 조선백자 가마터에는 같은 모양의 가마 2기가 50m 간격으로 만들어져 있다. 언제부터 이곳에서 자기가 생산되었는지는 밝혀지지 않았으나, 1900년경까지는 백자가 생산되었다고 한다. 이곳에서 구워진 자기로는 순백자와 모래와 점토를 섞어 받쳐 구운 대접, 탕기, 사발, 제기 등 민간인들의 일상 생활용기가 대부분이다. ○○ 조선백자 가마터는 당시 가마의 원형이 그대로 남아있어, 가마의 운영과 사용법, 축조방법을 연구하고 이해하는데 중요한 자료가 되고 있다.","a":"장흥 월송리 백자요지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654058.jpg"},{"q":"○○○은 중종의 9남 덕흥대원군(德興大院君)의 아들인 손자 하원군(河原君) 정(鋥)의 둘째 아들로 이름은 향령(享齡)이다. 1566년(명종 21)에 태어나 13세에 익성정(益城正)에 봉해지고, 임진왜란 당시 의주에 머물던 선조를 따라가 있다가 서울로 돌아와 1597년(선조 30) ○○○에 책봉되었다. 그러나 1612년(광해군 4)에 무고 사건에 휘말려 거제도로 유배되었고, 그곳에서 생을 마쳤다.","a":"익성군신도비및무석","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639139.jpg"},{"q":"○○읍성 안에 있던 ○○○○○의 출입문이다. 병영의 출입문은 보통 원문이라고 부르며, 좌우로 담장이 이어져 병영을 에워싸고 있다. ○○○○○은 당초 충남 해미현에 있다가 조선 효종 2년(1651)에 이곳으로 옮기었다. 1988년까지 ‘청녕각’으로 잘못 알려져 서원현감 이병정이 세운 것으로 여러 책자에 기록되어 있다. 앞면 3칸·옆면 2칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 네모진 높은 주춧돌 위에 세운 2층의 누문으로, 아래층의 중앙에는 문을 달아 출입하고 위층은 마루를 깔고 난간을 둘렀다.","a":"청주 충청도병마절도사영문","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638414.jpg"},{"q":"이 ○○○○은 충북 ○○○ 뒤 언덕 위에 있는 ○○○지에 흩어져 있었던 파불을 옮겨와 동국대학교에서 복원한 불상이다. 옮길 당시 광배는 일부만 남아있었고, 대좌는 반 이상 없어졌으며, 불상 자체도 깨어진 부분이 많았지만 현재는 불상과 대좌를 거의 완전한 형태로 복원하여 통일신라(9세기) 당시의 석불양식을 잘 보여주고 있다. 불신(佛身)은 신체에 비하여 상체가 다소 크지만 무릎폭이 넓고 어깨가 벌어져 안정감이 있다. 얼굴은 살찐 둥근 모습으로 턱부분이 둥글어 양감(量感)을 느끼게 하며, 굵은 나발(螺髮)의 머리에는 육계(肉髻)가 낮게 솟아 있다.","a":"법주사 수정암 석불좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636441.jpg"},{"q":"인천육군조병창에 쌓여 있던 것을 인천시립박물관 초대 관장 이경성이 1946년에 인수해 온 ○○○○○이다. 명문으로 미루어 ○○ 허난성 신정현에서 주조된 것으로 보인다. 이 범종은 돋을 선으로 가사문대(袈娑文帶)를 종신 전체에 두르고, 쌍룡(雙龍)의 용뉴를 달고 있는 등 전형적인 ○○종의 모습을 보인다. 천판(天板)에서 종신(鐘身)가지는 둥글게 이어져 있으며, 팔괘와 연판문 등으로 장식되었다. 그리고 그 아래로 다시 꽃잎이 같은 간격을 두고 배치되어 있다.","a":"중국 철제범종(1982-1)","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2015122810360100.JPG"},{"q":"○○○ 영산전 앞에 자리하고 있는 탑으로, 원래는 법당 앞에 있었으나 법당을 새로 보수하면서 이곳으로 옮겨놓았다. 널찍한 바닥돌 위로, 1층의 기단(基壇)을 쌓고, 5층의 탑신(塔身)을 차례로 올려놓은 모습으로, 탑신부의 1층 몸돌은 옮길 때 잘못 놓았는지 거꾸로 놓여 있다. 기단은 4면마다 모서리에 기둥 모양을 새겨놓은 후, 안상(眼象)을 얕게 새겼으며, 맨 윗돌의 밑면에 연꽃무늬를 두어 장식하였다. 탑신부의 각 몸돌은 기단에서처럼 모서리마다 기둥 모양을 본 떠 새겼고, 특히 5층의 몸돌은 4면에 부처의 모습을 도드라지게 조각해 놓았다.","a":"만일사 오층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661311.jpg"},{"q":"충청남도 천안시 성거읍에 있는 ○○○는 고려 태조 4년(921)에 도선이 지은 사찰로, 석가모니불과 5층 석탑을 만들어 놓았다고 하나 신빙성은 없다. 높이 164㎝의 불상은 관음전 뒤편에 있는 자연동굴 속 암벽에 조각되어 있다. 머리를 잃어버려서 시멘트로 새로 만들었는데 신체에 비해 좀 크게 느껴진다. 깊게 새겨진 옷은 왼쪽 어깨를 감싸고 있으며, 오른손은 무릎 위에 내려 땅을 향하고 왼손은 왼발 위에 올려 놓았다.","a":"만일사 석불좌상","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661313.jpg"},{"q":"조선 중기의 문신이자 의병장인 ○○○과 조선 후기의 실학자인 우하영(1741~1812)의 묘역이다. 1592년 임진왜란이 일어나자 의병을 모집하고 식량을 조달하여 난민을 구제하였다. 우하영은 국가·사회의 개혁방안을 담은 『천일록(千一錄)』을 저술하였다. ○○○ 묘역은 부인 양천허씨(陽川許氏)와 함께 매장된 쌍분(雙墳; 두개의 봉분)의 형태이다. 묘제(墓制)는 의병장의 묘역답게 검소한 제도와 석물로 구성되어 있다. 봉분 앞으로는 묘표, 상석, 향로석이 있고, 하단에는 망주석만 1쌍이 있고, 석인은 조성하지 않았다.","a":"추연우성전묘역(우하영묘역포함)","c":"문화유산자료","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660246.jpg"},{"q":"○○○○는 원주 변씨와 함양 박씨가 모여 사는 마을이다. 이 집은 첨추공파로 이 마을에 처음으로 와서 자리를 잡은 변희리(1435∼1505)의 증손자인 사괴당 응녕(1518∼1586)이 터를 잡았다고 한다. 건물 배치는 튼 ㅁ자형으로 정침과 양날개가 ㄷ자형을 이루면서 앞쪽에 일자형 문간채가 자리잡고 있고, 오른쪽 날개 동쪽에는 2층의 대문채가 있다. 집 구성은 정침과 오른쪽 날개에 걸쳐 세대별 구분이 명확하고, 수장공간의 구성이 뛰어나다. 또한 구조의 접합 기법과 창호 수법에서 세련된 법식을 지니고 있다.","a":"예천 상금곡리 사괴당고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658998.jpg"},{"q":"조선 세조 때 문신인 한확(韓確, 1400~1456)의 행적을 기록한 비이다. 한확의 본관은 청주이고 호는 간이재(簡易齋)이다. 덕종(德宗)의 비인 소혜왕후(昭惠王后)의 아버지이며 성종(成宗)의 외조부이다. 1455년(세조 1) 좌의정이 되고 좌익공신 1등에 올라 서원부원군(西原府院君)에 봉해졌다. 묘역 아래의 비각 안에 방부이수(方趺螭首) 양식을 갖춘 ○○○가 세워져 있다. 왕명으로 1494년(성종 25)부터 1495년(연산군 1)까지 2년에 걸쳐 만들었다.","a":"한확선생신도비","c":"시도유형문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637590.jpg"},{"q":"○○○는 청동기시대에 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 제주시 외도동에 있는 고인돌 무리는 제주시 서쪽을 흐르는 외도천(外都川)일대의 구릉지대에 있으며, 인근의 북제주군 애월읍 광령리 고인돌과 함께 20여 기가 무리를 지어 위치하고 있다.","a":"외도지석묘1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657662.jpg"},{"q":"○○○ 산성각에 걸려 있는 ○○○이다. 가로 95.5㎝, 세로 121㎝ 크기로 비단 바탕에 채색하여 그렸다. 고종 30년(1893)에 제작된 것으로, 민화풍의 나무와 폭포 및 호랑이의 모습 등은 전형적인 19세기 말의 ○○○ 양식을 잘 보여준다. 다만, 원색적이고 장식적이던 당시의 ○○○와는 달리 은은한 중간 색조를 사용한 점이 특이하며, 위엄과 격이 담긴 신선의 얼굴 묘사가 돋보인다.","a":"지장사 산신도","c":"문화유산자료","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2025070417551700.JPG"},{"q":"경기도 ○○○ 용문산 줄기 855m의 봉우리와 여우봉(865m)에서 서쪽과 남쪽으로 뻗은 능선과 북쪽으로 뻗은 큰 계곡을 막아 만든 산성으로, ‘함공성’, ‘양근성’, ‘함씨대왕성’ 등으로 불린다. 성 아래에는 성공혈이라는 큰 바위굴이 있는데 여기서 원삼국시대 함왕 주악(周鍔)이 탄생하였으며, 이 곳을 보호하기 위해 성을 쌓고 부근을 정복하였다고 전해지고 있다. 고려시대 몽골의 4차 침입이 있을 때 몽골군이 쳐들어오자 사람들이 이곳으로 피신하였다는 옛 기록이 남아 있다.","a":"양평군함왕성지","c":"시도기념물","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646585.jpg"},{"q":"○○○[積石塚, 돌무지무덤]은 선사시대부터 역사시대의 고구려, 백제 초기에 나타나는 묘제의 한가지로, 일정한 구역의 지면에 구덩이를 파거나 구덩이 없이 시체를 놓고 그 위에 돌로 쌓은 무덤을 말한다. 고구려의 경우 초기에는 강돌을 주로 사용하였으나, 이후 깬 돌을 계단식으로 쌓아올려 무덤을 만들었다. ○○○○○은 마을 뒤편 야산에 위치하며 경사가 10˚ 이내로 완만한 곳에 축조되어 있다. 사람머리 크기의 자연석으로 쌓아 만든 삼국시대의 무덤으로 추정되며, 붕괴로 말미암아 확실한 구조는 알 수 없다.","a":"은현리적석총","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645870.jpg"},{"q":"○○○○는 마을의 공무를 처리하던 곳이다. 조선 순조 5년(1805)에 이곳으로 옮겨 지었다고 하며, 그 뒤로도 여러 차례 고쳐서 원래 형태에서 많이 바뀐 것으로 보인다. 특히 최근 보수 때 침수에 대비하여 지대를 높이면서 본래의 분위기를 거의 잃었다. 앞면이 7칸으로 제주도의 일반 민가보다 규모가 크고 가운데에 있는 대청도 넓다. 그러나 구조와 양식 등은 민가와 거의 비슷하다. ○○○○는 우리나라에 별로 많지 않은 용도의 건물로 주목 받고 있다.","a":"신촌향사","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643280.jpg"},{"q":"○○○○○는 서방극락세계를 관장하면서 중생들에게 무한한 안락과 수명을 보장해주는 ○○○불의 설법장면을 그린 것으로 『정토삼부경(淨土三部經)』에 근거한 불화이다. ○○○ 요사에 마련된 법당 안에 봉안된 ○○○○○는 원래 극락보전(極樂寶殿)에 봉안되었던 불화로 현재는 불단(佛壇)에 가려 화면의 1/3 밖에 볼 수 없다. 불화는 가로 220㎝, 세로 185㎝의 비단바탕에 진한 채색으로 그려져 있다. 중앙의 ○○○불은 키형의 두광과 신광을 두르고, 높은 대좌 위에 결가부좌하였다. 대의 안쪽에 복견의(覆肩衣)와 승각기(僧脚崎)를 입고, 대의를 변형우견편단으로 걸치고 있다.","a":"쌍계사아미타회상도","c":"문화유산자료","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660230.jpg"},{"q":"농산 김난영이 조선 고종 13년(1876)에 지었고 아들인 남호 김뢰식(1877∼1935)이 살던 집이다. 응방산 줄기의 낮은 야산을 배경으로 자리잡고 있는 이 집은 솟을대문이 있는 대문간채를 들어서면 안채와 사랑채가 접하여 ㅁ자형을 이루고 있다. 이 지방의 ㅁ자형 집은 사랑채가 있는 가운데에 중문간을 두는 것이 일반적인데 이 집은 옆면에 중문간이 있다. 정면 중앙 부분에는 튀어나온 도장방이 있어 특이한 구성을 보이는데 이 마을에는 이같은 유형의 집이 몇 채 남아 있다.","a":"봉화남호구택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663261.jpg"},{"q":"척화비란 쇄국정책을 실시하던 흥선대원군이 병인양요, 신미양요를 치르면서 더욱 의지를 굳혀 서양사람들을 배척하고 그들의 침략을 국민에게 경고하기 위해 서울 및 전국 중요 도로변에 세우도록 한 비이다. 신창 초등학교 입구에 자리하고 있는 이 비는 높직한 사각받침 위로 비몸을 세운 모습이다. 비문에는 “서양오랑캐가 침범함에 싸우지 않으면 화의인데, 화의를 주장함은 나라를 파는 것이다.”라는 강한 경고 문구가 쓰여 있다.","a":"신창척화비","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661293.jpg"},{"q":"경상남도 ○○군 주상면 성기리에 있는 성곽으로, 산 정상부를 성 안으로 하고 있는 테뫼식 산성이다. 자연 암반 위에 자연석을 받쳐 쌓아올린 성벽으로 현재 30m 정도만이 남아있다. 임진왜란 때 의병들이 쌓은 성이라고 전해지고 있으나, 확실하지는 않다. 성이 산꼭대기에 있으며, 성벽을 만들 때 외벽은 돌로 쌓고 안벽은 흙으로 밋밋하게 쌓는 내탁법을 사용한 점으로 보아, 삼국시대에 만들어져서 조선시대까지 계속해서 사용된 것으로 보인다.","a":"거창 성기성","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664045.jpg"},{"q":"동구림리에서 도갑사 방향으로 오른쪽 400∼500m 거리에 있는 ○○○○ 대나무밭 옆에 자리한 장승이다. 보통 장승이라고 하면 나무나 돌의 윗부분에 사람의 얼굴을 새기거나 그려 넣은 기둥을 말하는데, 이 장승은 비석의 형태를 하고 있다. 높이 105∼120㎝, 폭 68㎝, 두께 22∼26㎝로, 앞면 가운데에 ‘황장생(皇長生)’이라는 세 글자를 새겨 놓았는데, 뒷면 모서리 부분이 약간 깨진 상태이다. 황장생의 ‘황’은 통일신라∼고려시대에 왕의 명을 받아 세우는 장생에 붙는 말로, 매우 귀한 글자라고 한다.","a":"영암소전머리황장승","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658376.jpg"},{"q":"○○○○ 종중의 요여는 홍성 노은서원이 철폐된 1871년에 종중에서 봉사(奉事)를 위해 제작하여 성삼문(成三問)의 신주를 논산시 상월면의 암천공 재실로 봉안할 때와 1903년 성삼문의 사손(祀孫)이 결정되어 문절사(文節祠)에 신주를 봉안할 때에 사용되었다. 요여는 붉은색, 회색, 백색으로 외부를 칠하였고, 천정은 직조물을 사용하여 납작한 반구형의 모양을 하였으며 지붕의 중앙 부분에 보주형의 장식을 달았다. 사방에 붉은색의 처마를 만들었고, 좌․우․후면에는 들창문을, 정면에는 쌍창문을 하였다.","a":"무안박씨요여","c":"시도민속문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658274.jpg"},{"q":"조선 전기 문신 여희림(1481∼1553)이 여씨향약을 교육하기 위해 세운 것이다. 조선 중종 11년(1516)에 세운 것을 현종 5년(1664) 여희림의 자손 여효회가 지금 있는 자리로 옮겨 세웠다고 한다. 건물은 앞면 7칸·옆면 1칸 규모의 ○○○, 앞면 3칸·옆면 1칸 규모의 전사청, 앞면 4칸·옆면 1칸 규모의 교직사와 솟을삼문으로 구성되어 있다. 최초의 여씨향약 강당인 동시에 1919년 파리만국평화회의에 보낼 『파리장서』를 써서 송준필·김창숙·여상윤 등이 서명하여 독립만세를 부른 곳이기도 하다.","a":"월회당","c":"시도기념물","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654470.jpg"},{"q":"경상남도 ○○시 해발 243m의 주화산 산마루에 있는 돌로 쌓은 성으로, ○○읍성으로부터 동쪽으로 약 2㎞지점에 있다. ○○○○은 신라가 가야와 낙동강을 사이에 두고 대치하던 시대에 만들어진 것으로 보이는 삼국시대 초기의 산성터로 추정된다. 성의 둘레는 1430m이고, 성의 구조는 동, 서, 남에 문터가 있고 북쪽 계곡의 평지에는 우물, 연못 부속건물들이 있었던 것 같다. ○○○ 서·북부 정상에는 봉수대가 있는데 적의 침입이 있을 때에는 군사적 고지이면서, 주변의 주민과 군사들에게 적의 침입을 알리는 기능을 하였던 곳이었다.","a":"밀양 추화산성","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655327.jpg"},{"q":"○○읍 ○○○ 마을 논밭 사이에 북쪽을 향하여 서 있는 불상으로, 작은 2구의 불상과 함께 주변에 흩어져 있던 것을 1949년 마을 뒷산에 성주사를 세운 윤월인 스님이 이 불상들을 모아 다시 세웠다가 한국전쟁 후 마을의 수호부처로서 주민들이 보호하고 있다. 발 아래부분이 땅에 묻혀 있는 이 불상은 머리에 높은 보관을 쓰고 왼손을 가슴부분에 들어 연꽃송이를 받치고 있는 보살상이다. 보관을 써서 머리부분이 상당히 큰 편이고, 어깨가 좁으며 몸의 양감은 편평하여 전체적으로 길쭉한 사각형의 형태를 보인다. 미소짓는 얼굴의 표정이 잘 조각되어 온화한 인상을 풍기고 있다.","a":"증평 남하리 석조보살입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638749.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 전형적인 향교 건축으로 조선 세종 15년(1433)에 처음 지었다고 전하나 그 뒤 불타 없어졌다．광해군 3년(1611)에 대성전만 다시 지었고, 인조 25년(1647) ○○○를 세운 것으로 보인다. 현재 남아있는 건물로는 대성전와 명륜당, ○○○, 동재, 서재, 외삼문 등이다. 외삼문 밖에 자리하고 있는 ○○○○○는 앞면 3칸·옆면 2칸 규모의 2층 누각이다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 되어 있다.","a":"화순향교만화루","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661992.jpg"},{"q":"이 3기의 방형분묘는 고려 고종∼충선왕대의 인물인 河東 鄭氏 國龍과 그의 두 아들 芝衍, 蘭衍의 묘로 전해지는 것이다. ○○○은 고려 고종대에 匡靖大夫密直副使에 증직된 인물이다. 그의 큰아들 지연(僉議公)은 충렬왕대에 中郞將과 左常侍를 거쳐, 충선왕대에 同知密直司事, 大匡都僉議贊成事 判選部事를 역임한 이로 시호는 文忠公이다. 국룡의 둘째아들 난연(左尹公)은 충렬왕대에 左尹을 역임하였다. 기록상 생물연대는 분명하지 않으나, 활동시기가 분명하므로 묘의 조성 시기는 대체로 13세기 후반 ∼14세기 초에 걸치는 것으로 판단된다.","a":"하동 정국룡 묘역","c":"시도기념물","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657431.jpg"},{"q":"조선 태종(太宗) 부마(駙馬) ○○○ 권규(權跬, 1393~1421)와 부인 경안 궁주(慶安宮主, 1393~1415)의 묘역이다. 권규는 길창군(吉昌君) 권근(權近)의 3남으로 1403년 태종의 3녀 경안궁주와 혼인해 길천군(吉川君)에 봉해졌다. 권규와 경안 궁주 묘역은 상하분(上下墳)으로 권규의 봉분이 위쪽, 경안궁주 봉분이 아래쪽에 있다. 묘역의 경사가 급해 북쪽에 석축을 쌓았고 좌우로 곡장(曲墻)의 흔적이 남아 있다. 또 각 봉분도 2개의 단을 쌓고 계체석(階砌石; 계단)도 설치했다. 각 봉분은 장대석(長大石)으로 만든 8각의 호석(護石)이 둘러져 있다.","a":"제간공 권규묘역","c":"시도기념물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2023041310152300.jpg"},{"q":"수명장수와 현세의 복을 구하기 위해 그려지는 ○○○는 산왕(山王)으로 신앙되던 호랑이를 의인화하여 묘사한 불화이다. 불교가 민간신앙과 결합하면서 토착화하는 과정에서 산신에 대한 신앙이 유행하면서 사찰의 산신각, 산왕각, 삼성각 등에 봉안되었다. 이 ○○○는 화기에 의하면 1901년(광무5년)에 환옹후진(幻翁嗅眞)이 증명(證明)을 맡고, 수경당승호(繍瓊堂承琥)가 수화사(首畵師)로 예운당상규(禮芸堂尙奎), 창오(昌旿), 상근(尙根), 영욱(靈昱), 긍엽(亘葉)등이 제작에 참여한 작품으로 칠성도, 독성도 등과 함께 봉안된 것이다.","a":"지장암 산신도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636489.jpg"},{"q":"○○○에 있는 산성으로, 능선의 병풍처럼 생긴 자연 암반을 북벽으로 하고, 서남쪽의 계곡을 성안에 품어 산꼭대기를 둘러쌓았다. 성의 둘레는 1,500m이고, 높이는 3m, 폭은 4.5m 정도이다. 남쪽의 좁은 계곡을 성문으로 삼고, 좌우의 낮은 지역에는 자연석으로 성벽을 쌓았으며, 높은 암벽을 최대한 활용하면서 능선을 따라 쌓아서 정면에서 보면 마치 이등변삼각형처럼 보인다. 북쪽과 동쪽은 비교적 완전한 편이나, 서쪽은 자연적인 풍화로 붕괴되어 있다.","a":"창녕 영축산성","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664015.jpg"},{"q":"○○○에 모셔져 있는 철로 만든 여래좌상으로 높이 1.03m, 무릎 너비 0.8이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 낮게 표현되었다. 4각형에 가까운 얼굴은 눈이 작은 편이며 귀는 어깨까지 길게 내려오고 있다. 옷은 왼쪽 어깨를 감싸고 있으며 옷깃이 왼쪽 어깨에서 수직으로 내려오고, 왼쪽 겨드랑이 부분에 매듭이 보인다. 옷주름은 매듭에서 오른쪽 허리를 향하여 비스듬하게 표현되었다.","a":"대복사철불좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639390.jpg"},{"q":"경남 ○○시 서상동 ○○ 정상부에 청동기시대에서 조선시대 전기까지 이르는 취락 유적이다. ○○○○은 청동기시대 및 삼한시대에 외적으로부터 침입을 막기 위해 설치한 방어시설인 환호와 집터, 저장시설, 조개무지 등으로 되어 있었다. 이곳에서는 청동기시대의 민무늬토기와 삼한시대의 각종 토기류를 비롯하여 반달 모양의 돌칼 등의 석기류와 철기류, 골각기류 등 총 399점의 유물을 출토하였다.","a":"창원 남산 유적","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656536.jpg"},{"q":"전라남도 무안군 무안읍 ○○○는 고려 태조 1년(918)에 남악사라는 이름으로 창건하였다고 하나 문헌 근거는 없다. 그러나 현 위치에 있는 석불의 규모로 보아 이 자리에 고려시대부터 상당한 규모의 사찰이 있던 것으로 보인다. 현재의 ○○○ 건물은 1972년 세운 것이다. 왼손에 큰 약항아리를 들고 있는 것으로 보아 약사여래를 표현하고자 한 것으로 보인다. 그런데 민머리 위에 상투 모양의 머리묶음이 없어서 지장보살로 보이기도 하는데 머리묶음을 인위적으로 깎아 낸 흔적이 보인다.","a":"무안약사사석불입상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640113.jpg"},{"q":"제주 한림읍 ○○○○○은 불복장에서 발견된 발원문에 의해 1661년이라는 조성연대와 운혜와 상전이 조각한 불상으로 17세기 불상연구에 중요한 자료를 제공하는 등 문화유산적 가치가 높이 평가되고 있다. 1671년 조선후기의 조각장인 응혜·계찬스님에 의해 아미타삼존불의 협시보살로 조성된 삼광사 목조불상은 17세기 불상연구의 중요한 단초를 제공하며, 용문사 불상의 경우 시주자와 조성자가 밝혀져 조선후기 불상양식을 고찰할 수 있는 중요한 문화유산이다.","a":"월계사 목조아미타불 좌상","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643339.jpg"},{"q":"이 건물은 달성서씨(達城徐氏) 학유공파(學諭公派) 9세손인 청송입향조 서윤(徐尹)과 그의 손(孫) 서창(徐昌), 그리고 서창의 손(孫) 서봉(徐琒) 세분을 봉정(奉呈)하기 위하여 건립한 것으로 창건연대는 1800년경으로 추정이 된다. 서원 철폐령 당시 훼철되었던 사당을 지난 2006년도에 복원하게되면서 파조(派祖)인 학유공(學諭公) 서도(徐渡)를 주벽(主壁)으로 하고 위 세분의 위패(位牌)를 복설(復設)하여 매년9월 초정(初丁)에 향사(享祀) 하고 있다 현재 재사(齋舍), 대문채, 곡간채, 주사채만 남아 ‘ㅁ’자형 배치의 공간으로 이루어져 있다","a":"청송덕양재","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663425.jpg"},{"q":"○○○은 금계산 기슭에 있었던 역원(驛院)으로, 조선시대에 교통시설과 공공기관으로 사용되었으나, 가까운 곳에 검부역이 생기면서 폐지되었다. 비는 이와 관련이 있는 것으로, 자연돌을 거칠게 다듬어 세워 놓았는데, 비의 윗변이 안쪽으로 비스듬히 다듬어져 전체적으로 뾰족한 인상을 준다. 앞면에는 8줄에 걸친 비문을 새겼다. 내용 중에는 동복현감을 지낸 ‘심지헌’이라는 인물의 이름도 보이는데, 그는 조선 현종 7년(1666) 9월 이곳에 부임하였다가 1668년에 다른 곳으로 옮겨갔음이 확인되었다.","a":"화순동복남덕원비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640134.jpg"},{"q":"‘○○○ 유적’은 한성기 백제의 토성 유적이다. 2003년에 발굴조사를 실시한 결과 한성기 백제의 다양한 유구들이 확인되었으며, 이 가운데 저장 구덩이 1기에 대해서 내부조사를 실시하였다. 이후에 2012년에 유적의 정비 복원을 위한 학술 발굴조사에서 한성기 백제 토성임이 새롭게 밝혀졌다. 유적은 ○○○ 정상부에 위치한다. 토성의 평면 형태는 타원형이며, 전체 둘레는 300m로 추정되는데, 현재 산 정상부의 남서쪽 언저리를 따라 남아 있다.","a":"고양멱절산유적","c":"시도기념물","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020031511502100.JPG"},{"q":"금오산 정상에 자리한 전통사찰 ○○○의 대웅전 본존불이다. 이 석조불상은 신라 말 혹은 고려 초에 조성된 것으로 추정이 되며, 개금이 두텁게 되어 있으나 그 재질은 화강암으로 보인다. 개금하기 전인 1960년대의 사진에 의하면 원만한 상호에 완전한 형태의 석가여래상임을 알 수 있다. 특히 영남지역의 석불 연구에 귀중한 자료라고 한다. 「○○○중수기(藥師庵重修記)」에 따르면 본래 지리산에 있던 석불(石佛) 3구(軀)[삼형제불(三兄弟佛)] 가운데 1불(佛)이라고 한다.","a":"구미약사암석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641127.jpg"},{"q":"전라남도 진도군 의신면 사천리 ○○○○○에 있는 ○○○○○이다. ○○○○은 지옥에서 고통받는 중생의 구제를 위해 영원히 부처가 되지 않는 보살로, 민머리를 하고 머리에 두건을 쓰고 있는 것이 특징이다. 진도 ○○○의 ○○○에는 주존인 ○○○○좌상을 비롯하여 현재 33구의 목조각상이 있다. 시왕은 의자에 앉아 있으며 나머지 상들은 모두 입상으로 금칠이 되어있다. 대체로 보존상태가 양호하며 33구 중 4구는 후대에 복원된 것이다. 1993년 ○○○○삼존상을 수리하던 중 도명존자상 속에서 조선 현종 7년(1666)에 만들었다는 기록이 발견되었다.","a":"진도쌍계사시왕전목조지장보살상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640143.jpg"},{"q":"이 목판은 임진왜란 때 공을 세운 송암 이노(1544∼1598)가 쓴 전쟁일기를 새긴 것이다. 이노는 일찍이 조식의 문하에서 수학하고 선조 24년(1591)에 문과에 급제했으나, 이듬해 임진왜란이 일어나자 조종도와 함께 김성일 휘하로 들어가 의병을 모으는 등 크게 공을 세웠다. 그 뒤 형조좌랑, 사간원 정언 등을 역임하였고, 선조 30년(1597)에 『○○○○』를 완성하였으며, 그 이듬해 55세를 일기로 세상을 떠났다. 여기에는 선조 25년(1592)에서 선조 30년(1597)까지의 기록이 자세히 기록되어 있다.","a":"용사일기목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641489.jpg"},{"q":"조선시대 만들어진 전체 높이 107㎝, 몸체 높이 80㎝의 동종이다. 동종은 2마리의 용에 의해 매달려 있고, 몸통 어깨의 4곳에 정사각형의 유곽을 배치하였다. 유곽 안에는 돌출된 9개의 유두가 있고, 유곽의 사이에는 위·아래 각각 원형 머리광배을 가진 보살상을 새겼다. 몸통의 윗부분에 2줄의 직사각형 띠를 만들어 그 안에 원을 그리고, 범자를 도드라지게 새겼다. 아랫부분에는 연꽃과 보상화를 교차시킨 덩굴무늬 띠를 만들어, 종 표면의 문양에 통일감과 안정감을 주고 있다. 이 동종은 마곡사 오층석탑 동쪽 심검당의 툇마루에 자리하고 있다.","a":"마곡사동종","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639104.jpg"},{"q":"○○○란 어떠한 사건이나 사업에 관련된 사실이나 자취를 기록해 놓은 비이다. 이 비는 조선 영조 49년(1773) 호남좌수사로 부임해온 김영수가 전라○○○의 성을 크게 다시 지어 새로이 하고, 군사를 정비하며, 군기, 잡물 등을 마련한 사실과 월과미(月課米:중앙에서 지방의 관아에 매달마다 부과하였던 세금), 털 없는 겉벼 등을 마련해 놓았던 사실을 적고 있다. 비각 안에 모셔둔 비는 네모난 받침돌 위로 비몸을 세우고 머릿돌을 올린 모습으로, 비몸 앞면에 ‘○○○○○’라는 비의 명칭을 가로로 새겨 놓았다. 비문은 한줄에 42∼45자씩 14줄의 글을 세로로 적어 놓았다.","a":"여수호좌수영수성창설사적비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662230.jpg"},{"q":"2층 규모의 붉은 벽돌 치장쌓기한 건물로, 일제가 1911년 8월 ‘조선교육령’을 발표한 뒤 대전에 처음 생긴 ○○○○이다. 경부선 철도 부설공사로 인해 일본인의 이주가 많아 일본인 아동을 교육하는 소학교의 필요성에 의해 건립되었다. 당시 유리를 많이 사용하던 추세에 맞춰 전·후면을 비롯한 양 측면에 유리창을 많이 넣었고, 현관은 충남도청처럼 귀빈 승용차가 현관 입구에 차를 세울 수 있도록 하였다. 입면에는 원형창을 설치, 내부 채광을 도입함과 동시에 주변의 직사각형 수직창과 대조를 이루게함으로써 미적인 측면을 배려한 것으로 보인다.","a":"삼성초등학교구교사","c":"문화유산자료","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659764.jpg"},{"q":"이 그림은 1625년(인조3) 을축년(乙丑年)에 태어난 7명의 동갑들이 회갑을 맞은 기념으로 계회(契會)를 연 장면을 그린 것이다. 구도면에서 조선 전기 계회도의 전형적인 3단 형식을 취해 제작된 이 그림은 맨 위에 전서(篆書)로 쓴 ‘○○○○○’라는 제목이 있고 중간 부분에는 계회(契會) 장면이 그려져 있으며 아랫부분에는 참석자들의 명단인 좌목(座目)이 있다. 대개 계회도(契會圖)의 제목은 묵서(墨書)로 쓰여 지나 이 그림은 주서(朱書)로 되어 있는데 이는 매우 드문 예이다.","a":"을축갑회도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590367.jpg"},{"q":"경산 이씨인 이천배·이천봉·이주를 추모하기 위해 도내 유림에서 세운 건물이다. 이천배와 이천봉은 형제 사이로 함께 정구에게 가르침을 받았는데, 이 중 이천봉은 정묘호란 때 성주에서 의병을 일으킨 공으로 벼슬을 지냈다. 조선 현종 13년(1672)에 세운 이 서원은 처음에는 성현을 모시고 제사를 지내는 기능만 담당하는 덕암사로 세웠다. 고종 5년(1868) 흥선대원군의 서원철폐령으로 해체되었다가, 고종 13년(1876) 덕암서당으로 고쳐 세우면서 교육 기능도 겸했던 것으로 보인다. 대문 격인 건명문을 들어서면 남동향으로 서당이 자리하고 있다.","a":"덕암서원","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663052.jpg"},{"q":"조선 인종 때의 학자인 하서 김인후(1510∼1560)와 관련된 문서들을 새긴 ○○으로, 모두 56판이다. 김인후는 1540년 문과에 급제하여 문원부정자를 시작으로 홍문관의 박사와 부수찬, 옥과현감 등의 벼슬을 지냈다. 시문에 뛰어나 10여 권의 문집을 남겼으나 도학(道學)에 관해 쓴 책은 많지 않다. 천문, 지리, 의약, 산수에도 정통하였으며, 제자로는 정철, 조희문 등이 있다. 그가 죽은 후 ○○의 ○○○○, 옥과의 영귀서원 등에 모셔졌고, 시호는 ‘문정’이다.","a":"장성 필암서원 하서유묵 목판 일괄","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018112114453100.jpg"},{"q":"송애당 김경여(松崖堂 金慶餘, 1596~1653)의 어머니 송씨부인의 지극한 효성을 기리기 위하여 영조 (재위 1724∼1776) 때 나라에서 내려준 정려기(旌閭記)를 보호하기 위한 건물이다. 명정의 시기는 명정에 의하면 \"崇禎再己酉今上五年六月日命旌\"으로 되어 있어 1729년(영조 5)임을 알 수 있다. 정려는 사괴석 담장을 쌓아 보호하고 있다. 정려의 규모는 전면 1칸, 측면 1칸이다. 사괴석장대석으로 쌓은 기단 위에 낮은 네모꼴 주춧돌과 그 위에 다시 윗면만 8각 단면으로 깎은 네모난 장초석을 놓고 짧은 두리기둥을 세웠다.","a":"은진송씨정려각","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637215.jpg"},{"q":"남계 이온(李溫)이 말년에 세운 정자로 선조 13년(1580)에 세우고 현종 14년(1673)과 철종 7년(1856)에 다시 지었다고 전해진다. 앞면 3칸·옆면 2칸 규모로 대청마루와 방으로 이루어져 있다.","a":"남계정","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639593.jpg"},{"q":"○○ 성씨와 관계된 문적을 새긴 것으로, 조선시대의 ○○들이다. 이 책판들은 『우계선생문집』책판 284매, 『두문동선생실기』책판 33매, 『○○성만역보』책판 22매, 『○○성씨문행열전』 70매, 『성시중효행록』 46매, 『○○성씨가축보』 189매 등으로 이루어져 있다. 이 책판들은 우계 성혼(1525∼1598)을 모셨던 ○○○○에 보관되어 있다가 대원군의 서원철폐 때 맥산재로 옮겨 보관하였다. 그후 ○○○○을 89∼94년까지 복원하고 서원의 경내에 책판고를 96년 11월 9일에 복원하여 책판을 다시 옮겨 보관하고 있다.","a":"창녕 물계서원 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642102.jpg"},{"q":"조선시대 병조참판을 지낸 유치명(1771∼1861)이 학문을 연구하던 곳으로 철종 6년(1855)에 세운 정자이다. 처음에는 임하면 사의동에 자리잡고 있었으나, 임하댐 수몰로 1988년 이곳으로 옮겨 지었다. 건물 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 이원조가 쓴 ‘○○○’이라고 쓴 현판이 걸려 있고, 유치명이 스스로 지은 기문이 있다.","a":"만우정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662404.jpg"},{"q":"경기도 양주 장흥면 삼하리 ○○○ 계곡의 자연 암반 9곳에 새겨진 글씨이다. 새겨진 여러 글씨 중에 쓴 사람을 추정할 수 있는 것으로 세로 약 50cm길이로 ‘夢齋(몽재)’라는 행서체 대자 명문이 있는데, 그 말미에 ‘秋史(추사)’라는 글씨가 새겨져 있어 조선 후기의 유명한 문인 서예가 추사 김정희(金正喜, 1786∼1856)의 필적임을 추정할 수 있다.","a":"노고산독재동추사필적암각문","c":"시도기념물","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646359.jpg"},{"q":"1898년 중건된 ○○○는 치목, 구조수법 등에 두드러진 특징은 없으나 중앙 마루 후부에 서고를 둔 점과 평면이 전후퇴가 발달한 겹집유형이라는 점과 입면구성에서 장식적 성격이 강하다. 이는 근대 초기 한옥의 경향을 잘 보여주는 것으로 19세기말 ○○지방 재실건축의 특징을 잘 보여준다.","a":"산청 인지재","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666354.jpg"},{"q":"○○○은 한국의 토속신인 산신 곧 산신령을 모시는 곳으로, 마을과 절을 수호하는 기능을 가진다. 용부원리 마을의 산 중턱에 자리한 이 ○○○ 내부에는 ‘○○산신지위(竹嶺山神之位)’라 적은 위패를 모셔두고 있다. ○○산신을 모시는 곳으로, 마을에서는 ○○산신을 ‘다자구 할머니’라고 부르고 있어 이 건물 역시 ‘다자구할머니당’이라 칭하고 있다. 다자구할머니를 ○○산신으로 모시게 된 데에는 다음과 같은 이야기가 전한다. 옛날 이곳에는 산적들이 밤낮으로 나타나 백성을 괴롭혔는데, 산이 험준하여 관군도 산적을 토벌하기 힘들었다.","a":"단양 죽령 산신당","c":"시도민속문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658205.jpg"},{"q":"○○○○○는 풍광이 매우 수려한 반변천변의 나지막한 구릉 위에 세워진 정자이다. 안동권씨 용담(龍潭) 권지(權誌; 1567~1637)가 창건하였고, 아들인 번곡(樊谷) 권창업(權昌業; 1600~1663)이 물려받아 별서(別墅)로 삼았으며, 손자 산택재(山澤齋) 권태시(權泰時; 1635~1719)가 무너진 건물을 중건하여 학문 연구와 후학을 양성하는 강학처로 삼았다. 그 후 ○○○는 다시 폐허로 변하였다가, 1916년에 중당협실형(中堂挾室形) 정자로 중건되었다.","a":"영양 남경대","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102610412900.jpg"},{"q":"옛날 고을 수령들의 연회장으로 쓰였던 건물이라고 하며, 언제 지어졌는지는 알지 못한다. ‘도계문루’라고도 불렸다고 하며 동쪽에 동헌터가 남아있는 점으로 보아, ○○현 관아의 문루였던 것으로 보인다. 앞면 3칸·옆면 2칸의 2층 누각으로, 여덟 팔(八)자 모양의 화려한 팔작지붕집이다. 2층 툇마루 밖으로 난간을 둘렀다. ○○○○○는 ○○군에서는 가장 오래된 누각 건물이다.","a":"합천 삼가 기양루","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641559.jpg"},{"q":"고려말 조선초기의 문신인 차원부(1320~1407)의 유문(遺文)과 관련 기록을 <○○○○○>라는 이름으로 엮어 1791년에 새긴 목판 53판이다. 중앙기관인 운각(芸閣)관 관련되고 빠진 것이 없이 전체가 보존되어 오고 있어 인쇄사적으로 가치가 크다.","a":"차문절공유사목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052018334500.JPG"},{"q":"○○○○○은 경상북도에서 가장 오래된 성당이다. 1895년 초대 주임 신부로 부임한 가밀로 파이아스(한국이름 하경조) 신부가 다섯 칸 규모의 기와집을 본당으로 사용한 것이 시초였다. 수로를 이용하여 내륙으로 천주교를 전파하고자 낙동강 선착장 가까이에 위치하였으며 이후 신자가 늘어 본당이 비좁아지자 1923년 당시 주임 신부였던 투르뇌(한국이름 여동선) 신부가 현재의 자리에 성당을 새로 지었다. 설계는 명동성당 등을 설계한 빅토르 루이 푸아넬(한국이름 박도행)* 신부가 맡았다. ○○○○은 지하 1층, 지상 1층의 신로마네스크 양식 건축물로 정면 중앙에 종탑이 있다.","a":"칠곡 가실성당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2022041516231100.JPG"},{"q":"1848년에 중건하고 1872년에 이건한 서당으로, 서당골 야산 중턱에 남서향하여 자리잡고 있다. 서당은 정면 4칸 측면 2칸 규모의 팔작기와집이다. 평면은 2칸 규모의 대청을 중심으로 좌우에 온돌방 1칸씩을 연접시킨 중당협실형(中堂挾室形)인데, 대청의 전면에는 쪽마루를 설치하였으며 양측 온돌방 뒤벽에는 반침을 두었다. 가구는 종량위에 제형판대공을 세워 마룻대와 장혀를 받게 한 5량가의 소로수장집이다. 가까이는 이산서원이 위치하고 있어 이 지역의 교육기관으로서 역사적 전통을 보여주고 있다.","a":"영주 도림서당","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020030409262700.jpg"},{"q":"이 건물은 의성김씨 청계공 김진金璡의 7세손인 제산霽山 김성탁金聖鐸 선생의 묘소를 수호하기 위해 지은 재사齋舍로 건립연대는 1830년경으로 추정이 된다. 가옥의 형태는 본채가 마루 중심형의 겹집 평면을 취하고 있는데 이러한 마루중심형의 겹집은 수십 년 전만하더라도 경북 북부지역에서 흔히 찾아 볼 수 있는 주택 유형이었으나 지금은 거의 소멸된 상태이다.","a":"청송 병보재사","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663545.jpg"},{"q":"전라남도 순천시 해룡면 신성리에 있는 낮은 구릉지대에 내·외성 2중으로 돌로 쌓아 만든 성이다. 1597년 정유재란 때 왜장 소서행이 일본군의 호남 공격을 위한 전진기지 겸 최후 방어기지로 삼기 위하여 쌓은 왜성이다. ○○○○은 왜교 또는 예교(曳橋)라 하며 일본사람들은 순천성이라 부르고 있고, 1997년 1월 1일 국가 사적에서 해제되기 전까지는 ‘승주 신성리성’으로 불려왔다. 성벽은 외성 3첩과 내성 3첩으로 쌓았는데 내성만 그 흔적이 분명하고 외성은 분명치 않으며, 성 주위에는 연못을 둘러 판 흔적이 남아 있다.","a":"순천왜성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654328.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 묘앞에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생의 공적을 기리고 있다. ○○○은 선조 38년(1605) 문과에 급제한 후 승문원을 거쳐 예문관 전적이 되었다. 그러던 중 광해군이 인목대비를 유폐하고 정치가 날로 어려워지자 인조를 추대하는 인조반정에 가담하였다. 정묘호란과 병자호란 때에는 청나라를 배척하는 당대 여론에 맞서 현실적인 외교정책을 추진하였다. 청의 군대가 물러간 뒤 우의정이 되어 왕을 위로하고 흩어진 정사를 잘 정리하여 국내외가 안정되도록 하였고, 이 후 좌의정을 거쳐 영의정에 이르렀다.","a":"청주 최명길 신도비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2017012309443300.jpg"},{"q":"어은 양사형(1547∼1599)이 조선 명종 22년(1567)에 분가하면서 지은 정자이다. 처음에는 영하정이라 이름지었다가, 후손들이 ○○○이라고 이름을 바꾸었다. 양사형은 조선 선조 21년(1588)에 문과에 급제하여 영광군수, 병조정랑을 지냈으며, 임진왜란 때에는 의병을 일으켜 큰 공을 세우고 선무원종공신이 되었다. 죽은 뒤에는 승정원도승지에 봉해졌으며, 순창의 화산서원에 신주를 모시고 있다. 건물은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"어은정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661765.jpg"},{"q":"원형 형태의 ○○○○는 이면에 10cm 폭 가량의 가장자리를 남겨놓고 가운데가 뚫려있어 마치 징과 같은 모양이다. 반자 표면은 3조의 돌기대로 구획되어 있는데, 내구는 타격하는 부분이라 많이 마모된 상태이다. 전면 가장자리에 약 10cm의 보수흔이 있으며, 측면에는 파손된 구멍자국이 보인다. 반자 앞면은 3조의 돌기대를 同心圓圈으로 둘러 內區·中區·外區로 구획되어 있다. 3조의 돌기대는 표면에서 융기되어 뚜렷하게 도드라져 있다. 內區와 中區는 문양이 없으나, 外區는 직경 7.4cm 크기의 梵字揷入蓮瓣圓文이 일정한 간격을 두고 5군데 시문되어 있다.","a":"남해용문사청동반자","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665556.jpg"},{"q":"○○○란 임금이나 공신의 평생업적을 기록하여 무덤가에 세워두는 것으로, 조선 영조 때 오위도총부를 지낸 ○○○의 생애와 공적을 기리고 있다. 일명 ‘거북비’로 통하는 이 비는 거북받침돌 위에 비몸을 세우고, 지붕돌을 얹은 모습으로, 조선 중기 이후의 수법을 잘 보여주고 있다. 받침돌의 거북은 머리가 거의 용의 머리에 가까우며 입에 여의주를 물고 앞으로 고개를 한껏 내밀고 있다. 다섯 발가락이 표현된 두 앞발은 아랫돌을 꼭 누르고 있는 모습인데, 전체적으로 강한 움직임이 느껴진다. 정교하게 조각된 지붕돌은 네 처마선이 부드러운 곡선을 그리며 위로 들려있다.","a":"화산군 이연 신도비","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636128.jpg"},{"q":"○○○○○ 건물은 1905년에 호주장로교 선교회에 의해 건립된 건축물이다. 건물은 서양식으로서 전국적으로 지금까지 남아 있는 유례가 드물고 비교적 원형을 잘 보존하고 있을 뿐 아니라, 비례와 균형미가 돋보이는 휼륭한 건축물로서 우리나라 초기 학교 건물로는 손꼽을 만큼 희소가치를 지니고 있어 건축사적으로 매우 중요한 자료이다. 또한 부산·경남지역 최초의 신여성 교육기관으로서, 그 동안 이 건물이 교육시설로서 맡아 온 역할과 기독교의 전래과정 등을 고려할 때 역사적·교육사적으로도 가치가 있는 문화유산으로 평가된다.","a":"부산진일신여학교","c":"시도기념물","nc":"","r":"부산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645255.jpg"},{"q":"○○○는 지은 시기를 정확하게 알 수 없으나 불교를 전파한 마라난타가 세웠다는 설과 각진국사가 세웠다는 설이 전한다. ○○○는 교육을 위한 강당 건물이다. 대개 절의 중심 공간으로 들어갈 때 누(樓) 아래로 드나드는 문루인 경우가 많은데, 화엄사의 보제루와 이곳 ○○○가 낮은 중층을 이루어 건물의 모서리로 돌아가게 하였다. 절의 강당은 초기에는 대웅전 뒤에 있었으나 고려 이후부터는 대웅전 앞뜰에 설치하였는데 ○○○의 경우도 마찬가지이다. 건물의 규모는 앞면 5칸·옆면 4칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다.","a":"불갑사만세루","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662153.jpg"},{"q":"선조 37년(1604)에 가의대부 ○○○를 자헌대부인 3등공신으로 한 계급 특진시키고 포상한 교서이다. 당시의 공신은 1등 2인, 2등 31인, 3등 53인이었으며, ○○○는 3등공신 53인중 23번째에 수록되어 있다. 이것은 의주까지 선조를 호종했던 공신들에 대한 포상 및 임진왜란 이후의 공신들의 변화상 등을 살필 수 있는 귀중한 사료로 평가된다.","a":"김양보 호성공신록","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636265.jpg"},{"q":"향로란 절에서 마음의 때를 씻어준다는 의미를 가진 향을 피우는데 사용한 도구를 말한다. 입 주위에는 넓은 테를 가지고 있으며, 사발모양의 몸통과 나팔모양의 받침을 한 전형적인 향로의 모습을 하고있다. 몸통에는 卍자와 톱니바퀴 모양 속에 범자를 새겼고, 아래에는 연꽃잎을 늘어놓아 종교적인 분위기를 연출하였다. 받침대는 밑이 넓고 위가 좁아진 나팔형으로 안정감을 준다. 몸통과 입 주위 넓은 테에 화려한 문양은 피하고, 담담한 장식으로 우아함을 표현하였고, 높이와 너비의 비례가 적당하여 안정된 느낌을 준다.","a":"선암사금동향로","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639844.jpg"},{"q":"충북 청원군 문의면의 대청댐 수몰지구에 있던 것으로 전해지며 국립중앙과학관에서 구입한 것이다. ○○○○○의 앞면 윗부분에는 천문도(天文圖)라는 글자가 전서체로 크게 새겨져 있으며 그 아래에 2개의 큰 원을 동심원으로 그려서 테두리로 삼고 그 안에 주로 겨울철과 봄철에 보이는 30개의 서양 별자리를 새겨놓았다. 묘사된 별자리의 모양은 현대의 별자리와 같으며 정확하게 위치를 묘사하고 있지만 별의 밝기에 따라 별의 크기는 구분하지 않고 있다.","a":"석각천문도","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023092115595800.JPG"},{"q":"방형의 이중 기단 위로 3층의 탑신을 갖춘 석탑이다. 하층기단은 지면에 갑석만 노출되어 있고, 상층기단은 투박하게 다듬은 면석 모서리에 측면 기둥인 우주(隅柱)를 표현했다. 두꺼운 갑석 윗면에는 고려 시대 석탑에 자주 사용된 복련(覆蓮) 형식의 연잎 문양을 조각했고, 중앙에 사각형 탑신 받침을 낮게 표현했다. 탑신석과 지붕을 모방한 옥개석(屋蓋石; 석탑이나 석등 따위의 위에 지붕처럼 덮은 돌)은 각기 1매의 석재로 이루어졌다. 탑신은 상층기단과 유사한 높이로 제작됐지만, 2층 이상부터 급격히 축소되어 고려 석탑 특유의 조형미를 보여준다.","a":"안성죽산리삼층석탑","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637464.jpg"},{"q":"대구광역시 동구 ○○○ 암벽에 조각되어 있는 ○○○○상이다. 민머리 위에는 상투 모양의 머리묶음이 커다랗게 솟아있고, 귀는 길게 늘어져 있다. 불상의 어깨는 자연스럽게 처리되었고, 단조로운 옷주름이 전면을 장식해 입체감을 주고 있다. 오른손은 밑으로 내려 가볍게 옷자락을 잡고 있고, 왼손은 가슴 아래로 올려서 ○○○○의 상징인 구슬 모양의 약그릇을 들고 있다. 풍화로 인한 마멸 때문에 선명하게 보이지는 않지만 전체적인 표현에서 당나라 풍의 훌륭한 용모가 엿보이는 불상으로, 신라의 기법에서 고려로 전환되는 마애불의 변화를 이해하는데 좋은 작품으로 평가되고 있다.","a":"신무동삼성암지마애약사여래입상","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636879.jpg"},{"q":"갑사는 백제 구이신왕 원년(420)에 아도화상이 처음 지었고, 통일신라 문무왕 19년(679)에 의상이 고쳐 지었다고 한다. 그 뒤 고려시대와 조선시대를 거치면서 여러 차례 고치고 넓혀 지어 오늘에 이르고 있다. 삼성각은 칠성·산신·독성의 삼성을 모신 곳이다. 건물 이름이 삼성각 인 이유는 모두 불교 밖에서 수용한 신이기 때문에 전이라 하지 않고 각이라 한다. 칠성은 도교의 북두칠성이 불교화한 것으로 수명장생을 주관하는 별이다. 산신은 우리 민족 고유의 토속신으로 호랑이와 더불어 나타난 만사형통의 신이며, 독성은 혼자 깨달은 성자를 말한다.","a":"갑사삼성각","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660957.jpg"},{"q":"함성중학교에 있는 통일신라시대의 석탑이다. 원래 여항면 주서리 주리사터에 있던 것을 일제시대 때 면사무소로 이전하였다가, 광복 후 다시 이 곳으로 옮겨온 것이다. 기단(基壇)에 네 마리의 사자를 배치한 것이 일반 석탑과는 다른 독특한 모습이어서, 바닥돌 위에 얹힌 지붕모양의 돌 위로 네 마리의 사자를 올리고 그 위로 5층으로 보이는 탑신(塔身)을 쌓았는데, 탑신의 몸돌 하나가 없는 상태이다.","a":"함안 주리사지 사자석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641346.jpg"},{"q":"『○○○○○』은 조선시대 영남사림학파의 영수인 ○○○의 시문집 책판이다. ○○○은 조선 전기의 문신으로 1459년 문과에 급제하여 홍문관제학, 공조 ·이조참판 등 여러 벼슬을 거쳤다. 문장과 역사에 뛰어나 조선시대 도학(道學)의 정수를 이어가는 중추적 구실을 하였다. 이 문집은 성종 24년(1493)에 ○○○의 조카 장중진이 최초에 작성된 원고를 모아 ○○○의 문도였던 조위가 편집을 하였으나, 미처 간행하지 못하고 무오사화로 인해 모두 소실되고 말았다. 다시 장중진이 그 나머지 글을 모아 중종 12년(1517)에 선산에서 ○○본으로 간행하였다.","a":"김종직 점필재문집 및 이존록 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641782.jpg"},{"q":"강원특별자치도 원주시 소초면 ○○○ 신양 마을 뒤의 야산 바위에 선으로 조각한 3○○○이 있다. 연꽃무늬 대좌(臺座)의 중앙에 본존불이 있고 양 옆에 협시보살이 서 있다. 얼굴 부분은 모두 마모가 심하여 그 모습을 전혀 알아볼 수 없다. 양 어깨에 걸친 옷자락에는 굵은 선으로 표현된 옷주름이 보인다. 손은 파손이 심하여 자세히 알 수 없으나, 왼손 검지를 오른손으로 감싸고 있는 것으로 보아 비로자나불을 형상화한 것으로 보인다. 양쪽의 보살상은 각각 둥근 머리광배를 갖고 있다.","a":"원주수암리마애삼존불상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638160.jpg"},{"q":"갑사 동쪽 계곡 약 100m 지점의 자연 동굴안에 있는데, 원래는 갑사 뒷산의 사자암에 있었던 것이라고 한다. 머리에는 상투 모양의 머리묶음이 큼직하고 얼굴은 긴편이다. 양 어깨에 걸쳐 입은 옷은 가슴을 약간 노출시키고, 무릎 아래까지 늘어져 있다. 가슴 아래로는 반원형의 옷주름이 표현되었고, 왼쪽 어깨 부근에서는 한 가닥의 주름이 어깨너머로 넘어가고 있는 모습이다. 손모양을 살펴보면 오른손을 가슴까지 들어 손바닥을 밖으로 하고 왼손에는 약그릇을 들고 있어 ○○○○임을 알 수 있다. 전체적인 구성미와 조각수법으로 보아 고려 중기에 만들어진 불상으로 추정된다.","a":"갑사석조약사여래입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639087.jpg"},{"q":"세운 시기를 정확하게 알 수 없으나 100년 이상 되었다고 전하며 안채와 사랑채, 헛간채로 구성된 ㅁ자형 구조이다. 안채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 대청 기둥만은 굵은 원형의 기둥을 사용한 점이 특이하며 대청을 중심으로 오른쪽에 건넌방을 두고 왼쪽으로 안방과 부엌을 직각으로 두었다. 사랑채는 앞면 3칸·옆면 1칸 규모에 一자형 평면을 갖추고 있다. 마루방·사랑방·대문으로 구성되어 있는데 방의 앞쪽에는 넓은 툇마루를 설치하였다. 대문 왼쪽에는 2칸 사랑방을 배치하였고 방 앞면에는 툇마루를 놓았다.","a":"영월 북쌍리 고택","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660462.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. 이 부도는 국태민안(國泰民安)을 비는 사찰인 전국의 3안국(지리안국, 서산안국, 금산안국) 중 지리산의 안국사에 있는 것으로, 명당의 혈(血)에 해당하는 곳에 자리잡고 있어 더욱 중요성을 띤다. 전체적으로 8각을 기본형태로 하고 있으며, 아래·가운데·위의 3단을 이루는 기단(基壇) 위에 탑신(塔身)을 올리고 머리장식을 얹은 모습이다. 아래받침돌에는 복련(覆蓮:엎어놓은 연꽃무늬)을 두르고 윗받침돌에는 이와 대칭되는 앙련(仰蓮:솟은 연꽃무늬)을 장식하였다.","a":"함양 안국사은광대화상 승탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642277.jpg"},{"q":"금성면 하신리에 있는 어필각 근처에 세웠던 절이다. 일제시대 때 지금 있는 자리에서 약 100m 떨어진 곳으로 옮겼다가 1982년 다시 지금 있는 자리로 옮겨 지었다고 한다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. 안쪽은 하나의 칸으로 되어 있으며 바닥에는 우물마루를 깔았고, 뒤쪽 중앙에 불단을 만들고 비로자나불을 모시고 있다. 이 불상은 신음산 국사봉 아래에 있는 신안사에서 옮긴 것이라고 전한다.","a":"금산 대원정사","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661483.jpg"},{"q":"이것은 임진왜란 때 의병장으로 활약했던 죽천 박광전(1526∼1597)의 시문집을 새긴 목판과 초서를 새긴 유묵판이다. 박광전은 퇴계 이황의 문하에서 공부하였고, 감사를 지내던 유희춘의 추천으로 경기전참봉을 역임하였다. 임진왜란이 일어나자 임계영, 김익복 등과 보성에서 의병을 일으켰으며, 1597년 정유재란이 일어나 적이 호남을 침범하자 송홍렬, 박사길 등에게 격문을 보내 다시 의병을 일으켰다. 동복에서 적을 크게 무찔렀으나 병이 악화되어 죽었다. 그가 죽은 뒤 보성의 용산서원에 모셔졌으며, 시호는 ‘문강’이다.","a":"보성죽천선생문집및유묵목판","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662236.jpg"},{"q":"2기의 석탑은 상하층 탱주 2:2의 8세기 신라석탑 양식을 따르고 있으며, 탑신의 옥개받침이 모두 5단인 점, 각층 탑신 및 노반받침이 2단인 점 등 구성에 있어 통일성을 보이고 있다. 가장 주목되는 것은 초층 탑신에 새겨진 부조상이다. 탑 모두 중앙에 커다란 문비를 두고 좌우에 문을 지키는 수호신인 권법형 금강역사를 새겨 넣었다. 조각 구성은 같지만 세부표현에 있어 차이가 있다.","a":"간월사지 남‧북 삼층석탑","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019011613272800.jpg"},{"q":"구이면 화원마을과 상하보마을을 잇는 고덕산 능선에 위치하고 있는 이 절터는 경복사 터로 추정된다. 경복사는 고구려의 보덕화상이 국가가 도교를 받들고 불법을 믿지 않아 백제로 옮겨 온 이후에 지어진 사찰로서 조선시대에는 36본사의 하나였다고 전한다. 임진왜란 이후까지 지속되다가 없어졌는데 그 시기는 정확히 알 수 없다. 경복사터에는 석축이 비교적 잘 남아 있고 삼국시대에 해당하는 유물이 많이 출토되었다.","a":"경복사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653715.jpg"},{"q":"조선 말기 성리학자였던 화서(華西) ○○○선생이 태어나고 자란 곳이다. 이 집이 위치해 있는 벽계마을은 벽진 이씨의 동성촌으로 ○○○○○ 생가 외에도 노산사(蘆山祠)가 있어 선생의 높은 학식과 유학을 전승하고 있다. ○○○의 고조 대에 벽계마을에 들어와 살기 시작했으며, ○○○의 부친이 생가의 안채를 약 200여 년 전에 건립한 것으로 전한다. 현재 가옥의 배치는 ‘ㄱ’자형의 안채와 ㄷ자형의 사랑채가 가운데 담을 두고 가로로 긴 ‘ㅁ’자형을 취하고 있다. 사랑채는 1994년에 새로 건립한 것이며, 가옥 남쪽의 강당도 최근에 건립한 것이다.","a":"이항로선생생가","c":"시도유형문화유산","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637533.jpg"},{"q":"○○○ 가옥이 있는 지역은 비룡소(飛龍沼)라 불리는 지역으로 5대조가 입향하여 건축하였다고 전해지며(약 300여년) 장신리 일대에 집성촌을 이루고 있다. 장신리 비룡소 마을 초입에 위치하며 가옥 외부로 담장이 둘러져 있으며 1980년대 복원한 솟을대문이 있다. 담장 내에 안채(초가)와 창고와 현대식 슬라브 주택이 있으며 집 앞으로 도로와 농지가 펼쳐져 있다.","a":"보은 박기종 고가","c":"시도민속문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658239.jpg"},{"q":"봉림사가 소장중인 불교전적류 모두 8건으로 각각의 명칭은 ○○○○○제1, ○○○○○제3,4, ○○○○○제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, 불정심관세음보살대다라니경, 월인석보제21(상), 불설대보부모은중경이다. 구마라습이 지은 ○○○○○ 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"묘법연화경 권제사~칠","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642613.jpg"},{"q":"○○○○은 ○○○도 수군의 총 지휘자가 머물던 진영(鎭營)으로, 원래는 부산포에 있었다가 세조때(1459) 울산 개운포(開雲浦)로 옮겼다가 다시 임진왜란 직전에 동래 남촌(수영동)으로 옮겼다고 하는데 그 연대는 확실하지 않다. 인조13년(1636) 사천(絲川, 수영천)의 홍수로 선창의 수로가 매몰되어 뱃길이 통하지 않아 다시 감만이포로 옮겼으나, 감만이포는 왜관과 가까워 군사기밀이 누설될 우려가 있다 하여 효종 3년(1652) 다시 부산포로 옮겨져, 고종 31년(1894) 군제개혁으로 수영이 폐지될 때까지 사용되었다.","a":"경상좌수영성지","c":"시도기념물","nc":"","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644945.jpg"},{"q":"제주도의 민가 가운데 기와집은 매우 드믈다. 관리들의 주거지인 묵은성과 연육포구인 화북,신촌, 조천에 몇 채가 산재했을 정도였다. 1904년 건축하여 3대째 내려오는 이 집은 제주 민가의 발전형식 중 대표적인 예라 볼수 있다. 먼문간과 안거리만 기와집이고 밖거리와 모커리는 초가로 마당을 중심으로 ㄷ자형 별동으로 배치시킴으로써 제주의 전통 주거형식의 바탕에다 한본토의 상류주택이 지닌 남성공간인 사랑채의 기능을 접합된 형식을 보여준다.","a":"김석윤가옥","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659222.jpg"},{"q":"○○○○의 정절을 기리는 열녀문이다. 추사 김정희의 증조할머니이자 조선 영조(재위1724∼1776)의 둘째딸인 ○○○○는 남편인 김한신이 38세의 나이로 세상을 떠나자 그 슬픔을 이기지 못하여 음식을 입에 대지 않았다. 아버지 영조의 만류에도 불구하고 슬픔을 이겨내지 못한 옹주는 결국 세상을 떠났다. 영조는 남편에 대한 옹주의 정절을 칭찬하면서도 자신의 뜻을 따르지 않은데 대한 아쉬움 때문에 열녀문을 내리지 않았다. 지금의 열녀문은 훗날 정조(재위 1776∼1800)가 내린 것이다.","a":"화순옹주홍문","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639078.jpg"},{"q":"조선 제25대 왕인 철종(재위 1849∼1863)이 왕위에 오르기 전에 살던 집으로 철종이 왕위에 오르자 ○○유수 정기세가 건물을 새로 짓고 ○○○이라 이름을 붙였다. 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이고, 기둥 머리에서 보와 도리가 직교하여 직접 결구되는 민도리양식이다. ○○○은 창덕궁의 연경당, 낙선재와 같이 살림집의 유형을 따라 지어져 소박하고 순수한 느낌이 든다. 경내에는 철종이 살았던 옛 집임을 표시하는 비석과 비각이 있다.","a":"강화 용흥궁","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637039.jpg"},{"q":"경상북도 ○○시 화서면 ○○○ 국도변에 서 있는 높이 230㎝의 보살상으로, 넓적한 1매의 화강암에 돋을새김 하였다. 머리에는 3면보관을 쓰고 있으며, 관에는 작은 부처 3구와 관대(冠帶)장식이 돋을새김되어 있다. 얼굴은 마멸이 심하나 윤곽이 풍만하고 이목구비가 반듯하다. 양 어깨에 걸친 옷은 옷주름이 간결하고 두껍게 표현되어 있다. 불신의 뒷부분에는 불꽃무늬가 새겨진 둥근 형태의 머리광배와 배(舟)모양의 몸광배를 1줄의 굵은 선으로 구분했다. 간결하면서도 장식성이 적고 둔화된 표현 양식으로 보아 고려 전기에 만들어진 것으로 추정된다.","a":"상주 신봉리 석조보살입상","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662642.jpg"},{"q":"○○○○○은 흔히 법화경(法華經)으로 불리며, 화엄경(華嚴經)과 더불어 한국 불교의 근본 경전 중 우리나라에 유포된 불교 경전 가운데 가장 많이 간행된 경전이다. ○○○○에서 소장하고 있는 ○○○○○은 인조 10년(1632) 삭령 용복사(龍腹寺)에서 간행된 7권 3책과 인조 27년(1649) 양산 통도사(通度寺)에서 간행된 7권 3책 등 총 14권 6책의 목판본으로서 간행된 연도와 간행처가 명확하여 수많은 ○○○○○의 간행 내역 등을 밝히는데 표식이 되는 자료이다.","a":"내원정사 묘법연화경","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636684.jpg"},{"q":"조선 중기의 무신 ○○○ 장군의 묘이다. 1587년(선조 20)에 남해안에 출몰한 왜구를 토벌하는 데에 큰 공을 세웠다. 이후 왜구가 다시 흥양에 침입하자 출병하여 손죽도 해상에서 적과 싸우다 전사하였다. 묘역은 그의 부인인 경주 김씨(慶州金氏)·용인 이씨(龍仁李氏)와 함께 매장된 삼분(三墳 ; 봉분이 3개인 무덤)의 형태이다. 그 중 장군의 봉분은 중앙에 있는데, 시신을 수습하지 못하여 옷으로 대신하였다고 전한다. 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)는 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이며, 후대에 세워진 것이다.","a":"이대원장군묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646111.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 원래 삼봉산 기슭에 있었는데, 조선 선조 38년(1605)에 대홍수로 향교가 없어져 몇 차례 옮겨 지었다가 영조 8년(1732) 지금 있는 자리에 세웠다. 대성전과 동·서무를 먼저 완성하였고, 그 다음해 학생들의 교육 공간인 명륜당과 부속 건물을 완성하였다. 1960년 대성전을 새롭게 단장하고 명륜당과 다른 건물은 그 이후에 보수하였다. 배치는 대성전 앞 양쪽에 각각 동무와 서무가 있다.","a":"정선향교","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660509.jpg"},{"q":"파평 윤씨 시조인 윤신달(893∼973)의 묘를 관리하기 위해 세운 재실이다. 그는 어려서부터 학문과 무예에 뛰어났고 장성한 뒤에는 고려 왕건을 도와 고려를 건국하고 나라의 기틀을 마련하는데 큰 공을 세웠다. 이 건물은 영조 27년(1751) 그의 28대손인 윤광소가 안동부사로 재임할 때 세운 것으로, 영조 38년(1762) 26대손인 윤동도가 경상감사로 있으면서 보수하고 안동부사였던 윤성대가 땅을 넓히고 고쳐 지었다. 앞면 6칸·옆면 4칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"봉강재","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662823.jpg"},{"q":"이 불상은 대좌와 보병, 보관까지 한 개의 돌로 조성한 관세음보살좌상이다. 상호는 원만상(圓滿像)이며 백호를 수정으로 감장(嵌裝)하였다. 보관은 간결하고 소박하나 법의(法衣)의 유려함이 돋보인다. 두 손은 큼직한 보병을 받들고 있어 관세음보살상임을 알 수 있는데 조선후기 불상으로는 보기드문 예이다.","a":"포항 대성사 석조관음보살좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663609.jpg"},{"q":"○○○은 돌이나 부모 회갑에 다복장수(多福長壽)를 기원하며 여러 가지 전서(篆書)를 변형하여 백가지 글자로 수(壽)자와 복(福)자를 쓴 것으로 이를 바탕으로 자수병풍을 만든 일종의 기원문이다. 또한 글자는 완전한 전서가 아니고 도안화하여 조자(造字)되거나, 파자(破字)하여 재구성하였다. 현재 ○○○ 병풍은 위당 김문제(韋當 金文濟)가 쓴 백수백복도를 비롯하여 국립민속박물관에서 소장하고 있는 ○○○자도병, 백수백복도수병 등이 있다. ○○○ 수복병풍은 조선 말기 불교에 뜻있는 궁인(宮人)이 제작하여 발복 청원의 뜻으로 ○○○에 공양한 것으로 보인다.","a":"범어사자수수복문병풍","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659398.jpg"},{"q":"이 성은 온양읍 동상리 상서마을의 북쪽 비옥산 산정에 위치하여 동상리 성지라고도 부른다. 체성은북쪽~남동 방향이며 남쪽으로 회야강과 남창지역을 관망하기에 좋다. 성벽은 길이 500m, 높이 150cm 정도 남아 있는데, 평면은 원형이다. ○○○○은 자연석을 가공하여 내탁(성벽의 안팎을 모두 수직에 가까운 석벽으로 쌓는 방법) 수법으로 쌓은 성인데, 주변에는 하산 봉수대, 서생포 만호진성, 운화리 성지 등이 옛 유적이 분포하고 있어 동남해안 방어에 중요한 역할을 하였을 것으로 짐작된다.","a":"비옥산성","c":"문화유산자료","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659801.jpg"},{"q":"조선 선조~인조 연간의 문신이자 한문학의 대가로 칭송되었던 신흠(申欽, 1566∼1628) 선생의 묘이다. 신흠 선생은 장중하고 간결한 성품과 뛰어난 문장으로 선조의 신임을 받았고, 특히 외교문서의 제작과 각종 의례문서의 제작에 뛰어난 재능을 발휘하였다. 묘역은 부인 전의 이씨(全義李氏)와 합장한 단분(單墳 ; 하나의 봉분)의 형태이다. 묘제(墓制)는 비교적 원형이 유지되고 있으며, 석물은 대부분 옛 석물이다. 봉분 앞에는 묘표·혼유석·상석·향로석을 차례로 조성하였다.","a":"신흠묘역및신도비","c":"시도기념물","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646761.jpg"},{"q":"이선제·이조원·이중호·이발·이길 등 5현의 학문과 덕행을 추모하기 위해 세운 서원이다. 필문 이선제(생몰년 미상)는 조선 전기의 문신으로 호조참판과 예문관제학 등을 역임하였다. 『세종실록』편찬과 『고려사』의 내용 중 사실과 다른 점을 고쳐서 편찬하는 일에 적극 참여하였다. 이조원·이중호·이발·이길 등은 모두 이선제의 자손으로 여러 벼슬을 하였던 분들이다. 인조 2년(1624)에 세운 이 서원은 고종 5년(1868)에 흥선대원군의 서원철폐령으로 폐쇄되어 1901년에 임시로 단을 세워 제사를 지내오다가 1919년에 복원하여 오늘에 이르고 있다.","a":"수암서원","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654073.jpg"},{"q":"○○○은 충성심을 고취시키기 위하여 중국 송나라의 신하 ○○의 행적을 그림을 그려 만든 것으로서, 우리나라에서는 조선 선조 17년(1584)에 간행되었으나 임진왜란으로 없어지고 숙종 35년(1709)에 다시 펴 내었으며 영조 45년(1769)에 조익도의 집에 있던 것을 또다시 펴내게 되었다. 이것은 책의 재간 과정과 판화의 예술수준을 알 수 있는 학술적인 자료이다.","a":"악비 정충록","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642295.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 7년(1407)에 처음 지었는데, 훗날 지금의 태안중학교 자리로 옮겨 지었다. 지금 있는 건물은 불타 없어진 것을 숙종 46년(1720) 지금의 자리로 다시 옮겨 지은 것이다. 제사지내는 공간인 대성전과 동무·서무, 교육 공간인 명륜당, 학생들의 기숙사인 동재·서재, 내삼문과 외삼문 등의 건물이 남아 있다. 대성전 안쪽에는 공자를 비롯하여 중국과 우리나라 성현들의 위패를 모시고 있다.","a":"태안향교","c":"시도기념물","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653020.jpg"},{"q":"조선 태종이 보관해오던 거문고를 그의 여섯째 아들인 희녕대군에게 주었다고 하여 ‘○○○’이란 이름이 붙은 거문고로, 현재는 전주이씨 희녕군파의 가보로 내려오고 있다. 길이 120.3㎝, 너비 15.9㎝, 두께 12㎝로 작은 편이며, 오동나무와 밤나무로 만들었고, 부재료로 명주실과 소가죽이 사용되었다. 명주실을 꼬아 만든 6줄의 현을 술대로 쳐서 소리를 내도록 하였다. 이 거문고에는 섬세한 솜씨로 조각한 문양이 있고, 전체적인 모양새가 매우 아름답다.","a":"희령군 어사금","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640769.jpg"},{"q":"율곡 이이의 유물인 『격몽요결 』과 『해동연원록 』등을 소장하기 위해 세운 서원이다. 이이(1536∼1584)는 조선 중기 학자이며 정치가로 퇴계 이황과 쌍벽을 이루는 대학자이다. ○○○○은 영조 3년(1725)에 지금 있는 자리에서 4㎞ 정도 떨어진 향옥동에 세웠으나, 흥선대원군의 서원철폐령으로 폐쇄되었던 것을 고종 6년(1867)에 마을 동쪽 200m 지점에 다시 세웠다. 서원의 건물로는 강당, 소원사, 내삼문, 외삼문, 관리사 등이 있다. 강당은 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"합천 옥계서원","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663949.jpg"},{"q":"고려말 충신인 상촌 김자수를 제사지내는 재실로 조선 말기에 지어졌으며, 원래 노산동에 있었으나 안동댐 건설로 인해 1973년 이곳으로 옮겨졌다. 경주 김씨 세력이 커서 김씨골로 알려져 있는 금곡동에서 태어난 상촌은 고려말 나라의 정세가 어지러워지자 벼슬을 버리고 고향인 안동에 내려와 살았다. 조선이 개국된 뒤 태종(재위 1400∼1418)이 불렀으나 나가지 않고, 결코 무덤을 만들지 말라는 유언을 남기고 자결하였다. 이숭인·정몽주와 친분이 두터웠으며, 문장이 뛰어나 그의 글이 『동문선』에 실려있다.","a":"추원재","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640296.jpg"},{"q":"시남 유계(1607∼1664)를 기리고 후학을 양성하기 위해 세운 서원이다. 유계는 조선 중기 문신으로 예에 관해 정통한 학자이다. 김장생의 제자이며 충청도 유림의 오현 중 한 사람으로 불린다. ○○○○은 숙종 13년(1687)에 세워 숙종 23년(1697)에 임금으로부터 ‘칠산(七山)’이라는 현판을 받아 사액서원이 되었다. 그 후 흥선대원군의 서원철폐령으로 폐쇄되었다가 1967년에 복원하였다. 서원 경내에는 제사 공간인 사당과 공부하는 공간으로 강당, 장판각 등이 있다.","a":"칠산서원","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661052.jpg"},{"q":"이 영정(○○○○○영정)은 좌안 7분면의 바닥가부좌상으로, 운보문의 충진구도 벽면과 화문석의 이단구도를 배경으로 왼손에 불자를, 오른손엔 염주를 쥔 채 여유 있게 가부좌를 하고 있다. 화면 향좌측에 주지묵서의 ‘○○○○○대사지진(永閑堂宗悅大師之眞)’ 화제가 있고 화면 밖 하단에 ‘가경 을축 오월일 독판 시주 윤옥 비구 양공 제한(嘉慶 乙丑 五月日 獨辦 施主 閏玉 比丘 良工 濟閑)'의 묵서화기가 있다. 이로서 1805년 제한(濟閑)이 제작했음을 알 수 있다. 화면크기는 85.9cm, 세로 126.3cm이다.","a":"영한당 종열 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642988.jpg"},{"q":"이 불상은 발목 부분이 흙에 묻혀 있어 전체 높이는 정확히 알 수 없으나, 드러난 불신(佛身)의 높이가 1.95m에 이르는 대형 불상이다. 석불은 전체적으로 마모가 심한 상태이지만, 조각선이 깊어 대략적인 형상은 파악할 수 있다. 먼저, 머리에는 크게 표현된 육계(肉髻, 상투 모양의 머리)가 있으며, 얼굴은 전체적으로 풍만한 형태를 띠고 있다. 옷차림은 양 어깨를 덮는 통견(通肩)으로, 가슴 아래로 넓은 U자형의 옷주름이 흘러내리다가 다리 부분에서 두 가닥으로 갈라진다.","a":"논산덕평리석조여래입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639096.jpg"},{"q":"○○○○은 선조3년(1570) 간재 이덕홍이 세운 오계정사의 후신으로 정사가 임진왜란으로 피폐해지자 선조33년(1600)에 큰아들인 이시가 쌍계마을로 이건하고 한호의 글씨로 관성재,관서헌의 편액을 걸었다. 현종6년(1665)에 선생의 위패를 봉안하고 道存祠를 건립하였다. 1691년 ○○○○으로 승격하고 1699년과 1707년의 대홍수로 물길이 바뀌어 서우너의 침수 피해가 있자 현 위치로 이건하였다. 고종때 서원철폐령에 따라 훼철되었다가 1919년에 복향하였고 1978년에 道存祠를 재건하였다.","a":"오계서원","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663523.jpg"},{"q":"본래 제주시 서사가 지경의 법화종 사찰에서 모셔왔다고 한다. 주지 스님의 증언에 의하면 1982년 이 사찰이 훼첼될 때 불단(佛壇) 밑에 방치되었던 ○○○○을 수습하여 모시게 되었다는 비불(秘佛)과도 같이 귀중히 봉안하여 공개하지 않고 있었던 것을 최근에 김봉옥 선생의 주선으로 조사하게 되었다.","a":"월영사소장목조여래좌상","c":"문화유산자료","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666844.jpg"},{"q":"파사성 서쪽 능선의 남쪽 경사면의 바위에 새겨진 마애불이다. 왼쪽 눈과 콧망울 아래쪽, 입술 등 군데군데 표면이 떨어져나간 곳이 있다. 머리 오른쪽이나 왼쪽 어깨에는 잘못된 선을 수정한 곳이 보여 기량이 떨어지는 지방 장인의 작품으로 추정된다. 두광(頭光 ; 붓다의 정수리에서 나오는 성스러운 빛을 형상화한 것)은 이중의 동심원으로 지나치게 크고, 대좌(臺座 ; 불교존상을 봉안하여 올려 놓는 받침대)는 내부를 거의 직선으로 표현하여 연꽃잎으로 알아볼 수 없을 지경이다. 두 발은 법의 속에 감춰져 드러나지 않는다.","a":"양평상자포리마애여래입상","c":"시도유형문화유산","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637706.jpg"},{"q":"○○○ 선생의 본관은 영천이며, 자는 경부, 호는 대전이며, 세종 11년(1429)에 문과에 급제하여 집현전 박사를 거쳐 사정이 되고 1443년에 사은사의 서장관으로 명나라를 다녀와 주부가 되었음. 1448년에 지대구군사로 재직시 대구에 사창법을 시험적으로 시행했고 문종 때 장령을 지냈음. 정조 때 이조판서에 추증되었고 광주의 대치사 영천의 송곡서원 청안의 향사에 제향되고 있으며 시호는 충장공임. ○○은 총 87매이며 크기는 30×45cm로 박물관 선현유품실에 전시되어 있음.","a":"이보흠 대전실기 목판 및 교지","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642032.jpg"},{"q":"○○○ 상여는 ○○○ 마을에 전해지는 길이 2.2m, 폭 1m, 높이 1.5m의 조선 시대 후기 상여로 가마와 유사한 형태이다. 청룡과 황룡의 얼굴을 조각한 용수판과 봉황의 머리를 표현한 봉두, 용의 머리를 조각한 용두 등의 목조각품은 채색이 화려하며, 특히 용마루 위 해태를 탄 저승사자상은 조각이 정교하여 미술사적 가치가 높다. ○○○ 상여는 조선 시대 제26대왕 고종의 아들 완화군 이선(1868~1880)의 국장을 치르는데 사용하였다는 이력이 있으나 분명하지 않고 안면도로 낙향한 김병년(1855~1927)의 장례에 사용한 것은 분명하다.","a":"태안승언리상여","c":"문화유산자료","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661417.jpg"},{"q":"○○○는 고려 우왕 6년(1380) 운봉 황산에서 왜구를 크게 무찌른 이성계가 개선길에 잠시 머물렀던 곳이다. 이를 기념하기 위해 대한제국 광무(光武) 4년(1900)에 비석을 건립했는데, 태조가 잠시 머물렀던 곳이라는 뜻의 <태조고황제주필유지(太祖高皇帝駐蹕遺址)>라는 비문은 고종황제가 직접 쓴 친필을 새긴 것이다. ○○○는 이성계의 5대 할아버지인 목조(穆祖) 이안사(李安社)의 출생지라고 전해지는 곳이다. 전주 이씨들은 이안사 때까지 줄곧 이곳에서 살다가, 함경도로 이사했다고 한다.","a":"오목대이목대","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653348.jpg"},{"q":"온천약수가 나온 것을 기념하고 알리기 위해 세운 비이다. 자연스러운 돌의 형태를 그대로 유지한 채 앞·뒤·옆면만 평평하게 다듬었고, 앞면에 ‘○○○’라는 글씨를 큼지막하게 새겨 넣었다. 예산군에서는 1918년 덕산 지역에 온천을 개발하면서 그에 따른 부속건물 공사를 하였다. 그후 1947년에도 지하 180m까지 굴착작업을 진행하였는데, 이 때 온천약수가 나오자, 땅에서 나온 것이라는 의미로 약수의 명칭을 ‘○○○’라고 하여 새로이 건물을 짓고 이 비를 세웠다.","a":"덕산온천지구유","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661213.jpg"},{"q":"○○○○○에 보존되어 있는 그림으로, 불경 중 하나인 『우란분경』의 내용을 그림으로 설명한 것이다. 비단 바탕에 채색하여 그렸으며 가로 218.5㎝, 세로 225㎝의 크기이다. 화폭의 윗부분에는 극락의 아미타여래 일행이 지옥 중생을 맞이하러 오는 장면, 즉 아미타불·관세음보살·대세지보살 등 6여래와 지장보살이 지옥의 중생을 극락으로 인도하기 위해 온 모습과 이들을 정토로 인도하는 인도왕보살 및 수레를 그려 놓았다. 이들 주위로는 오색 구름이 둘러싸여 천상세계와 지옥세계를 구분하는 역할을 하고 있다.","a":"은해사백흥암감로왕도","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641045.jpg"},{"q":"신음산 자락에 위치한 ○○○는 신라 진평왕 5년(583)에 무염선사가 창건한 것으로 알려져 있으나 확실하지 않다. ○○○라는 절의 이름은 신라의 마지막 왕인 경순왕(재위 927∼935)이 \"주위 산수의 경치가 아름답고 조용하여 몸과 마음이 편안하다\"고 한데서 비롯되었다고 한다. 원래 ○○○에는 ○○○·극락전·진향각·요묵당 등이 있었으나, 현재는 ○○○·극락전만 남아 있다. 내부에는 석가모니가 설법한 진리를 형상화한 비로자나불을 본존으로 약사여래·석가여래불을 봉안하고 있다. 정면 5칸 · 측면 3칸 규모의 맞배지붕 건물로, 내부의 3칸에는 후불벽과 불대단을 조성하였다.","a":"신안사 대광전","c":"시도유형문화유산","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639002.jpg"},{"q":"1604년(선조 37) 호성공신(扈聖功臣)에 녹훈된 ○○○의 공신도상이다. ○○○은 정종(定宗)의 10번째 아들 덕천군(德泉君) 후생(厚生)의 현손이다. 1592년(선조 25) 임진왜란 당시 선조(宣祖)를 의주까지 호종한 공로로 1604년(선조 37) 호성공신 2등으로 녹훈되어 완양부원군(完陽府院君)에 봉해졌다. ○○○ 호성공신도상은 17세기 초반기에 제작된 공신도상 가운데 필치가 정밀하고 화격이 매우 높다. 공신도상의 기본 형태인 전신교의좌상(全身交椅坐像)에 공수(拱手) 자세를 취하였다.","a":"송암 이충원 영정","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023041309521300.jpg"},{"q":"취죽당 김응명(1593∼1647)과 그의 아들 운계 김주(1612∼1678)의 제사를 지내는 곳이다. 2채의 건물 중 본채는 ㄱ자형으로 되어 있고, 대문채는 앞에서 볼 때 사다리꼴을 한 우진각지붕으로 꾸몄다. 세운 시기를 정확하게 알 수는 없으나 1957년 새롭게 고쳤다. 원래는 순지리에 있던 것인데 운문댐 건설로 이 지역이 수몰되어 지금 있는 자리로 옮긴 것이다.","a":"원모재","c":"문화유산자료","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662906.jpg"},{"q":"화면의 중앙에 청색의 천공을 배경으로 하여 구름 속에 솟아오른 연화좌 위에 치성광여래가 앉아 있고, 좌우에 월광ㆍ일광보살이 시립하고 있으며, 본존의 두광 좌우에 太上老君과 開德眞君이 좌우대칭을 이루며 배치되어 있다. 9폭이 1조를 이룬 이 작품의 주조색은 주색ㆍ녹색ㆍ군청ㆍ황색ㆍ백색이며, 보관의 장식과 홀, 무릎 아래로 흘러내리는 장식, 성수의 머리 묶는 끈 장식 등에 금박을 사용하여 화려함을 더하고 있다. 이 ○○○은 주존으로 치성광여래탱 1위와 자미대제 삼태육성탱 1위, 칠원성군탱 7위를 포함하여 모두 9위의 완품이 갖추어진 수작에 속하는 ○○○ 작품이다.","a":"양산통도사극락암칠성탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642645.jpg"},{"q":"신도비란 왕이나 2품 이상의 공신들의 평생업적을 기록하여 그의 무덤 가까이에 세워두는 것으로, 이 비는 고려말·조선초의 유명한 문신인 ○○ 선생의 업적을 기리고 있다. ○○은 고려 공민왕 20년(1371) 문과에 급제한 후 성균학우를 시작으로 여러 관직을 맡아 보았다. 1392년 이성계가 조선을 세울 때 그를 도와주어 개국공신이 되었고, 태종 8년(1408) 태조가 죽자, 능을 지키는 관리가 되어 3년간 그의 능을 지켰다. 태종 16년(1416)에는 옥천부원군에 봉하여졌다. 일찍이 이성계와 사귀어 그에게 가르침을 주었고, 개국 후에도 여러 차례 왕에게 강론을 하였다.","a":"문희공 유창 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636280.jpg"},{"q":"\"전라남도 담양군 고서면 금현리는 원래 ○○○의 절터였는데, 1976년 터를 닦아 새로 사찰을 지었다. 옛 절터에 넘어져 있던 석불 2구를 일으켜 세워 법당에 모시고 있는데, 현재 법당 중앙에는 광배(光背)를 갖춘 ○○○○이 있고 그 옆으로 이 불상이 오른쪽을 보고 있다. 목 부분이 떨어져 나간 것을 시멘트로 붙여 놓았으며, 민머리 위에 솟아 있는 상투 모양의 낮은 머리묶음도 부분적으로 손상을 입었다. 얼굴도 많이 닿아서 자세한 기법을 볼 수 없지만 눈·코·입 등이 사실적으로 조각되어 원만한 모습을 보인다.","a":"영은사석불좌상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662085.jpg"},{"q":"통도사에 딸린 절인 ○○○○○의 옛 ○○○으로 사용하던 건물이다. ○○○를 세운 기록은 전하지 않으나 신라 때 세운 절이라고 전하며, 임진왜란 당시 승병활동의 거점이 되었던 절 중 하나이다. ○○○에서 1998년 새로이 ○○○을 신축함에 따라 이 건물은 지금 있는 자리로 옮긴 것이다. 앞면 3칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짜올린 익공 양식으로 비교적 간결한 구조를 보인다.","a":"대안동신흥사구대웅전","c":"문화유산자료","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659789.jpg"},{"q":"불신만 남아 있는 이 불상은 왼쪽 팔목의 보수를 제외하면 보존상태가 좋은 편이다. 신체에 비해서 큰 얼굴은 앞으로 숙여져 있으며 옷은 왼쪽 어깨만을 감싸고 있다. 손은 오른손 바닥을 무릎에 대고 손끝이 아래를 가리키고, 왼손은 손바닥을 위로 향하게 하여 배꼽 앞에 놓은 모습이다. 왼발을 오른쪽 넓적다리 위에 얹어 놓은 앉은 자세는 그 예가 드문 편이다. 평판적이고 굴곡이 없는 네모진 상체, 목에 있는 3개의 주름, 둔감한 옷주름선 등에서 도식화되는 경향을 보이는 고려시대 말기 불상으로 추정된다.","a":"괴산 봉학사지 석조여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638446.jpg"},{"q":"이 정려는 ○○○○○의 대표를 표창하라는 왕명으로 세워진 \"○○조봉대부형조정랑 겸 춘추관 기주관 ○○○ 려\"이다. 본시 태생지인 창원 지개동에 세워졌는데(1592)임란에 소실되어 이곳으로 이건 하였다(1634년) 공은 일찍 토계의 문도가 되어 경학을 강마하였으며 사마시에 합격하고 중시에 장원급제하여 형조정량으로 승천되었다. 천상을 당해 상례가 어김 없었고 모친을 지효로 섬기니 향리는 물론 ○○, 창원, 영천의 사림이 감복하여 순찰사가 그 효행을 나라에 장개하였다.","a":"밀양 조광익 효자 정려각","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665178.jpg"},{"q":"비슬산 ○○○는 통일신라 신덕왕 원년(912)에 보양국사가 처음 지었다고 전한다. 조선 세종 1년(1419)에 천일대사가 다시 지었고, 임진왜란으로 불탄 것을 여러 해에 걸쳐 다시 지었다. 이렇게 지어진 건물은 200여 칸이 넘고 승려도 500여 명이나 되는 큰 절이었다고 한다. 아미타불을 모신 ○○○은 영조 4년(1728)에 다시 지었다. 앞면 3칸·옆면 3칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 간결한 맞배지붕집이다.","a":"용연사 극락전","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636919.jpg"},{"q":"조선후기 문신 유회당 권이진(有懷堂 權以鎭, 1668~1734)의 문집을 인출하기 위해 만든 판목이다. 권이진은 송시열의 외손자로 1694년 문과에 급제하여 벼슬길에 올랐으며 1728년(영조 4) 호조판서가 되어 궁중에서 민간의 전답을 매입하지 말 것과 공물을 정액 이상으로 거두지 말 것 등을 건의했다. 유회당 판목은 순조 초(1807~1827)에 유회당의 증손자인 좌옹 권상서(左翁 權尙恕, 1767~1835)가 판각한 것으로 유회당 부속건물인 장판각에 246판 중 244판이 보관되어 있다. 재료로는 배나무와 소나무를 사용하였다.","a":"유회당판각","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101511045400.jpg"},{"q":"임진왜란 때 순절한 분들의 충렬(忠烈)을 기리어 당시의 격전지인 ○○읍성의 남문 밖 농주산에 세웠던 비로, ‘○○충렬비’라고도 부른다. 현재 비는 받침돌 위에 크게 훼손된 비몸을 세운 모습이다. 그 위에 얹었던 머릿돌을 옆에 따로 놓여 있다.","a":"동래 남문비","c":"시도기념물","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645049.jpg"},{"q":"○○○○○은 ○○○ 경재 응진전의 북동쪽 상부의 자연석으로 이루어진 석축 위에 위치하고 있다. 1709년에 지덕(地德)비보를 위해 석불입상(경상북도 문화유산자료)과 함께 조성된 비보사탑(裨補寺塔)이다. 비보사탑은 대개 통일신라시대와 고려시대에 집중적으로 조성되었다. 조선후기에 풍수적 지덕 비보를 위해 ○○○처럼 탑과 불상을 동 시기에 함께 조성한 예는 그리 많지 않다. 이 탑의 전체 높이는 2.85cm로, 단층 기단부와 3층 탑신부 그리고 상륜부로 구성되어 있다. 1층 탑신석 남면에는 ○○○○의 가장 큰 특징이라 할 수 있는 방형의 틀을 파서 불상을 새겼다.","a":"문경 김룡사 삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020041319325600.jpg"},{"q":"○○○○은 존재(存齋) 이휘일(李徽逸)의 증손인 냉천(冷泉) 이유원(李猷遠, 1695~1773)이 1720년경에 건축한 고택이다. 배치 구조는 트여 있는 구자형(口字形)이다. 정면에 중문칸을 중심으로 좌측으로는 외양간을 두고 우측으로는 사랑방 2칸을 두었다. 사랑방의 전면과 측면에는 쪽마루를 설치하였다. 안채는 2칸 대청을 중심으로 좌로는 상방과 안방을, 우측으로는 건넛방을 두었다. 안방의 전면에는 부엌을 두었다. 아래채는 고방 1칸과 온돌방이 위치한다.","a":"영덕오촌리냉천고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663540.jpg"},{"q":"조선 정조 21년(1797)에 무열공 배현경, 금헌 배정지, 정절공 배극렴을 모시기 위해 지은 사당으로 무열사라 사액하였다. 배현경은 고려 태조 때 무신으로 경주 사람이다. 궁예 때부터 활약했던 인물이며, 고려 건국에 큰 역할을 하였다. 이에 일등공신에 오르고 태조를 도와 후삼국 통일에 많은 역할을 하였다. 시호는 무열이다. 배정지는 고려시대의 무신으로 10세에 금위에 들어가 도지가 되었다. 그는 원나라에 들어가 원제로부터 용사라는 칭찬을 받고 백금을 하사 받기도 하였다. 배극렴은 고려말 왜구 토벌에 공을 세운 조선의 개국공신이다.","a":"나주무열사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654148.jpg"},{"q":"1910년대에 형성된 순천 선교촌에 남아 있는 2층 석조건물로, 1913년 건립되었고 코잇(Coit, Robert Thronwell, 한국명 고라복, ?-1932) ○○○와 관련이 있음. 이 가옥은 한국근대사회에서 전개된 기독교 선교활동의 한 모습을 보여주는 유구임. 특히 목포와 광주에 이어 순천에서 이루어진 선교활동을 위한 ○○○ 가옥으로서 그 형태와 내용면에서 의미가 크다.","a":"순천코잇선교사가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2025103117011690.jpg"},{"q":"｢妙法蓮華經｣은 ‘法華經’이라 약칭하기도 하며 天台宗의 根本經典으로 부처가 되는 길이 누구에게나 열려 있음을 基本思想으로 하고 있다. ｢華嚴經｣과 함께 우리나라 佛敎思想의 확립에 가장 크게 영향을 끼쳤으며 三國時代 이래로 가장 많이 流通된 佛敎 經典이다. 이 간본은 1561년(명종 16)에 간행된 목판본이다.","a":"묘법연화경 권6~7","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638872.jpg"},{"q":"이 건물은 근촌 ○○○ 선생의 고택으로 안채는 정면 4칸, 측면 2칸의 팔각지붕으로 규모는 16.5평이다. 주초는 자연석을 그대로 사용하였고 기둥은 각주, 기단은 근래에 깬돌로 보수하였다. 사랑채는 정면 4칸, 측면 2칸의 우진각 지붕으로 건물 규모는 17평이다. 근촌 ○○○ 선생은 고종26년(1889) 1월28일 성내면 덕산리에서 태어나 여섯살때 부터 거유인 간재 전우의 문하에서 한문을 익히고, 열여섯 되던 해에 러일 전쟁이 일어나 망국의 을사보호조약이 체결되었다.","a":"백관수선생고택","c":"시도기념물","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653641.jpg"},{"q":"조선 중기의 무신인 석담(石潭) 유형(柳珩, 1566∼1615) 장군의 묘이다. 노량해전에서 전사한 이순신을 대신해 전투를 지휘하여 부산진첨절제사에 발탁되었다. 그 후 여러 관직을 거쳐 선조 35년(1602)에 충청·전라·경상 3도의 수군을 통제하는 관직에 올랐다. 묘역은 원형 단분(單墳 ; 하나의 봉분)의 형태이다. 봉분 정면 오른쪽에는 새로 세운 묘표가 있고, 봉분 앞으로 혼유석·상석·향로석이 차례대로 있는데 모두 현대에 세운 것이다.","a":"유형장군묘","c":"시도기념물","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646095.jpg"},{"q":"○○○ 大弘願殿에 봉안되어 있는 아미타구품탱은 阿彌陀極樂會上圖의 일종으로『阿彌陀經』을 바탕으로 하여 그려진 탱화이다. 즉, 극락정토의 모습을 조밀하고도 세밀하게 화면 전체에 묘사하고 있는 觀經變相圖인 것이다. 이 탱화는 현재 대홍원전 내에 마련된 불단 위에 액자 형태로 봉안되어 있으며, 최근에 탱화 앞쪽 사방 외곽에 다시 나무로 틀을 짜 놓은 상태이다. 따라서 화면 하단에 墨書되어 있는 畵記 부분이 틀 속에 가려져 있기에 그 내용을 자세히 파악할 수는 없다.","a":"밀양 표충사 아미타구품도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643078.jpg"},{"q":"○○○는 아도화상이 고구려 소수림왕 11년(381)에 세운 절로 정족산성 안에 자리잡고 있다. 대웅보전 앞 마당 바로 밑에 세운 ○○○는 기둥을 세워 지면과 사이를 두고 지은 누각이다. 지은 시기를 알 수 없으나 1748년(영조 24) 주지 초윤(楚允)과 화주인 보학(寶學) 등이 고쳐지었다고 하며, 1841년(헌종 7)에는 화주 연홍 등이 중건했다고 『○○○본말사지』에 명기되어 있다. 그 뒤 크고 작은 보수를 거쳐 오늘에 이르고 있다. 앞면 5칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"강화 전등사 대조루","c":"문화유산자료","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659540.jpg"},{"q":"정훤이 숨어 지내며 남은 삶을 보내던 곳이다. 정훤은 광해군의 포악한 정치에 휩쓸리기 싫어서 이곳에 내려와 정자를 지어 ○○○이라 불렀다. 건물은 앞면 4칸·옆면 2칸 규모로，지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞뒤에 퇴칸을 두었고 좌우 양쪽에 대청을 두었다. 뒤를 제외한 3면에는 난간을 둘렀다. 정자와 사당을 남북쪽에 앞뒤로 나란히 二자 모양으로 배치하였는데, 사당은 앞면 3칸·옆면 1칸 규모이며 지붕은 팔작지붕이다.","a":"진주 고산정","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663803.jpg"},{"q":"임진왜란시 의병을 일으켜 ○○수성(安東守城)에서 공을 세운, 대박 김철의 묘소를 보호하기 위해 세운 재실이다. 조선 중기에 세운 이 건물은 제사를 지내는 방인 정침을 중심으로 좌우에 건물을 두었고 앞쪽으로는 5칸의 누각이 설치되어 ㅁ자형 구조를 보여준다. 원래는 임하면 사의동에 있었으나 인하댐 건설로 1987년 이곳으로 옮겨 세운 것이다.","a":"안동 송석재사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658912.jpg"},{"q":"조선 후기 문신이며 성리학자인 갈암 이현일(1627∼1704) 선생의 종가이다. 선생은 조선 숙종 때 이조판서를 지냈고 영남학파의 거두로 퇴계 이황의 학통을 이어 받아 ‘이기호발설’을 지지하였다. 서인의 탄핵을 받아 귀양을 가기도 하였다. 저서로 『갈암집』과 『홍범연의』가 있다. 가옥은 경북 북부지역의 전통적인 ㅁ자 형태이다. 선생은 원래 영덕군 창수면 인량리에서 출생하고 자랐으나 선생이 40세 되던 해에 영양군 입암면 병옥리로 옮겼다.","a":"갈암종택","c":"시도기념물","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654538.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었고 봉수대는 산 정상에 설치하여 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. 이 연대는 남제주군 성산수산고등학교의 북쪽 밭에 있는데, 현재 많이 훼손되어 있다. 수산진에 소속되었던 이곳은 수산진 소속 별장 6명, 봉군 12명이 배치되어 교대로 지켰다. 동쪽으로 성산 봉수대를 거쳐 협자연대, 서쪽으로 종달 연대와 연결되어 있다.","a":"오소포연대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657857.jpg"},{"q":"○○○는 합천 해인사, 승주 송광사와 더불어 우리나라 3대사찰 중 하나로 경내는 크게 상로전, 중로전, 하로전의 3영역으로 나눌 수 있다. ○○○은 중로전에 있는데 고려 공민왕 18년(1369)에 지었으며, 조선시대 영조 1년(1725)에 청성대사가 보수해 현재에 이르고 있다. 앞면 3칸·옆면 3칸으로 지붕 옆모습이 사람 인(人)자 모양인 맞배지붕으로 되어있다. 지붕을 받치기 위하여 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식으로 매우 화려하다. 세부장식에는 용무늬를 많이 썼고 건물 앞면 중앙칸에 문짝을 달은 것이 특징이다.","a":"양산 통도사 용화전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641843.jpg"},{"q":"○○○○은 동강 김우옹 선생을 제사지내던 집으로 조선 영조 5년(1729)년에 지어졌다. 처음에는 청천서원이라는 이름으로 회연서원과 함께 성주지역의 중심서원이었으나 대원군의 서원 철폐령으로 철거 되었다. 그 후 동강의 12대 후손인 김호림에 의해 ○○○○으로 이름을 바꾸어 다시 지었다. 1910년에는 심산 김창숙 선생이 ○○○○을 성명학교라고 하고 애국계몽운동을 위한 학교로 활용되기도 하였고, 김창숙 선생이 한때 머물던 장소이기도 하다. 건물은 앞면 5칸·옆면 한칸반이고 지붕은 옆에서 보면 여덟 팔(八)자 모양인 팔작지붕이다.","a":"청천서당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640810.jpg"},{"q":"장흥 ○○○당은 원래 1906년 4월에 동학의 후예인 교구장 강봉수(姜琫秀) 등이 중심이 되어 ○○○인에게 모금운동을 전개하여 지어졌다. ○○○○○군교구역사〉와 교당 내부에 걸린 〈교구실기(敎區室記〉(1920년)를 통하여 당시 개축에는 전남의사원(全南議事員) 신명희(申明熙), ○○○구장 김재계, 수령 강봉수, 윤세현 등이 주도하였다는 것과 1917년(포덕오십육년정사(布德五十六年丁巳) 11월부터 한달여에 걸쳐 2,300원(圓)을 모금하여 1918년 2월 15일에 건축을 시작하여 6개월만인 8월 26일 준공한것 그리고 건축 실비가 1,600원이 들었다는 것을 알 수 있다…","a":"천도교장흥교당","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654372.jpg"},{"q":"원명 ○○○의 부친인 연채우(延采羽)〈延彩羽〉의 집으로, 독립애국지사 ○○○가 태어나고 성장한 ○○인 동시에 만년에 이곳에서 살다가 생애를 마친 집이다. ○○○는 1894년에 괴산군 도안면 석곡리에서 출생하여, 1919년 중국으로 망명하여 길림성 북로군정서 참모겸 서기로서 국권회복 운동을 하였다. 1919년 상해 임시정부 활동을 지원하였으며, 청년외교단<비밀조직> 활동으로 검거 투옥되었다. 이후 다시 망명하여 독립혁명당을 조직하였으며, 1937년 임시정부에서 활약 중 일본 관헌에 체포되어 징역 8년을 선고받고 옥고를 치렀다.","a":"증평 연병호 생가","c":"시도기념물","nc":"","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650983.jpg"},{"q":"○○○ 상부의 크기가 남북 30m, 동서 15m 정도의 넓이로 우리나라 ○○○ 유적 중에 가장 큰 규모이다. 바위에 새겨진 그림은 말굽형과 유사하게 생긴 도형, 새의 모양과 흡사한 도형, 윷놀이 말판과 흡사한 도형, 15cm 정도의 사람 발자국 등과, 이외에도 지름 20cm 내외, 깊이 10cm 내외의 큰 바위 구멍들이 있다. 이외에도 의식을 치르기 위한 것으로 추측되는 바위 홈들이 있다. ○○○ 유적 가운데 바위의 수평면에 대규모로 새겨진 형태는 이곳이 유일하며, 특히 말굽형태의 도형은 한국 ○○○의 원류를 추적할 수 있는 자료로 평가되고 있다.","a":"안동수곡리암각화","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663477.jpg"},{"q":"○○○는 통일신라 경문왕 10년(870)에 두운이 세운 절이다. 두운이 용문산에 이르렀을 때 바위 위에서 용이 영접하였다 하여 붙인 이름이다. ○○○는 2층 누각집으로 고려 의종 20년(1166)에 자엄대사가 세웠으며, 조선 명종 16년(1561) 고쳐 짓고, 광해군 13년(1621)에도 고쳐 지었다. 그 뒤, 1979년에 보수하여 오늘이 이르고 있다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짠 익공 양식으로 꾸몄다. 안쪽 천장은 뼈대가 그대로 드러나 있는 연등천장이다.","a":"예천 용문사 자운루","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641311.jpg"},{"q":"김유신·최치원의 영정과 홍유후·설총·문창후의 위패를 모시고 있는 서원이다. 680년경에 지었고 1919년 지방유림들이 다시 지었으며, 경주 서○○○의 이름을 본따 ○○○○이라고 이름지었다. 경내에는 사당, 서원 2동의 재, 솟을대문이 있다. 사당은 앞면 3칸·옆면 1칸의 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 서원은 앞면 4칸·옆면 2칸 규모에 지붕은 팔작지붕이고, 대청이 없이 툇마루가 확장되어 대청의 기능을 한다. 서원 좌우에 마주보고 있는 재는 각각 앞면 4칸·옆면 2칸 규모이다.","a":"진주 남악서원","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663802.jpg"},{"q":"대전광역시 유성구 신동 속골마을의 북쪽 해발 200m의 산정상부에 있는 산성으로, 성벽의 둘레는 350m이다. 이 산성은 산 정상을 둘러쌓고 있는데, 이러한 형태를 테뫼식 산성이라 한다. 산은 거의 평탄한 지형을 유지하고 있으며 성의 평면은 거의 원형에 가깝다. 테뫼식 산성 중에서는 비교적 작은 규모에 속하는 이 산성은 성벽이 통과하는 지점은 안쪽에 5∼10m의 평탄한 지형이 있고, 성벽 바깥 높이는 5m 내외로 추정된다.","a":"소문산성","c":"시도기념물","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645806.jpg"},{"q":"이곳은 그 유래가 전해지지는 않으나, 통일신라시대 때 세워 조선시대 때 없어진 것으로 추정되는 ○○○가 있던 자리이다. 1984년의 발굴결과 앞면 3칸·옆면 3칸의 금당터와 부속 건물터를 확인하였다. 통일신라시대의 유물인 석탑, 석등, 석불 등의 재료와 고려·조선시대의 명문기와가 많이 발견되고 있어, ○○○가 신라시대부터 조선시대까지 여러 차례 중건을 거듭하며 이어져온 오랜 역사를 가지고 있는 사찰이었음을 알 수 있다.","a":"인제 한계사지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"인제군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648165.jpg"},{"q":"요지는 자기나 기와, 그릇 들을 만들어 굽던 가마터를 말한다. 웅천 가마터는 보배산 기슭의 점골에 자리잡고 있으며, 조선시대 분청사기를 생산하던 곳으로 두동요지, 금곡요지 등으로 알려져 있다. 도굴로 파괴된 가마터와 가마터 주변에서는 사발, 대접, 접시류를 비롯하여 귀얄문과 덤벙무늬 분청사기가 출토되고 있다. 이로 보아 이 가마터는 조선시대 분청사기가 백자로 변해가는 마지막 단계인 15∼16세기에 만들어 운영되다가 임진왜란으로 폐요되었을 것으로 추정한다.","a":"창원 웅천도요지","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655940.jpg"},{"q":"남·여를 상징하는 한 쌍의 성기 모양 암석이다. 전하는 말에 의하면 고려말 왜적의 침입에 대비하기 위하여 ‘○○토성’을 다시 돌로 쌓았는데, 성쌓기에 참여했던 승려가 암자로 돌아가던 중 2개의 돌이 굴러오는 것을 보았다고 한다. 성을 쌓는데 필요한 성돌이 되려고 간다는 말에 승려가 모두 완성되었다고 대답하자 두 돌 모두 그 자리에 서서 통곡을 하며 울었다 한다.","a":"진주 명석 자웅석","c":"시도민속문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659049.jpg"},{"q":"대연사는 백제 의자왕 16년(656)에 고승인 의각과 도침이 세운 절로 고려시대의 역사는 전하지 않고, 조선시대에 여러 차례 보수하고 고쳐 세운 기록이 남아 있다. 대연사 경내 건물로는 ○○○○을 비롯하여 노전, 산신각, 요사채가 있다. ○○○○을 지은 시기는 알 수 없고, 1975년 보수 당시 건물에 관해 기록한 상량문과 ‘극락보전’이라고 쓰인 현판을 발견하여, 인조 25년(1647)에 보수되었고 그 뒤 한 차례 더 수리하였음을 알게 되었다. 현재 ○○○○의 현판은 ‘극락전 ’으로 되어 있다.","a":"대련사원통보전","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661183.jpg"},{"q":"임진왜란에서 전사한 송제와 광해군 8년(1616) 여진족의 침입 때 전사한 송덕일과 송제의 처 구씨의 절개를 표창하기 위해 세운 곳이다. 송제는 무관으로 임진왜란 때인 선조 26년(1593) 당시 왜군에게 포로가 되어 꿇어앉히려는 적장에게 ‘내 목을 자를 수 있을지언정 내 무릎은 굽힐 수는 없다.’라고 호령하며 항거하다 목숨을 잃었다. 이를 보고 감탄한 왜적은 시체를 매장한 후 ‘조선의사송제지시’라고 쓴 나무표식을 세웠다고 한다. 조은 송덕일은 조선 중기 무신으로 선조 25년(1592) 임진왜란 때 훈련원 첨정으로 의주까지 왕을 호종하였다.","a":"송씨쌍충일열각","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2026020308312200.JPG"},{"q":"이곳은 열녀로 열녀문을 하사받은 쌍청당(雙淸堂) 송유(1389~1446)의 어머니 유씨 부인이, 문종 2년(1452) 82세로 돌아가시자 이곳에서 장례를 지내고 그 옆에다 만든 재실이다. ㄱ자형 재실 건물에 양 옆으로 2칸씩 방이 달려 있는데, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 재실 중앙에는 큰 마루를 중심으로 좌우에 안방과 건넌방을 두었고, 안방 옆으로는 2칸 크기의 부엌을 만들었다. 중앙 큰 마루에는 ‘○○○○’라는 현판이 걸려 있다.","a":"관동묘려","c":"문화유산자료","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659745.jpg"},{"q":"○○○○○는 1741년의 작품으로 일본에 전해지는 16세기의 작품(1550년 日本 愛知縣 新長谷寺 소장품 외)을 제외하고는 국내에 남아있는 작품 중에서는 빠른 시기의 작품이다. ○○○는 18세기 전반에 대대적인 중수 불사를 하면서 당시 대표적인 화승 의겸을 모시고 많은 불화불사를 진행하는데 ○○○○○는 그 시기의 작품으로 전체적인 색감과 화면구성, 각 군중의 표현 등에서 융성한 ○○○의 일면을 담고 있는 것으로 보인다. ○○○의 ○○○○○는 제작시기도 빠르고 작품의 질도 우수하다. 제작에 참여한 화승들도 18세기 초반의 대표적인 화승인 의겸의 제자들이다.","a":"여수 흥국사 삼장보살도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640219.jpg"},{"q":"정사각형의 지대석위에 각형 괴임대가 새겨진 하댓거을 놓고 호감암의 석종형탑신을 올렸다. 탑신 윗부분은 복발모양으로 조각하여 정상부에 3단의 돌출부부을 조식하였고 탑신부 가운데에 부도의 주인공을 새겨놓았는데 '寂雲堂舍利塔'으로 보여진다","a":"충주 청룡사지 석종형승탑","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660815.jpg"},{"q":"1820년경 세운 집으로 一자형 안채와 ㄷ자형 사랑채가 배치되어 전체적으로 ㅁ자형을 이루고 있다. 안채는 앞·뒤 2열로 구성된 겹집이다. 앞칸은 상방(사랑방)·안방을 두었고 뒤칸에는 뒷방·도장방·뒷상방으로 이루어졌으나 지금은 도장방을 없애고 뒷상방을 넓게 쓰고 있다. 사랑채는 안채와 연결되어 있으며 마루와 방이었는데 지금은 모두 방으로 개조하였다. 안채 오른쪽으로는 조그만 규모의 사당이 있고, 뒤에는 활을 쏘던 과녁터로 불리는 후원이 있다.","a":"강릉 서지 조진사댁","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018122714063800.JPG"},{"q":"이 불화는 ○○○○○의 ○○○으로 대자재천을 비롯하여 모두 18위의 천인이 묘사되어 있다. 화면의 상단 중앙에는 삼목팔비(三目八臂)의 대자재천을 중심으로 좌우에 범천ㆍ제석천 등 3위가 원형 두광을 갖추고 합장한 모습으로 배치되어 있다. 대자재천과 범천ㆍ제석천의 가장자리에 산개(傘蓋)를 든 동자상 1위, 당번을 든 동녀 2위가 그려져 있으며, 그 아래쪽 화면 가장자리에는 일궁ㆍ월궁천자가 시립하고 있다.","a":"양산 통도사 극락암 가경23년명 신중탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665655.jpg"},{"q":"고려 때 명장인 문숙공 ○○의 ○○화로, 문·무복 차림을 한 2폭의 전신상이다. ○○은 고려 문종 때 과거에 합격하여 별무반이라는 특수군대를 창설하고, 탈환한 곳에 9성을 세우는 등 고려가 여진을 정벌하는 일에 큰공을 세운 인물이다. 문인복 차림은 의자에 앉아 두 손을 앞으로 모아 잡고 있는 좌상이고, 무관의 전투복을 차려입은 모습은 활을 들고 서 있는 전신상이다. 파평 윤씨 집안에 전해오는 바에 의하면 ○○의 ○○화는 원래 함경북도 만뢰사에 보존되어 왔으며, 이 상은 만뢰사의 것을 옮겨 그린 것이라 하나 확실하지는 않다.","a":"윤관 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638646.jpg"},{"q":"○○○는 사람이 죽어서 3일 후에 받는 심판을 주재하는 현왕을 중심으로 묘사한 불화이다. 현왕은 염마왕(閻魔王)을 여래화 시킨 것으로 법당 안의 현왕단에 봉안되는데, 현왕단은 대체로 약사전(藥師殿)에 봉안하는 경우가 많다. 액자형의 이 탱화는 액자 뒷면 중앙에 높이 9.5㎝, 가로 12.0㎝, 폭 3.0㎝ 크기의 네모난 틀이 있고, 그 안에 후령통을 싸는 황색비단보자기를 비롯한 복장물을 봉안하고 있다.","a":"복천사현왕도및복장유물일괄","c":"문화유산자료","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659387.jpg"},{"q":"구 ○○○○○소는 한강변에서는 최초로, 전국에서는 아홉번째로 건립된 자기(自記)○○○로서 조위(潮位)와 홍수위(洪水位)를 관측할 목적으로 건립되었다. 이 ○○○가 세워지기 전인 1917년도부터 이미 동일 지점에서는 ＇○○○＇이라는 양수표명으로 보통○○○○이 이루어지고 있었지만 1924년 12월 구 ○○○○○소가 건립되고 1925년 1월 관측이 정식으로 개시되면서부터 보다 과학적이고 현대적인 ○○○○이 개시될 수 있었다. 구 ○○○○○소는 조위 변동으로 인하여 1977년 폐쇄되었는데, 실제 ○○○○은 1976년 9월까지 이루어졌다.","a":"구용산수위관측소","c":"시도기념물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644820.jpg"},{"q":"충청북도 ○○시 상당구 문의면 ○○○ 태봉에 위치하는 조선 왕실의 ○○이다. 이곳 산 이름이 ‘태봉’胎峰이 된 것은 여기에 ○○이 있기 때문이다. 이 ○○의 주인공과 건립시기를 명기한 ○○비의 비문에 ‘만력십육년무자萬歷十六年戊子’에 세운 ‘아지씨阿只氏’의 ○○이라는 명문이 판독되어, 1588년(선조 21)에 선조와 정빈민씨 사이에서 태어난 인성군仁珹君의 ○○로 추정된다. ○○○○○은 현재 봉분과 ○○비가 남아 있는데 봉분에 묻혀있는 태함胎函은 석회암으로 만든 반구형半球形 개석蓋石을 갖춘 원통모양이다.","a":"청주 산덕리 태실","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650183.jpg"},{"q":"속초지역의 유학자이셨던 매곡 ○○○ 선생의 생가로서, 전면 4칸, 측면 2칸의 ㄱ자 함경도형 겹집이다. 본채 전면에는 머름대가 있으며, 안채 뒤쪽으로 일자형의 방들이 이어져 있다. 뒷마당에는 증축한 곳간과 창고가 있다. 마구간 벽체는 판벽으로 짜여 있고 본채 지붕에 이어서 내림지붕으로 낮게 이어져 내려오고 있다. 안방에는 할머니가, 윗방에는 시어머니가 거주하였으며, 윗방에는 툇마루가 후원 쪽으로 나와 있어 후원을 거닐 수 있도록 되어 있다. 사랑방에는 조부가, 윗사랑에는 손자가 생활하였고 뒷방에는 며느리가, 윗 뒷방에는 딸들의 공간으로 활용하였다.","a":"속초매곡오윤환선생생가","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660633.jpg"},{"q":"장례원 판결사 조광의(1543∼1608) 선생이 학문을 연구하던 곳이다. 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 건물의 안쪽 구조가 매우 섬세하며 조선 중기 건축 양식을 보여 주는 건축물이다.","a":"약산당","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662521.jpg"},{"q":"이휘일(1619∼1673)의 8대손 이수악의 생가인 ○○○○, 이휘일을 추모하기 위해 지은 건물이다. ○○○ 이수악이 말년을 보낸 ○○○, 관리사 4동으로 이루어졌다. 이휘일은 조선 중기의 학자이며 호는 존재이다. 성리학에 몰두하였고 후진 양성에 힘썼다. 저서로는 『전원팔곡시조』, 『홍범연의』, 『존재집』등이 있으며 죽은 뒤 영해의 인량서원에 모셨다. ○○○○은 이수악의 생가이다. 앞면 8칸·옆면 6칸 반 규모이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 원래는 정침과 사당으로 이루어져 있었으나 현재는 정침만 남아 있다.","a":"존재종택및명서암.우헌정","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663069.jpg"},{"q":"남은 서섭과 취정 서효재의 학문과 덕을 추모하기 위해 세운 서원이다. 서섭은 세종(재위 1418∼1450) 때 이조판서를 지냈고, 후일 사육신의 순절을 애통해 하여 시골로 내려와 은둔생활과 후학을 기르며 여생을 보냈다. 달성 서씨 문중의 서당이었던 풍성당을 무풍면 지성리로 옮겨 고쳐 짓고, 1901년 분양정사라 하고 제사지내 오다가 1945년 동편에 숭모사를 세웠다. 1973년 ○○○○으로 이름을 바꿔 오늘에 이르고 있다. 현재 남아 있는 건물로는 숭모사, 강당, 화수헌 1동, 수직사 1동 등이 있다.","a":"분양서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661822.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 시기는 정확히 알 수 없으나, 성종(재위 1469∼1494)대에 지은 것으로 보인다. 지금 남아 있는 건물로는 ○○○을 비롯하여 동무와 서무, 명륜당, 동재와 서재, 내삼문, 외삼문 등이다. ○○○은 앞면 3칸·옆면 3칸의 규모로，지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"순창향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661684.jpg"},{"q":"○ 고려시대 승려의 생활용품의 하나인 정자발우는 기벽이 얇고 빛이 청아하고 유연하다 ○ 시문된 문양은 없지만 구연부를 직각으로 세워 독특한 모양을 하고 있다.","a":"단양 구인사 청자발우","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638758.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 태조 3년(1394)에 세워졌다고 전하며 인종 1년(1545)에 수리한 기록으로 보아 조선 전기에 건축되었음이 확실하다. 대성전과 명륜당이 서로 다른 토담속에 남향으로 배치되어 제사공간이 앞에 있고 학습공간이 뒤에 있는 전묘후학으로, 전형에서는 벗어난 독특한 배치를 하고 있다. 향교의 중심 건물인 대성전은 중국과 우리나라 성인들의 위패를 모신 곳으로 앞면 5칸·옆면 2칸의 맞배집이며 조선 중기 건축이다.","a":"의성향교","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640571.jpg"},{"q":"建陽2年(1897)에 조성된 작품으로 화면 중앙에 위치한 석가모니를 중심으로 전방 좌우측에 협시인 문수ㆍ보현보살과 사천왕 중 2구가 배치되어 있고, 그 상단에는 미륵·제화갈라·관음·지장보살 4구가 각각 2구씩 배치되어 있으며, 가장 상단에는 대제자상·8금강(4구)·사천왕상(2구) 등의 권속들을 꽉 차게 배치하고 있다. 권속들의 모습은 화면 아래에서 위쪽으로 갈수록 상대적으로 작게 표현하여 상승감을 주고 있다. 색채는 백색·녹색·적색을 주로 사용하고 있으며, 부분적으로 청색과 회색을 사용하고 있다.","a":"남해 용문사 건양2년명 석가설법도","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665116.jpg"},{"q":"조선 선조 35년(1602)에 세운 화축관의 문루로 추정되며, 당시 임금이 온천에 갈 때 머물던 별궁으로 사용했던 곳이다. 본래 중앙초등학교 정문에 있던 것을 1959년에 이곳으로 옮겨 세웠다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면 중앙에 층계가 있으며 4면에 난간을 설치했다. 건물 안에는 우암 송시열이 지은 글(記文)이 남아 있다.","a":"영남루","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660882.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 지상에 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 대구시 수성구 ○○○에 있는 이 고인돌은 바둑판식으로 4기가 무리지어 있다. 덮개돌의 길이는 1.7∼2.37m, 너비는 1.1∼1.6m이며 받침돌 높이는 0.7m∼1.27m 정도이다.","a":"사월동지석묘군","c":"시도기념물","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645369.jpg"},{"q":"조선 후기 경상도 지방 상류 가정을 살펴 볼 수 있는 집이다. 1840년대에 안붕원이 부북면 전사포리에서 이곳으로 이사한 뒤, 1870년대에 안채와 별채 2동과 대문을 지었다. 사랑채와 창고, 바깥대문 등은 1890년경에 새로 지은 건물이다.","a":"밀양청운리안씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664076.jpg"},{"q":"몸통 부분은 사각기둥에 가깝고 측면의 한쪽은 편평하며 다른 한쪽은 둥근 장군이다. 전면을 백토분장(白土粉粧)한 후 조화(彫花)와 박지(剝地)기법으로 문양을 새겼다. 몸통 부분의 양면에는 ○○○을 새기고 둥근 한 측면에는 화문(花文)과 연판문(蓮瓣文)을 배치하였다. 입부분의 양쪽에도 화문(花文)을 새겼다. 투명한 담청색의 분청유약이 입혀졌는데 빙렬이 있으며 광택이 좋다. 굽은 평저(平底)로 굽바닥에 모래를 받치고 구웠다. 구연부(口緣部) 일부가 파손되었으나 별도의 굽이 없는 독특한 형태의 장군으로 대담한 문양 시문(施文)이 기형(器形)과 조화를 이루는 수작이다.","a":"분청사기조화모란문장군","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593089.jpg"},{"q":"○○○○○는 2007년 경남고고학연구소의 발굴조사를 통해 묘역의 부석시설과 거대한 개석의 존재가 확인되었던 유적으로 이후 5m 정도의 복토를 통해 지하에 보존 조치된 유적이다. 10m*4.5m*3.5m의 규모에 350t 정도로 추정되는 거대한 상석과 85m 정도의 세장방형 부석의 존재는 국내 최대 규모에 해당되는 ○○○이다.","a":"김해 구산동 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657597.jpg"},{"q":"진주 유씨 16세손 유시회(1562∼1635)가 지었다고 전하는 가옥이다. 원래는 충북 괴산에 살았는데 유시회의 조카 적이 선조의 사위로 정해진 후 아버지가 세상을 뜨자 선조의 명으로 이곳 안산에 묘자리를 정하고 정착하여 살기 시작하였다. 이후 나라에서 넓은 땅과 안산 바닷가의 어염권을 받아 대대로 살아 오면서 많은 인물들을 배출하였다. 청문당은 조선 후기에 와서 정치권력에서 소외된 문인들의 교류장으로 쓰였으며, 특히 조선시대 4대 서고의 하나인 청문당의 만권루는 이들의 학문적인 기반이 되었다고 한다.","a":"안산청문당","c":"문화유산자료","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660148.jpg"},{"q":"남한산성을 쌓을 때, 동남쪽 건축 책임자였던 이회(李晦, 1567-1625)와 그의 아내, 첩 그리고 벽암대사(碧岩大師)를 모신 사당이다. ○○○은 마을의 신을 모시는 신당의 성격을 띠고 있다. 청량산에 지어져 ‘○○○’이라고 불렸고 수어장대(守禦將臺) 옆에 위치한다. 이 사당에 전해져 내려오는 이야기가 있다. “이회는 1624년에 남한산성을 건축할 때, 동남쪽의 공사를 맡았다. 그는 경비를 함부로 사용하고 공사에는 힘쓰지 않아, 기한 내 마치지 못했다는 억울한 누명을 쓰고 사형을 당했다.","a":"청량당","c":"시도유형문화유산","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637317.jpg"},{"q":"임란 후에 간행된 경전 7책중 하나로, 십지경론(하) 난승지 제5권 7~ 법운지 제10권 12, 간집록, 대방광불화엄경소초 권34, ○○○○○, 대방광원각수다라요의경 권6, 묘법연화경 권1,2 이다. 각수를 적어놓은 형태나 어미 모양 등 지방 사찰에서 간행된 목판본의 형태와 판본류를 확인해 볼 수 있으며 조선후기 각 지방의 경전 간행의 경향을 알 수 있는 중요한 자료로 인정됨","a":"경덕전등록 권22~24","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643188.JPG"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 태조 7년(1398)에 지어진 후 임진왜란(1592) 때 불타 없어진 것을 그 뒤에 다시 지었다. 현재 남아있는 건물은 ○○○·명륜당·동재·서재·제기고·내외삼문·홍살문·하마비 등이 있다. ○○○은 제사공간의 중심이 되며, 중국과 우리나라 성현들의 위패를 모시고 제사지내는 곳이다. 앞면 3칸·옆면 2칸 반이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집으로 겹처마이다.","a":"익산향교대성전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639542.jpg"},{"q":"○○○는 계룡산 기슭에 있는 절로 백제 의자왕 11년(651)에 보덕이 처음 지었다고 전한다. 고려와 조선을 거치면서 여러 번 다시 지어졌고, 지금의 ○○○ 건물은 조선 고종 13년(1876)에 보연이 지은 것이라고 한다. 앞면 3칸·옆면 3칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 처마의 끝을 살짝 올려 우아한 멋을 나타내었다. 지붕을 받치면서 장식을 겸하는 공포가 기둥 위와 기둥 사이에도 있는 다포양식 건물이며, 연꽃을 조각하여 장식하였고 매우 간략한 양식으로 되어있다.","a":"신원사대웅전","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639127.jpg"},{"q":"조선시대 태인현에 있던 관아 건물이다. 동헌은 현감의 사택인 내동헌과 공무를 집행하던 외동헌으로 구분되어 있는데, 보통 동헌이라 하면 외동헌을 말한다. 현재의 ○○○○은 중종(재위 1506∼1544) 때 건립되었고, 순조 16년(1816)에 수리한 것으로 보인다. 앞면 6칸·옆면 4칸 규모이며, 지붕 옆면이 여덟 팔（八）자 모양인 팔작지붕집이다. 내부의 공간이 매우 다양한데, 오른쪽이 대청마루이고 왼쪽이 온돌방으로 되어 있으며 앞뒤로 퇴칸이 있다. 뒤쪽 퇴칸은 오른쪽 2칸을 대청보다 높은 마루로 꾸미고 나머지는 흙바닥으로 처리하였다.","a":"태인동헌","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639474.jpg"},{"q":"○○○○의 업적을 기리기 위해 조성한 이 비석은 ○○○ 입구로 들어서서 오른쪽 숲 속의 부도 밭에 세워져 있다. 조선 철종 9년(1858)에 건립한 것으로 비명(碑銘)은 조선시대의 대명필가인 추사(秋史) 김정희(金正喜)의 필적이다. 조선조의 억불정책에도 불구하고 오랜 침체기를 헤치며 조선후기 불교의 참신한 종풍(宗風)을 일으킨 화엄종주(華嚴宗主) ○○○○의 업적이 적혀 있는 이 비석은, 네모난 받침 위에 몸통을 세우고 지붕돌을 씌운 모습으로 되어 있다.","a":"선운사백파율사비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639549.jpg"},{"q":"조선 선조 33년(1600) 조선 중기 문신인 부사 성여신(1546∼1632)의 제자가 선생의 호를 따서 지은 정자로, 유학을 가르치던 곳이다. 정조 9년(1785)에 반구정 외 17동이 불에 타 없어져 지금은 ○○○ 외 1동이 남아 있다. 이 정자는 앞면 4칸 규모인 목조기와집이다.","a":"진주 부사정","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664310.jpg"},{"q":"○○○○○는 1868년 명조(月照)를 증명(證明), 보관(普寬)을 송주로 하여 응륜(應崙), 창엽(瑲燁), 승의(勝宜) 등이 그린 것으로, 치성광여래삼존(熾盛光如來三尊)을 중심으로 칠성여래(七星如來), 칠원성군(七元星君), 삼태육성(三台六星), 동녀(童女), 천녀(天女) 등을 묘사하였다. 즉 치성광여래 아래에는 일광보살(日光菩薩)과 월광보살(月光菩薩) 및 칠원성군(七元星君)이 시립하고 있으며, 본존의 좌우로는 칠성여래가 치성광여래를 향하여 합장하고 서있다.","a":"청룡사 칠성도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110815550100.JPG"},{"q":"이 책은 당(唐)나라 초기에 시인 왕발(王勃)*이 지은『○○○○○기(釋迦如來成道記)』에 대해 당나라 때 중국 항주시 남쪽 교외의 전당강(錢塘江)가에 있는 월륜산(月輪山)의 도성(道誠)이 주석(註釋)을 한 것이다. 조선 전기에 사용된 을해자(乙亥字)가운데 중자(中字)과 소자(小字)를 사용하여 인쇄했으며, 그 내용은 석가모니의 일생을 담고 있다.","a":"주석가여래성도기","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101216240500.jpg"},{"q":"○○○는 통일신라 성덕왕 23년(724) 상원사라 하여 처음 지은 절이다. ○○○은 삼성(칠성·산신·독성)의 탱화를 모신 곳이다. 칠성은 북두칠성으로 인간의 복과 수명을 맡고 있으며 산신은 우리민족 고유의 토속신으로 호랑이와 더불어 나타나며 재물을 담당한다. 독성은 홀로 깨닫고 성인이 되어 말세 중생에게 복을 내리는 존재이다. 이것은 불교가 토착화하는 과정에서 도교, 토속, 불교 등 여러 신앙요소가 합쳐진 형태이다. 불교 밖의 신앙대상을 모셨으므로 건물 이름을 전이라 하지 않고 각이라 하였다.","a":"동학사삼성각","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660964.jpg"},{"q":"이 목판은 이의조 선생이 관혼상제의 예법을 전국적으로 통일시키기 위해 영조 34년(1758)에 『주자가례』에 우리나라의 여러 설을 열거, 증보, 해석하고, 자기의 설을 첨가하여 영조 47년(1771) 완성한 『○○○○초본』이다. 이 판목은 정조 16년(1792) 직지사에서 느티나무를 이용하여 김풍해 등이 3년의 작업에 걸쳐 정조 18년(1794)에 완성하였다. 이것은 총 475매의 목판으로 새긴 기술이 우수하고 보존이 잘 되어 가례연구의 귀중한 자료로 평가된다.","a":"가례증해판목","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640361.jpg"},{"q":"조선 후기에서 일제시대 초기 사이에 지은 개량한옥으로, 행랑대문채와 본채로 구성되어 있다. 본채는 사랑채 부분과 건넌방 부분이 복도를 사이에 두고 남북으로 배치되어 있다. 사랑채 부분은 왼쪽에 현관과 홀을 내었고 서남쪽에 대청을 두어 정원을 내다볼 수 있게 하였다. 대청왼쪽에는 온돌방을, 그 앞쪽에는 주인실을 배치하고 툇마루를 돌렸다. 현관홀 뒤쪽에는 온돌방 2칸을 두어 객실로 쓰고 있으며 복도를 통하여 안청 대마루에 이른다. 안청 대마루 오른쪽에는 안방을 두고 그 위쪽에 부엌을 마련하였다.","a":"가회동한씨가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658051.jpg"},{"q":"충청북도 ○○군 청천면 ○○○의 암벽에 새긴 불상으로 모두 3구의 불상을 선으로 표현하였다. 본존불은 얼굴 길이가 2m이며 이목구비가 시원스럽고 큼직하다. 사각형의 신체에는 선으로 새긴 U자형의 옷주름이 촘촘하게 표현되었다. 얼굴과 신체, 옷주름이 서로 유기적으로 관련되어 만들어졌다고 여겨지는데 이는 고려초에 유행하던 선으로 새긴 마애불상과 같은 경향을 보여준다. 오른쪽 보살상은 모습과 조각수법이 본존불과 비슷하다. 왼쪽 보살상은 타원형의 얼굴과 둥근 머리 등이 약간 도드라지게 새겨져 세련된 면을 보여주고 있다.","a":"괴산 도명산 마애불상군","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638609.jpg"},{"q":"이 불화는 현재 ○○○ 대웅전의 향좌측(向左側) 벽에 걸려있다. 화면 아래 붉은색 란에 묵서(墨書)로 명기된 화기(畵記)에 의하면 1914년 음력 10월 8일 새로 ○○○ 1축을 조성하여 경성부 고양군 삼각산 안양암에 봉안하였다고 하다. 연응 정순(淵凝 淨旬)스님을 증명으로 하고, 양학 효신(養鶴 孝信)스님이 별좌(別座) 겸 화주(化主)가 되어 조성하였는데, 금어(金魚)로는 금호 약효(錦湖 若效), 향암 성엽(香庵 性曄), 연암 경인(蓮庵 敬仁) 등 3인의 화승이 제작에 참여하였다.","a":"응선사 산신도","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313244700.jpg"},{"q":"○○○ 정석현을 추모하기 위하여 조선 영조 3년(1727)에 관찰사 권대규가 지었다. 1977년 영천댐 건설로 인하여 지금의 위치로 옮겨 지었다. 소박하게 지어진 건물로, 앞면 4칸·옆면 1칸 규모이다. 지붕 옆면이 사람 인(人)자 모양인 단순한 맞배지붕인데, 양쪽 옆면에 눈썹지붕을 이어 달아서 마치 팔작지붕처럼 보이게 하였다. 이런 예는 영천지역에서 흔히 볼 수 있는 일반적인 것이다. 한쪽에 마루 2칸, 다른 한쪽에는 방 2칸을 나란히 들였다.","a":"오회당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640373.jpg"},{"q":"○○○의 칠성각 내에 봉안된 조선 후기의 마애불이다. 거대한 암벽에 돋을새김한 ○○○로 모두 연화대좌에 앉아 있다. 중앙의 본존불은 크게 표현하고, 좌우의 보살상들은 조금 작게 표현하였다. 본존불은 민머리의 정상부에 뾰족하게 작은 육계(肉髻 ; 상투 모양의 머리묶음)가, 머리 중앙에는 계주(髻珠 ; 머리를 장식한 보석)가 표현되었다. 방형의 얼굴에는 눈두덩이 부은 눈, 삼각형의 짧은 코와 작은 입을 표현했으며 희미한 미소를 띠고 있는 부드러운 인상의 불상이다. 양 어깨에는 두꺼운 법의(法衣 ; 승려들의 겉옷)가 걸쳐지고 양팔을 거쳐 무릎까지 덮고 있다.","a":"삼막사마애삼존불","c":"시도유형문화유산","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637505.jpg"},{"q":"○○○○○는 3책으로 되어있는데, 그 1책은 참당사 ○○○, 도솔산 고적기(兜率山 古蹟記)의 두줄로 표제(表題)가 되고 그 옆에 당채종(唐太宗) 정관 원년시적(貞觀元年 始蹟)이라고 적혀있다. 이책의 첫장은 도솔산 대참사 고사(兜率山 大懺寺 故事)로 시작되어 다음의 대참사 법당기까지 15면에 달하는 기사를 숭정기원후3갑인동(崇禎紀元後3甲寅冬) 임우상(林雨相)이 기술했다.","a":"선운사사적기","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639632.jpg"},{"q":"목은 이색의 학문과 덕행을 추모하기 위해 세운 서원이다. 이색은 고려 후기의 문신이며 학자로 원나라에서 성리학을 연구하였고 그 나라의 벼슬을 지냈다. 귀국한 뒤 예문관 대제학 등 여러 벼슬을 거치며 신유학의 보급과 성리학의 발전에 공헌하였다. 이 서원은 조선 영조 47년(1771)에 세웠다. 이색의 10대손인 이홍조를 추가로 모시고 제사를 지내며 지방 교육의 일익을 담당해 오던 중 흥선대원군의 서원철폐령으로 폐쇄되었다가 1962년에 다시 지은 것이다.","a":"서산서원","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654460.jpg"},{"q":"수성암의 절벽 사이에 자리잡고 있는 용암사터에 유일하게 남아 있는 불상으로, 지옥에서 고통 받고 있는 중생을 구제한다는 지장보살을 표현한 것이다. 머리에 쓰고 있는 두건은 어깨까지 내려왔으며, 이목구비가 단정한 타원형의 얼굴은 오른쪽 뺨이 깨졌으나 눈가에 어린 미소가 불성(佛性)을 충분히 느끼게 할 만큼 온화하다. 양쪽 어깨를 감싸고 있는 옷은 매우 사실적으로 표현되었는데, 옷깃은 두꺼우며, 옷주름은 선으로 처리하여 신체를 부각시키고 있다. 이러한 특징은 고려 초기에 유행했던 양식으로 두건 쓴 모습과 더불어 당시의 지장보살상의 실례로 주목되고 있다.","a":"진주 용암사지 석조지장보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641335.jpg"},{"q":"동헌은 옛 관청인 관아에서 업무를 처리하던 중심건물을 가리킨다. 이 건물은 ○○목 동헌으로, 당시 ○○ 목사가 이곳에서 집무를 보던 곳이다. 조선 고종 7년(1870) 화재로 타버린 것을 같은 해 조병로가 다시 세웠다고 한다. 지금 있는 건물은 중원군 청사로 개조하여 사용하다가 1983년 군청 자리를 옮기면서 원형으로 복원하였다. 앞면 7칸·옆면 4칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕집이다. 가운데 3칸은 대청, 오른쪽 끝 1칸은 마루방, 대청 왼쪽 2칸은 온돌방, 왼쪽 끝 1칸은 누마루로 구성되어 있다.","a":"충주 청녕헌","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638487.jpg"},{"q":"이 비석은 동래부사 강필리(姜必履)가 온정을 대대적으로 수리한 공로를 기리기 위하여 1766년(영조 42)에 세웠는데, 송광적(宋光迪)이 썼다. 동래온천에 대한 최초의 기록은 신라의 재상 충원공(忠元公)이 이곳에서 목욕을 하고 돌아갔다는 삼국유사의 기록이다. 동래부읍지(東萊府邑誌) 산천조 온정란에 보면, 동래온천은 신라시대부터 알려져 있었음을 알 수 있다. 온천의 물이 계란을 익힐 만큼 뜨거웠으며, 병자가 목욕을 하면 병이 잘 나아 예로부터 많은 사람들이 찾았다고 한다. 비는 높이 144cm, 폭 61cm이다.","a":"온정개건비","c":"시도기념물","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645001.jpg"},{"q":"충청남도 논산시 연무읍 금곡리에 위치한 이 묘는 후백제의 시조 견훤(甄萱:867∼935)의 것이라고 전해온다. 견훤의 원래의 성은 이(李)씨이며, 상주 사람으로 신라 장군 이자개의 아들이라 한다. 신라 진성여왕이 즉위하면서 몇몇 신하들의 횡포로 정치 기강이 문란해졌고, 또 기근이 심하여 백성들의 원망과 봉기가 심해졌다. 이때 견훤이 경주의 서남 주현(州縣)을 공격하니 이르는 곳마다 사람들이 호응하여, 마침내 진성여왕 6년(892)에 무진주(지금의 광주)를 점령하고 스스로 왕위에 올랐다. 그 뒤 완산주(지금의 전주)에 도읍을 정하고 후백제를 세워 40여년간 다스렸다.","a":"전견훤묘","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651982.jpg"},{"q":"°이 건물은 축조연대가 종도리의 상량문에 崇禎後四己酉年(헌종 15년, 1849)으로 되어 있어 인근의 최감찰댁보다 앞서 그 가치가 크며 특히 부재의 규격과 짜임새가 우수하다. 또한 후대에축조된 최감찰댁의 초가보다 구조상 안정성을 고려한 부재와 가구 등이 우수하다. 그러나 사랑채와 기타 부속건물이 화재로 소실되었으며 일부 부재가 교체한 흔적이 있으나 부재의 상태나 치목수법, 마루청판은 고식기법으로 조선시대 치목기법이 역력히 나타나 있다. 안채는 정면 5칸 반, 측면 2칸의 홑처마 팔작 기와집이다.","a":"보은 최혁재 고가","c":"시도민속문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658237.jpg"},{"q":"이 영정은 경파당 ○○선사의 좌안 8분면 바닥가부좌상으로, 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 등받이의자를 배치하고 바닥에는 방석을 깐 후 측면을 바라보며 앉아 있는 모습이다. 의자에는 연부에 연화당초문양이 그려진 녹색 법피를 드리우고 있으며 불자를 기대어 두고 있다. 화면 향좌측에 ‘청허하제육세○○○대선사○○지진(淸虛下第六世影波堂大禪師聖奎之眞)’의 화제와 1870년에 쓴 영찬이 있다. 화면크기는 가로85.4cm, 세로122.5cm이다.","a":"영파당 성규 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643006.JPG"},{"q":"조선 중기의 고승인 ○○○○의 초상화이다. ○○○○의 자는 이환(離幻)이며, 호는 사명당(四溟堂)·송운·종봉(鍾峯)이고, 다른 이름은 사명대사이다. 조선 선조 25년(1592) 임진왜란이 일어나자 의승병을 모아 순안(順安)에 가서 휴정과 합류하여 활약하였다. 선조 37년(1604)에는 선조의 명을 받아 강화사(講和使)로 일본에 가서 성공적인 외교성과를 거두었고, 이듬해 전란 때 잡혀간 3,000여명의 동포를 데리고 돌아왔다. 초상화는 비단 바탕에 채색하여 그려진 것으로, 향좌측을 바라보며 의자에 앉아 있는 전신교의좌상(全身交椅坐像)으로서 족좌대(足座臺)를 하고 있다.","a":"함양 용추사 송운대사 진영","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023102312371800.jpg"},{"q":"일제시대 독립운동가였던 ○○○ 선생이 태어난 곳이다. 선생은 기미독립선언 민족대표 33인의 한 분으로 박영효와 함께 수신사로 일본에 다녀오고, 광무2년(1898) 한국 최초의 한글신문을 창간하고 1908년 대한황성신문 사장에 취임하여 민중을 계몽하고 일본의 침략정책을 공격하였다. 1925년 3월에 68세의 나이로 세상을 떴는데 1962년 3월 1일 건국공로훈장 복장을 수여받았다. 생가는 ㄴ자형 평면을 갖추고 있는 초가로 1986년 복원하였다. 남쪽으로부터 건넌방·대청·윗방·안방이 각 한 칸씩이고 부엌이 2칸이며 앞에 마루를 깔았다.","a":"이종일선생 생가지","c":"시도기념물","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652829.jpg"},{"q":"○○○를 둘러싼 산줄기의 서쪽 사면에 동향으로 자리한 집으로, 이 마을의 집들 중 가장 높은 곳에 위치한다. 이 집은 조선시대에 ○○○의 모든 논과 밭을 관리하고 조세를 거둬들이는 박씨 성을 가진 세력가의 집이었다고 전해지며, 마을 주민들은 이곳을 소가 누운 와우형 풍수형국의 중심부에 해당한다고 하여 예로부터 명당으로 인식해 왔다. 가옥의 배치는 ㄱ자형 안채와 ㄴ자형 바깥채가 안마당을 중심으로 마주보고 있는 튼ㅁ자형이다. 안채는 2칸 대청을 중심으로 좌우에 안방과 건넌방이 배치되고 안방 앞쪽으로 부엌을 시설한 전형적인 경기지방 건물이다.","a":"양평 창대리고가","c":"시도민속문화유산","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2023052614034101.jpg"},{"q":"○○○○○에 봉안되어 있는 ○○○○○은 방형(方形)의 수미단(須彌壇) 위 연화좌(蓮華座)에 각각 결가부좌한 자세로 앉아 있다. 중앙 본존불은 125㎝, 좌우협시는 100㎝ 정도의 크기로, 중앙의 본존불이 협시불에 비해 규모가 크게 조성되었다. 본존인 비로자나불은 등을 세우고 얼굴을 앞으로 약간 숙여 아래를 굽어보고 있으며, 수인은 지권인(智拳印, 오른손 검지를 왼손으로 감싸 쥐고 있는 모양)이다. 보편적인 조선 후기 불상과 마찬가지로 신체에 비해 머리가 큰 편이다.","a":"범어사 비로전 목조비로자나삼존불좌상","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636738.jpg"},{"q":"조선 중기의 학자·문신이자 의병장이었던 죽유 오운(吳澐)(1540∼1617)을 기리기 위하여 후손이 지은 살림집이다. 오운은 임진왜란(1592)이 일어나자 곽재우와 함께 의병을 일으켜 공을 세웠으며, 개인 문집인 『죽유문집』과 조선 중기 남인의 역사인식이 반영된 대표적인 역사서인 『동사찬요』를 쓰기도 하였다. ○○○○은 오운의 후손이 1700년대 말에 지어 죽유 오운을 기리고자 집의 이름을 죽유구택이라 하였다. 그 후 1906년에 고쳐 지었으나 1920년 대홍수로 이곳에 옮겨 왔다.","a":"죽유종택","c":"시도기념물","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654644.jpg"},{"q":"두암마을의 민가 옆에 자리하고 있는 탑으로, 주위에서 고려시대의 기와조각이 발견되어 이곳이 당시의 옛 절터임을 알게 되었다. 탑은 전체의 무게를 받치는 기단(基壇)을 2층으로 쌓고, 그 위로 3층의 탑신(塔身)을 올린 모습으로, 꼭대기의 머리장식을 제외하고는 대체로 본모습을 잘 간직하고 있다. 아래층 기단에는 각 면마다 3개씩의 안상(眼象)을 움푹 들어가게 새겼고, 위층 기단에는 4면의 모서리와 가운데에 기둥모양의 조각을 두었다. 탑신부의 1층 몸돌에는 한쪽면에 문짝모양을 새겼는데 그 안에 자물쇠도 표현해 놓았다.","a":"옥천 두암리 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638579.jpg"},{"q":"○○○○ 재사(齋舍)는 괴정 남준형의 묘소를 관리하고자 1780년대에 건립한 것으로 전해지며, 괴정공의 증손인 회수(華壽, 號 明厓,1781~1851) 대에 중수한 건물이다. 건물은 一자형으로 겹집형태의 구조를 취하고 있으며 평면은 전렬은 좌측으로부터 방, 2칸마루, 부엌으로 되어 있고, 후렬은 방, 방(도장), 방, 부엌으로 구성되어 있다. 자연석 주초위에 각주를 세웠으며, 상부가구는 납도리에 3평주 5량가로 맞보를 올렸다. 천정은 고미반자로 마감하고 그 위 상부는 노출시켰으나, 부엌과 전면 우측 마루부분의 천정은 앙벽을 치지 않고 산자를 노출시킨 상태로 있다.","a":"영덕괴시리스므나골재사","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663503.jpg"},{"q":"다산리 마을에 자리하고 있는 비로, 임진왜란 때 순절한 이희룡 장군과 그의 아들 이문진 및 며느리 김씨의 행적을 기리고 있다. 이희룡은 임진왜란 때 왕을 의주까지 호위하였으며, 영남의 적을 정찰하라는 왕명을 받고 임무를 마치고 돌아오는 길에 충주에서 적을 만나 전사하였다. 아들 문진은 아버지의 시신을 찾으려다 신령에서 적과 대치하다 죽었다. 며느리 김씨가 이 소식을 듣고 손수 시신을 찾았지만 결국 찾지 못하고 3개월만에 스스로 목숨을 끊었다. 조정에서는 이들의 공을 기리어 조선 숙종 36년(1710)에 벼슬을 올려주고 정려각을 하사하였다.","a":"이씨삼강묘비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640744.jpg"},{"q":"○○○은 청동기시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 이 ○○○은 ○○읍에서 48번 국도를 따라 인화리 방면으로 가다 송해면과 하점면 경계지점을 지나 ○○○-망월간 도로의 중간지점, 고려산 북쪽에서 흘러내린 주능선의 끝자락에 있는 해발 15m 정도의 낮은 지대의 밭에 위치해 있다.","a":"강화 부근리 점골 고인돌","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112111231000.jpg"},{"q":"울산 ○○○○○은 현재 매곡지방산업단지 부지에 위치하는 유적이다.2002년부터 2004년까지 이루어진 발굴조사를 통해 유적이 알려지게 되었으며, 청동기시대 집터, 삼국시대 무덤과 숯가마, 구덩이, 조선시대 무덤, 숯가마 등 여러 시대의 다양한 유구가 확인되었다. ○○○○○은 청동기시대부터 조선시대에 이르는 복합유적으로 이 지역의 고대인들의 생활상을 연구하는데 중요한 자료이다. 발굴된 청동기시대 유구는 집자리가 대표적인데, 모두 네모꼴의 움집[竪穴住居] 구조이다.","a":"울산매곡동생활유적","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645928.jpg"},{"q":"◦ 웅천읍 ○○○ 장터마을(기현부락)에 있는 12기의 ○○○임. ◦ 이곳은 장터마을의 중앙으로 많은 ○○○이 집중적으로 분포함. 장터마을에는 이곳 외에도 많은 ○○○이 있었으나 이곳을 제외하고 대부분이 훼손되었음. ◦ 대부분의 ○○○은 편마암인데, 동북쪽 산지에는 많은 편마암 노두가 있어 이곳에서 옮겨다 만들었을 것으로 생각됨.","a":"보령죽청리고인돌","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661535.jpg"},{"q":"○○○는 임진왜란 때 싸움에 나아가 충효의 이름이 높은 김유부(1549∼1621)를 비롯하여 병자호란 때 종군하여 순절한 최씨, 송씨 등의 덕목을 높이 평가하여 1905년 조정의 뜻에 따라 유림에서 건립한 집이다. ○○○라는 것은 유교사회 기본 덕목인 충(忠), 효(孝), 열(烈) 이 3가지를 한 가문에서 이룬 행적을 기리기 위해 ｀탁삼(卓三)´이라는 두 글자를 나라에서 내린데서 유래하였다. 이 ○○○에는 교지 등 고문서 44점과 나무로 만든 비 1점, 편액 2점, 녹권 1점 등이 소장되어 있다. ○○○ 옆에는 김유부의 충효각이 세워져 있다.","a":"밀양 탁삼재 유물","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642163.jpg"},{"q":"○○○는 삼일운동 당시 민족대표중의 한분인 백상규(白相奎) 즉 용성대선사(龍城大禪師)께서 1918년경 창건하시고, 병자년(1936년)에 선파(仙坡)·전강선사(田岡禪師) 등 고승대덕 스님들께서 주석하시면서 포교를 하셨고 1975년 비구니 혜안(慧眼)스님께서 인법당이었던 것을 八작지붕의 법당으로 건립하셨으며, ○○○○○는 조선시대 임진왜란 전후 시기에 간행된 불교 의식에 관한 불서로서, 97책(목판본 75, 필사본 12, 신식본 10)중 17책이 문화유산으로 지정되어 소장하고 있다.","a":"향산사 소장불서","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639757.jpg"},{"q":"지석묘는 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. ‘○○○ 지석묘’는 한탄강의 샛강인 양원천 지류의 편평한 대지상에 위치한다. 지석묘는 양쪽 고임돌 위에 커다란 덮개돌을 올려놓은 탁자식 ○○○이다.","a":"연천양원리고인돌","c":"시도기념물","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647400.jpg"},{"q":"○○○○○壤城山城은 충청북도 ○○시 상당구 문의면 ○○○ 일원에 위치하고 있는 석축산성으로 주변의 봉우리를 에워싼 마안형馬鞍形의 지세에서 낮은 위치의 능선을 길게 연결하고 있다. 『세종실록지리지』에는 “태산석성兌山石城이 현의 서쪽 4리에 있다. 둘레가 772보이며, 산세가 험하다. 안에 우물 하나가 있는데 겨울·여름에도 마르지 아니한다”라고 하였다. 그리고 『신증동국여지승람』에는 “○○○○은 돌로 쌓았으며, 둘레가 3,754척, 높이가 한 장이다. 안에 둥그런 못이 있는데 큰 못[大池]이라 부르며, 둘레가 192자 8치이다. 사면에 모두 돌을 쌓아 섬돌이 되었다.","a":"청주 양성산성","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651103.jpg"},{"q":"조선 전기의 문신인 기대승(1527∼1572)선생의 위패를 모시고 있는 사당이다. 선생은 성리학의 대가로 새 학설을 제시하여 학계에 주목을 받았으며 특히 스승인 이황 선생과 사단칠정(四端七情)을 주제로 한 8년 간의 서신왕래는 너무나 유명하다. 원래 이곳은 기대승을 중심으로 하여 좌우에 박상·박순·김장생·김집 등 조선의 명신들을 함께 배향하고 있는 ‘월봉서원’의 강당이었다. 월봉서원은 그가 죽은 뒤 그를 추모하기 위해 큰아들인 기효승이 선조 11년(1578) 세운 것으로 정조가 ‘○○○’이라 이름을 지어 내렸다.","a":"빙월당","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645748.jpg"},{"q":"이 팔각○○○은 가락국 수로왕의 처남인 ○○○○의 사리를 봉안하고 있는 석조물로서 가락국 제8대 질지왕(451-492) 재위중 장유암 재건당시 세워진 것으로 전하고 있다. 1500여년의 오랜 세월속에 여러번의 전환으로 암자와 관계 유물들은 거의 소실되고 ○○○만이 있었다고 하나 현존 ○○○은 그 제작 수법으로 보아 려말선초의 작품으로 보인다. 1915년 5월 선포화상의 원력으로 현재의 장유암 사옥이 중건되면서 탑의 보호를 위한 석조 난간을 설치하고 아울러 가락국사 ○○○○사적비를 건립하여 불모산 개창주의 뜻을 후세에 기리도록 하였다.","a":"김해 장유화상 사리탑","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663850.jpg"},{"q":"조선 전기의 학자이자 문인인 눌재 박상(朴祥,1474∼1530) 선생의 시문집의 판각이다. 선생은 연산군 7년(1501) 정시을과에 급제하여 교서관 정자로 관직에 나아간 후 여러 관직을 거쳐 중종 25년(1529) 나주목사를 역임하였다. 학문으로 배운 바를 충실히 실천하는데 앞장섰던 인물로, 정사에 임하는 자세가 공정하고 청렴하였다. 선생이 남긴 글은 시(時), 부(賦), 서(序), 기(記), 발(跋), 제문(祭文), 문(文)으로 나누어지는데, 즉흥적이고 직설적인 면보다 내면적 여과를 거친 차분하고 완곡한 서정을 바탕으로 하고 있다.","a":"눌재집목판각","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637153.jpg"},{"q":"○○는 반구 모양이며 전체높이가 약 21.5㎝, 몸통 지름이 약 15.2㎝이다. 투조(透彫)된 덮개, 공 모양 몸통, 손잡이 2개, 다릿발 3개 등으로 이루어져 있다. 덮개는 4개의 다리와 4개의 손톱을 가진 용이 하늘로 올라가는 모양이며 꼭지가 용의 머리이다. 몸통 윗부분에는 3마리의 봉황이 보이고 아랫부분에는 소가 보이며 다른 부분에 보상화무늬도 새겨져 있다. ○○은 타원 모양이며 전체높이가 약 7.5㎝, 몸통 지름이 약 9.2㎝이다. 덮개, 몸통, 원통형 다리 등으로 이루어져 있는데, 몸통은 소박한 원통처럼 생겼고 봉황무늬와 보상화무늬가 새겨져 있다.","a":"함양 하륜 부조묘 소장 향로 및 향합","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666587.jpg"},{"q":"이 유적은 임진왜란 때 의병장으로 활약하다가 순국한 송암(松菴) 김면(1541～1593) 장군의 묘소, 신도비(神道碑), 도암사(道巖祠), 도암재(道巖齋), 도암서당(道巖書堂)을 일괄하여 지정한 사적지이다. ○○○○은 조선 선조 25년(1592) 임진왜란이 일어나자 고령, 거창 등지에서 의병을 규합, 수십 여 차례에 걸친 전투에서 승리하면서 의병장으로 추대되었다. 1593년 경상우도병마절도사(慶尙右道兵馬節度使)가 되었으나, 선산대전을 앞두고 충청․전라도 의병과 함께 금산, 개령에 주둔하고 있을 당시에 병을 얻었다.","a":"김면장군유적","c":"시도기념물","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654523.jpg"},{"q":"조선 중기의 문신인 정탁(1526∼1605)을 기리고 제사지내는 곳이다. 정탁은 명종에서 선조 때까지의 사람으로 임진왜란 때 큰 공을 세웠으며 옥중에 있는 이순신 장군의 목숨을 구한 유명한 일화를 가지고 있다. 죽은 후 예천의 도정서원에 모셔졌다가 후손들이 지은 지금의 건물로 옮겨졌다. 재실과 대문으로 되어있다. 재실은 앞면 5칸·옆면 3칸의 ㄷ자형으로 되어있다. 대문채는 옆면 1칸짜리로 一자형이며, 마구간·고방·방앗간 등이 있다. 재실의 대청 뒷벽에 있는 영쌍창은 이 건물이 17세기에 지어졌다는 것을 보여주고 있다.","a":"예천청주정씨재실","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641016.jpg"},{"q":"○○○ 부조묘에 소장된 문서로서 국가에 공이 있는 인물의 후손들이 자신들의 처우를 확보하기 위해 만든 문서와 국가로부터 받은 문서들이다. 부조묘란 나라에 큰 공훈이 있는 사람의 신주를 사당에 영구히 제사 지내게 하는 특전이다. 조선시대에는 이와 같이 그 후손에 대해 여러 가지 특전과 혜택이 주어졌다. 여기 ○○○○○ 관련된 문서들은 조선 후기(18세기 말∼19세기 말)에 한정된 각종 증명서들이다. 현존하는 문서는 다음과 같다.","a":"보성 문익점 부조묘와 고문서","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640095.jpg"},{"q":"‘○○○’은 사육신(死六臣; 1456년 단종 복위를 위해 목숨 바친 6사람) 중의 한 명인 유응부(兪應孚, ?-1456년)의 충절을 기리기 위하여 세운 제단으로, 이후에 이어(李?), 양치(楊治,)의 위패를 추가로 모셨다. 이들 모두 세조에게 폐위(廢位; 임금의 자리를 잃음)당한 단종을 다시 그 자리에 올리려다 실패하여 죽임당한 이들의 충절을 기리기 위하여 세운 제단이다. 처음 ‘유허비(遺墟碑; 추모하기 위하여 세운 비석)’를 세울 당시에는 유응부의 깨진 비석만 있었기 때문에 ‘○○○’이라 하였다고 한다.","a":"충목단","c":"시도기념물","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646391.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말하며, 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 영덕 ○○○○○는 영덕 축산포 방면의 상황을 서울 남산까지 전하던 곳의 하나였다. 남쪽으로 별반 ○○○, 북으로 평해의 후리산 ○○○, 서로는 광산 ○○○를 거쳐 진보의 남각○○○○로 연락을 취하도록 되어있다. 산의 꼭대기에는 방어벽을 쌓고, 성 안에는 직경 11m, 높이 3.5m로 봉돈(烽燉)을 쌓았다. ○○○의 형태가 비교적 뚜렷하게 남아있어, 조선시대의 통신수단을 알아볼 수 있는 좋은 자료로 평가된다.","a":"영덕대소산봉수대","c":"시도기념물","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654447.jpg"},{"q":"○○○에 돌다리를 놓은 것을 기념하고자 세워 놓은 비로, 받침돌과 머릿돌이 없어진 채 비몸만 남아 있다. 비몸의 꼭대기 가운데 부분이 볼록하고 네모나게 돋아있어 여기에 비의 머릿돌을 얹었던 것으로 짐작된다. 비의 윗부분에는 비의 명칭을 새기고, 그 아래에 비문을 새겼는데, 아래의 작은 글자들은 거의 알아볼 수가 없으며, 맨 끝부분에 ‘승정기원후 51년(1688) ’이란 연대를 겨우 알아볼 수 있을뿐이다. 비의 옆면에는 스님들의 이름으로 보이는 글자가 희미하게 보인다. 원래 역천 갯가에 있던 것을, 1960년대에 지금의 자리로 옮겨 세운 것이라 한다.","a":"채운포석교비","c":"문화유산자료","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661265.jpg"},{"q":"‘○○○’는 신라 때 처음 세워졌다고 전한다. 고려 때는 혜소 국사 정현스님(972~1954년)이 이곳에서 머물면서 크게 중수했다. 조선 시대에는 인목대비(선조의 왕비)가 일찍 죽은 아버지와 아들의 명복을 빌기 위해 ○○○를 크게 후원하였다. ○○○가 자리하고 있는 칠현산 고개는 조선 시대에 충청북도 진천과 경기도 안성을 오고 가는 중요한 길목이었다. 이런 교통의 요지에는 유난히 도적과 관련된 설화가 많다. 칠현산(七賢山)이란 이름도 ○○○를 도적질하려던 도적 7명을 혜소 국사가 제자로 받아들여 바르게 가르쳤다는 설화에서 유래한 것이다.","a":"칠장사","c":"문화유산자료","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659931.jpg"},{"q":"1703년(숙종 29) 계미년(癸未年)에 태어난 7명의 동갑들이 만든 동경계첩(同庚契帖)이다. 화첩을 펼치면 오른쪽 면은 비어 있고 왼쪽 면에 참판 이익진(李翼鎭, 1703~?), 판서 조영진(趙榮鎭, 1703~1775), 참판 이규채(李奎采, 1703~?), 영의정 한익모(韓翼謨, 1703~?), 부사 송진흠(宋晉欽, 1703~?), 영의정 신만(申晩, 1703~1765), 유언술(兪彦述, 1703~1773) 일곱 명의 반신 초상화가 차례로 각각 그려져 있다. 이어서 이들이 69세이던 1771년(영조 47) 10월 상순에 유언술이 쓴 서문이 4면에 걸쳐 있다.","a":"계미동경소진첩","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636539.jpg"},{"q":"조선 중기의 유학자 주곡 이도(1636∼1712)가 주남리에 지었던 것을 후손들이 순조 30년(1830)에 이곳으로 옮겨 지은 것이다. ㅁ자형 구조이며, 사랑방의 편리를 위하여 다양하게 꾸민 벽장과 감실방 벽장 아래 끌어내릴 수 있는 널로 된 제사상이 돋보인다. 또한 부엌에 물을 길어 담아 두고 쓰는 큰 독인 물두멍도 남아있는, 예가 드문 옛 생활문화의 흔적이다. 경상북도 북부지역의 전형적인 민가건물로 중요한 자료이다.","a":"원리주곡고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658843.jpg"},{"q":"태조 이성계의 첫째 아들인 진안대군 이방우와 대군의 첫째 아들인 봉령후의 위패를 모신 사당이다. 이방우(？∼1393)는 부친이 혁명의 뜻이 있음을 알고 해주에 은거하다 죽고, 사후에 진안대군에 봉해졌다. 순조 31년(1831)에 세운 이 건물의 ‘청덕(淸德)’이라는 이름은 대군이 청빈하고 덕이 있다고 하여 붙인 것으로 ‘○○○’라고 쓴 현판을 솟을삼문에 걸었다. 솟을삼문 둘레로는 담장을 두르고 외삼문 안에는 연못을 조성하였다. 건물 구조는 앞면 3칸·옆면 1칸 반 규모로, 지붕은 옆면에서 볼 때 사람(人)자 모양인 맞배지붕이다.","a":"괴산 청덕사","c":"문화유산자료","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660727.jpg"},{"q":"의촌 김남식과 시은 김이성·인일정 김성은의 학문과 덕행을 추모하고 이를 계승하고자 세운 서원이다. 김남식은 김집 선생의 문인으로 병자호란 때 청나라와 굴욕적인 화의를 맺었다는 소식을 듣고 통곡하며 돌아와 계령산 밑에 살며 집 이름을 대명유계라 하였다. 김이성은 김남식의 아들로 송시열 선생의 문인이며 효성이 지극하였다고 전한다. 김성은은 김이성의 증손으로 황의찬 문하에서 수학하였고『동국문헌록』등의 저술이 있다. ○○○○은 크게 세 영역으로 구분된다. 중심 영역에는 사우와 내삼문, 강당인 옥산정사가 일렬로 배치되어 있으며, 강당 동쪽에는 고직사가 자리잡고 있다.","a":"옥산서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661787.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. 들판의 논둑을 따라 대체로 3∼4m 씩 사이를 두고 11기의 고인돌이 있다. 형태상 모두 바둑판식으로 덮개돌의 크기는 길이 3m, 너비 2m이다.","a":"남해 다정리 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655071.jpg"},{"q":"원주 ○○○○○ 소장 ○○○○○은 정조 1년(1777) 전남 화순의 ○○○에서 중간한 목판본으로, 독특한 국문표기법을 비롯하여 한글 자모의 용법을 설명한 언본과 범자가 한글로 설명되어 있는 등 국어학 연구에 중요한 자료적 가치를 지니고 있다.","a":"원주고판화박물관소장만연사중간진언집","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660665.jpg"},{"q":"○○○ 석불입상은 조각수법에서 세련미는 약하나 지역불상의 특징을 나타내는 고려시대 거불이 조선시대에 이어지는 석불양식의 변천을 알려주는 불상으로 작례가 많지 않아 희귀성이 있는 귀중한 석불임. 옛날의 절 터인 듯한 공간에 전면 측면 각각 1칸이 맞배지붕의 보호각 안에 서 있다. 석불은 나발의 머리에 아주 낮은 육계가 있는 듯하며 이마 중앙에는 白毫가 음각으로 파이고 눈썹은 뚜렷하게 반달을 이루며 코와 연결되어 야무진 코를 만들었다. 눈은 약간 도드라졌으나 명확하지 않고 입은 작게 선각으로 이루어졌다.","a":"제천 두학동 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638865.jpg"},{"q":"여주 ○○○에 있는 ○○○○는 크기와 용도를 달리하여 모두 3기가 있다. 큰 가마는 큰 항아리를 굽는데 사용하며 현재 가장 많이 사용하고 있다. 이 가마는 대략 100년 전에 만들어진 것으로 바닥의 길이가 40m가 넘으나, 점차 옹기 일이 줄어들면서 장작을 효율적으로 사용하려고 뒷부분을 잘라내서 24.5m로 줄였다. 가마 옆 부분에는 창 불을 때는 창구멍이 나 있다. 중간크기의 가마는 길이가 약 10.7m정도 되며, 통가마와 구조와 거의 비슷하지만 규모가 작아 ‘뫼통가마’라 혹은 ‘작은대포가마’라고 부른다. 이 가마는 소품이나 반오지그릇을 굽는 데에 사용한다.","a":"여주이포리옹기가마","c":"시도민속문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658178.jpg"},{"q":"용원동 앞 바다에 잡목으로 뒤덮인 섬을 망산도, 이 섬의 동남쪽 70m 해상의 바위섬을 유주암이라 부르는데 모두 가락국 김수로왕의 왕비인 허태후와 관련된 전설이 있는 곳이다. 가락국의 수로왕이 도읍을 정한 지 7년만에 신하들이 왕비를 맞아들일 것을 얘기하자 ‘짐이 이땅에 내려온 것은 하늘의 뜻이며, 왕비 또한 하늘이 주실 것’이라 하였다. 신하들에게 바닷가에 나가 기다릴 것을 명령하여 기다리니, 서남쪽 해상에서 붉은 깃발을 휘날리며 배 한 척이 다가왔다.","a":"창원 유주비각","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655288.jpg"},{"q":"○○○는 통일신라 경덕왕 때 지었다고 전하는데, 지금 있는 건물은 조선 인조(재위 1623∼1649)때 진묵대사가 지은 것이라고 한다. 1933년과 1977년에 고쳐 지었다. 악서전의 지붕은 옆면에서 볼 때 여덟 팔(八)자인 팔작지붕이며, ㄱ자형 평면을 갖춘 건물이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짜올린 익공 양식으로 꾸몄다. 앞으로 나온 한 칸은 마루를 놓았고, 그 위에는 최근에 만든 종이 걸려 있다. 건물 오른쪽에는 방과 부엌이 있어서 악서전이 법당 겸 요사로 사용되었음을 알 수 있다.","a":"망해사낙서전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661761.jpg"},{"q":"예천 양씨의 건의로 지은 건물이다. 순조 10년(1810)에 금수서당으로 세웠다가 ‘금수서숙’으로 이름이 바뀐 후 1928년에 이 마을의 임씨 시조인 임억숙(1546∼1605)의 묘소를 수호하고 제사를 지내는 곳으로 기능을 바꾸었다. 이 건물은 대들보에 적힌 기록으로 보아 헌종 15년(1849)에 새롭게 고친 것으로 19세기 서당 건물의 특징을 잘 간직하고 있다. 관리자가 거주하던 왼쪽 건물은 안동지역에서는 보기드문 ㄷ자형 평면구성을 하고 있다. 이곳에서는 해마다 음력 10월 3일에 제사를 지낸다.","a":"금곡재","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663014.jpg"},{"q":"강릉 오죽헌시립박물관의 앞뜰에 놓여 있는 비의 받침돌로, 거북의 모습을 하고 있다. 바닥돌과 하나의 돌로 이루어진 이 받침돌은 거북의 목이 짧고 얼굴은 등과 거의 수평을 이루고 있다. 얼굴에는 눈, 코, 입, 귀, 갈퀴가 얇게 표현되어 있으며, 턱 밑으로는 역삼각형의 수염이 조각되어 있다. 4개의 발가락이 있는 앞발은 등껍질의 앞쪽 아래에 돌출되어 있고, 부서져 있는 뒷발은 움츠린 형태이며, 꼬리는 오른쪽으로 돌려져 있다. 6각형의 무늬가 가득 채워진 등에는 그 중앙에 비를 꽂아두기 위한 네모난 홈을 두었다.","a":"강릉귀부","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660302.jpg"},{"q":"○○○○는 첨모당 임운 선생이 살던 곳으로, 그의 아들 서간 임승신 선생이 덕행과 학문을 닦던 곳이다. ○○○○가 있는 경남 ○○군 갈계리는 대부분이 임씨로 씨족마을을 이루고 있는 곳이다. ○○○○는 이 마을의 종가 구실을 하고 있는 임씨 고택의 서쪽에 자리잡고 있다. 이곳은 살림채 없이 대문채와 사랑채로 이루어진 것이 특징으로, 본래 임씨 고택과 ○○○○가 하나의 주거 영역이 아니었나 추측하게 한다.","a":"거창 서간소루","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664481.jpg"},{"q":"이 불화는 ○○○ 대웅전의 향우측벽에 봉안되어 있는 ○○○로, 여러 부분에 오염으로 인한 얼룩이 있으며, 현재는 액자에 끼워 봉안하고 있는데 전체적으로 채색이 변색되어 어두운 편이다. 그림 상단에는 범천(梵天)과 제석천(帝釋天)을 중심으로 천부중(天部衆)을 배치하였으며 하단에는 위태천(韋駄天)을 중심으로 천룡팔부(天龍八部)를 표현하였다. 범천과 제석천은 보살 옷에 보관을 쓰고 두 손을 모아 흰 연꽃을 들고 정면을 향해 서있는데 그 주위로는 일궁천자와 월궁천자를 비롯하여 당(幢)과 번(幡), 부채 등의 장엄구를 든 동자, 동녀들과 주악천 등이 둘러싸고 있다.","a":"개운사 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593257.jpg"},{"q":"○○○○○는 1895년 상무회의소 구례의 제정 공포로 설립되어, 진주. 곤양, 하동, 남해, 고성, 진남(통영), 함안, 단성, 산청, 삼가, 함양, 안의, 거창, 합천, 초계, 의령 등 17개 지역을 관할구역으로 보상과 부상의 권익을 보호하고 상업활동을 관장하던 조선후기의 상업기관이다. 처음에는 읍내에 위치하였다가 1936년 대홍수로 인하여 유실된 것을 1938년에 지역의 경제인들이 힘을 모아 지금의 위치에 새로 건립하여 지금까지 유지되어 왔다. 전통목조기와집으로 남아있는 상무사건물이 드물어 상징적 자료로서의 가치가 매우 높다.","a":"진주상무사","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022560701.JPG"},{"q":"정려는 나라에 공을 많이 세운 사람이나 효자·열녀의 집앞에 나라에서 세운 붉은 문이다. 이곳은 김장생의 7대 할머니인 허씨의 정려이다. ○○○○는 태조(재위 1392∼1398) 때 대사헌을 지낸 허응의 딸로 김간과 결혼했는데 17세의 나이로 혼자가 되었다. 이에 친정부모가 재혼시키려 하자 시댁이 있는 연산지방에 아들을 데리고 와서 훌륭히 키우고 일생을 마쳤다. 이런 사실이 조정에 전해지자 세조 13년(1467)에 정려를 세웠다. 이후 광산 김씨 가문에서 김장생·김집 등을 비롯하여 많은 문인과 학자가 배출되었다.","a":"고정리양천허씨정려","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639200.jpg"},{"q":"전북특별자치도 정읍시 ○○○에 있는 돌로 된 입불상이다. 머리에는 마치 갓과 같은 테가 큰 모자를 쓰고 있어 유교적인 성격이 가미되었음을 알 수 있다. 어깨는 다소 움츠린 모습이며, 턱 밑에는 U자형의 옷주름이 있다. 배 아래에서는 옷주름이 V자형으로 처리되었고, 손목 아래에는 3줄의 평행선이 내려지고 있다. 오른손은 어깨 높이로 들어 손바닥을 보이며 손끝은 위를 향하고 있다. 왼손은 마찬가지로 손바닥을 보이는데 손끝이 땅을 향하고 있다. 얼굴 표현과 손 표현에 노력이 집중된 불상으로 민속적인 특색을 띠고 있다.","a":"망제동석불입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639545.jpg"},{"q":"이치는 대둔산 중허리를 넘어 전북 완주군으로 통하는 교통의 요지이며 전략상 중요한 곳이다. 1592년 임진왜란 당시 경상도와 충청도를 휩쓸고 승승장구 하던 2만여 병력의 일본군이 호남으로 나아가 군량미를 얻고자 이곳을 넘으려 하였다. 이 때 먼저 길목을 지키고 있던 권율장군이 동복현감 황진과 1,500여명의 군사를 이끌고 결사적으로 싸워 일본군을 격퇴하였다. 이로써 전주성과 호남평야를 지킬 수 있었다. 임진왜란의 첫 승리를 장식한 이 싸움을 ○○○○ 또는 이치싸움이라고 하며, 여기에 힘입어 이후 권율장군은 행주대첩과 웅치싸움을 승리로 이끌 수 있었다.","a":"금산 이치대첩지","c":"시도기념물","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653095.jpg"},{"q":"임지왜란 당시에 벽진 이씨가 정착하여 살았던 집으로 통일신라와 고려시대부터 취락이었던 곳이다. 울타리와 담장은 흙담에 기와를 얹었고 우물과 장독대 등이 있으며 벽진 이씨의 자손들이 지금까지 살고 있다.","a":"창녕 부곡리 이씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664069.jpg"},{"q":"이곳은 A.D 42년 낙동강을 중심으로 일어난 여섯 가야(伽倻) 중 하나인 ○○○○ 태조의 무덤이라고 전해오고 있다. ○○○○는 낙동강 일대인 함창, 문경, 가은 지방을 영역으로 하여 세워진 나라로,『삼국유사』의 5가야조와『삼국사기』의 고령군조에 그 이름이 보이고 있다. 조선 선조 25년(1592) 당시 경상도 관찰사 김수와 함창 현감 이국필 등이 묘 앞에 묻혀 있던 묘비를 발견하여 ○○○○임을 확인했다고도 전해오고 있다. 그 후 조선 숙종 38년(1712) 왕명으로 묘비와 석양(石羊) 등의 석물을 마련한 후 후손들에 의해 여러 차례 묘역이 정비되어 오늘에 이르렀다.","a":"전고령가야왕릉","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654431.jpg"},{"q":"고흥 ○○○○○은 금산면 거금도의 어전리와 석정리 일대에 위치하는데, ○○○는 거금도의 조선시대 지명이다. 이 성은 적대봉(592.2m)과 용두봉(418.6m)의 중간 계곡을 형성하는 부분과 두 봉우리가 연결되는 능선의 움푹 들어간 부분에 위치하고 있으며, 성을 중간으로 나눈 남북방향으로 축성되어 있다. 성은 완만한 구릉이 형성되어 있는 부분의 서쪽 사면 끝자락에 위치하며, 남쪽으로는 해안선까지 이어진다.","a":"고흥절이도목장성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020052414042300.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 북제주 애월읍 하귀리의 한천변 주택가 경작지에 있는 바둑판식 고인돌이다. 이 고인돌의 규모는 덮개돌이 3.61m, 폭 1.92m 정도이며 덮개돌 아래 북쪽과 동쪽에 받침돌 2개를 고였고 지대가 높은 남쪽은 작은 돌 하나를 고였다.","a":"하귀지석묘 1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657681.jpg"},{"q":"김관은 고려시대의 장군인 김취려의 9세손으로 조선 세종 29년(1447) 사마시를 거쳐 조선 문종 1년(1451) 증광문과에 급제하여 승문원정자·형조좌랑·병조정랑 등을 지냈다. 조선 세조 13년(1467) 이시애의 난이 일어났을 때 공을 세워 적개공신이 되었고, 강원도·충청도·황해도·영안도·전라도 관찰사를 지냈다. 영정각(影幀閣)에 봉안되어 있는 영정의 크기는 가로 88㎝, 세로 154㎝, 인물크기 139㎝이다. 이 영정은 조선 초기 양식으로, 얼굴은 밝은 연주황색으로 칠하고 갈색선으로 윤곽을 그렸으며 입술은 붉은 연지색으로 하였다.","a":"김관영정","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638270.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 봉암사 뒤쪽 기슭에는 3기의 부도가 자리하고 있는데, 이 부도도 그 중 하나로, 조선시대 중기의 승려인 ○○○의 사리를 모셔두고 있다. ○○○은 ‘지경’이라 불리기도 하였는데, 16세에 승려가 지켜야 할 계율을 받고 팔공산 동화사에 들어가 성현대사의 가르침을 받았다. 21세에는 청량산에 들어가, 그 곳에서 31년간 곡식대신 솔잎·밤·대추 등을 먹으며 지내었다. 88세에 해인사의 백련암이라는 암자에서 생을 마치었다.","a":"환적당지경탑","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662659.jpg"},{"q":"조선 중기 문신 송희건(1572∼1633)의 제사를 모시고 있는 재실이다. 선생은 사마시와 대과에 급제하고 금정도 찰방과 안동대도호부 판관 등을 지냈으며, ○○○는 그의 호를 따서 붙인 이름이다. 앞면 5칸·옆면 2칸 규모이며 ㄱ자형으로 배치되어 있는데, 가운데 3칸에는 넓은 대청마루가 있고 그 양 옆으로 안방·부엌 그리고 건넌방이 있다.","a":"월송재","c":"문화유산자료","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659736.jpg"},{"q":"조선 세종 때의 재상인 고불(古佛) ○○○ 선생의 묘이다. ○○○은 『태종실록』을 감수하고, 『팔도지리지』를 편찬하였으며, 향악을 정리하고 악기를 만들어 조선 초기 문화 발전에 크게 기여하였다. 묘역은 최근에 정비를 하여 원형이 거의 없어졌는데, 봉분 하단에 직사각형의 둘레석에서 조선 초기 묘제의 흔적이 남아있다. 석물은 옛 것과 현대 것이 섞여 있는데, 봉분의 둘레석·묘표(墓表 ; 무덤 주인의 이름 등을 새긴 비석)·문석인만 옛 것이고 나머지 신 묘표·상석·향로석·동자석인·망주석은 모두 최근에 만든 것이다.","a":"맹사성선생묘","c":"시도기념물","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645965.jpg"},{"q":"○○○○○은 남한지역에서 최초로 확인된 구석기시대의 동굴유적이며, 조선계 석회암지대에 발달된 구석기시대의 동굴유적으로 용두산 동남향 사면 중간쯤의 병풍바위 끝부분에 위치하고 있으며, 동굴을 중심으로 근처에 6개의 가지굴이 발달되어 있다. 1973~1980년까지 8차에 걸쳐 연세대 박물관에서 발굴조사를 실시한 결과 전기·중기·후기 구석기문화의 뚜렷한 3개의 문화층이 발달되어 있는 것으로 밝혀졌다.","a":"제천 점말동굴 유적","c":"시도기념물","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650737.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 무학산 줄기인 해발 265m ○○○에 있는 ○○○○○는 고려 말기에 왜구의 침입 등 위급 상황을 서울에 알리기 위한 신호수단으로 쌓은 것으로 추정된다. 이곳 ○○○○○는 동래에서 서울 목멱산(지금의 남산) 중앙 봉수에 이르는 봉화 선로를 연결하고 있다. 처음 동래 다대포 ○○○에서 시작하여 진해 고산○○○, ○○○○○, 함안 칠서 안곡산 ○○○, 창녕 소산 ○○○를 거쳐 최종적으로 서울 목멱산 ○○○로 이어졌다.","a":"창원 봉화산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655925.jpg"},{"q":"조선 전기의 문신인 ○○○ 선생을 추모하기 위해 세운 비이다. ○○○○○ 선생은 김종직의 문인으로, 성종 16년(1485) 별시문과에 급제하여 사간원정언, 성균관전적 등의 벼슬에 종사하였다. 연산군의 어지러운 정치를 강직한 언행으로 아뢰다가 왕과 훈구파에게 미움을 받아 무오사화 때 유배되었으며, 연산군 10년(1504) 갑자사화에 관련되어 처형당하였다. 중종 반정 후 명예가 회복되어 도승지 겸 예문관직제학에 추증되었다. 비는 네모난 받침돌 위에 거대한 비몸돌을 세우고 머릿돌을 올린 모습이다.","a":"오졸재박한주여표비및비각","c":"시도기념물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654571.jpg"},{"q":"이 집은 정방형에 가까운 대지의 안쪽으로 안채를 배치하고 안채의 좌측 아래로 아래채를 두었으며, 안채의 좌측 위쪽으로는 곳간채를 두었다. 안채는 정면 7칸, 측면 2칸 반 규모의 전퇴집이고, 아래채는 정면 4칸, 측면 2칸의 'ㅡ'자형이며, 곳간채는 아래채에 못지않은 큰 규모의 흙벽으로 되어 있다. 이 집은 1924년 지어져 조선후기 건축의 특징인 측면간의 확장을 볼 수 있으며 겹지붕 형식이라는 특징도 가지고 있어 학술적 가치가 있다.","a":"산청 박인현 고택","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666408.jpg"},{"q":"이 불상은 암벽의 한면을 평평하게 다듬어 선각한 것으로 두광과 신광을 갖추고 연화좌 위에 결가부좌 하였다. 머리에는 육계가 솟아 있으며 갸름한 얼굴에는 눈, 코, 입 등이 얕게 새겨졌다. 신체는 어깨가 넓고 무릎의 폭이 안정되어 강건한 느낌을 주는데 오른손은 가슴위로 들어올리고 왼손은 왼쪽무릎에 대고 있어 아미타불로 생각된 U자형으로 넓게 터진 통견의 법의에는 비스듬히 승각기로 표현되었으며, 팔 위에 걸쳐 몇가닥의 옷주름이 선각되었다. 앙련과 복련의 연화대좌도 단판의 연꽃을 간단하게 선각처리 하였다.","a":"김해 구산동 마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641799.jpg"},{"q":"전북특별자치도 정읍시 영원면 해정사 절터의 남북쪽 산기슭 탑동마을에 위치한 높이 96㎝의 좌상이다. 머리가 없어진 상태이며, 풍화가 심해 세부표현이 잘 보이지 않는다. 옷은 양 어깨를 감싸고 있으며, 양 손은 가슴에 모으고 있어 비로자나불을 표현한 것으로 생각된다. 4각형 대좌(臺座)의 아래와 위에는 연꽃이 조각되어 있다. 대좌의 형태와 연꽃무늬 등으로 보아 고려 초기의 작품으로 추정된다.","a":"후지리탑동석불","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639511.jpg"},{"q":"설악산 동쪽 기슭에 있는 ○○○에 있으며, 조선 영조 46년(1770)에 세워진 것으로, 장대석으로 2단 쌓은 기단 위에 정면 7칸, 측면 2칸의 홑처마 맞배지붕 건물이다. 이 건물은 극락보전을 중심으로 운하당과 적묵당이 있는 마당을 둘러싸 사찰 중심 영역의 공간성을 확보해 준다. 건물의 하부는 기둥으로만 구성된 열려 있는 공간으로 극락보전으로 가는 통로가 된다. 조선 후기로 갈수록 규모가 커진 모습을 보여주는 ○○○ 내에는 법고와 목어, 대종, 경판이 보관되어 있고 몇몇의 현판과 중수기가 걸려 있다.","a":"신흥사 보제루","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638122.jpg"},{"q":"○○○○는 서왕모(西王母)의 거처인 곤륜산(崑崙山) 요지(瑤池)에서 열리는 연회장면을 그린 것으로 총 8폭의 병풍에 담은 것이다. 중국의 옛 문헌인『죽서기년 竹書紀年』과『목천자전 穆天子傳』에 실린 서왕모와 주목왕(周穆王)의 연회에 군선(群仙)들이 초대되어 가는 이야기가 결합된 고사에 연원을 둔 것이다. 화면 중앙 4～5폭에 서왕모와 그녀를 방문한 주목왕(周穆王)의 연회가 베풀어지는 장면이 위치해 있고, 7～8폭에는 여러 신선들이 그 곳을 향해 바다를 건너오는 모습이 생동감 있게 그려졌다.","a":"요지연도","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637753.jpg"},{"q":"○○○<新興寺>는 진덕여왕<眞德女王> 3년(889) 범일국사<梵日國師>가 창건<創建>하여 지흥사<池興寺>라 하였는데 조선<朝鮮> 현종<顯宗> 15년(1674) 현위치로 이전하여 광운사<廣雲寺>라 하였고, 후에 다시 운흥사<雲興寺>로 개칭하였다. 영조<英祖> 46년(1770) 화재로 소실<燒失>된 것을 중건하고 순조<純祖> 21년(1821) ○○○<新興寺>라 개명하였다.","a":"삼척신흥사설선당및심검당","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660536.jpg"},{"q":"요지란 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. 부여도서관 곁에 있는 ○○○ 가마터는 일찍부터 4각형, 원형의 건물 주춧돌이 드러나 있었고, 연꽃무늬 수막새 등의 유물이 출토되어 절터로 알려졌었다. 그러나 조사 결과 백제 토기 또는 기와나 벽돌을 굽던 곳으로 밝혀졌다. 연꽃무늬 와당, ‘대당(大唐)’이라 쓰여진 와당이 출토되었으며 인(寅), 병(丙), 사(斯), 오(午), 지(止)의 도장이 찍혀 있는 기와조각이 많이 출토되었다. 아울러 백제 유물로 추정되는 화강암으로 만들어진 네모난 모양의 주춧돌이 발견되었다.","a":"부여쌍북리북요지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652733.jpg"},{"q":"고려시대 문신인 성사달(?∼1380)을 비롯하여 성부·성여원·성무조 등 창녕 성씨들의 위패를 모시고 있는 사당이다. 성사달은 충혜왕 2년(1341) 문과에 급제하고 한림사성이 되었다. 공민왕 1년(1352) 억울하게 옥살이를 하였으나 곧 복직되었다. 1362년 홍건적이 침입했을 때 왕을 호위하였으며 김용의 난을 평정하여 1등공신이 되었다. 그 뒤 1364년 교주도병마사로 여진의 침입을 막아 대제학에 올랐으며 창산 부원군에 봉해졌다. 문장과 글씨에도 뛰어났으며 죽은 뒤 문효란 시호를 받았다.","a":"송양사","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661827.jpg"},{"q":"1636년(인조 14)에 ○○○사 정양필이 창건하고, 1711년(숙종 37) ○○○사 이정신이 ○○○으로 편액을 붙여 조선시대 말기까지 ○○으로 사용되었다. 일제시기 이후에는 동래군청 청사로 사용되다가 1973년 동래군 이 양산군으로 편입됨에 따라 양산군 보건소 동래지소로 사용되었고, 1977년 부산광역시에서 매입하여 초석 이상을 해체복원하여 지금까지 보존되고 있다. 이 건물은 ○○○사 등 동래의 수령이 일을 처리하던 곳으로 지금의 부산광역시장 집무실과 비슷하다. 지붕은 팔작지붕이고, 처마는 겹처마이며, 천장은 연등천장이다.","a":"동래부 동헌 충신당","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636597.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배 안에 넣어서 보관하던 유물 가운데 하나이다. 불경을 한글로 풀이한 언해본과 불경의 내용을 판화로 풀이한 것을 합쳐 모두 13종 17책에 이른다. 한글로 번역된 불경에는 화엄사상을 담은 『묘법연화경』과 원나라의 승려 몽산화상의 법어를 모은 『몽산화상법어약록』, 그리고 부모에 대한 효를 강조한 『불설대보부모은중경』 등이 포함되어 있다.","a":"보림사사천왕상복장언해판화관계불서","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814404200.jpg"},{"q":"오리 이원익의 5대손인 이인복(李仁復, 1683~1730)과 그의 아들 이언충(李彦忠, 1716~1776)이 의금부도사로 있었을 때 소유했던 것이다. 이인복이 소유한 ○○○○ 4점[제작시기 : 1713년(숙종 39) 12월, 1714년(숙종 40) 5월, 1714년 9월, 1714년 11월]은 그가 의금부도사에 임명되어 14개월 동안 재직하는 동안 후배 관리들로부터 받았으며, 이언충이 소유한 ○○○○ 1점[제작시기 : 1756년(영조 32)]은 그가 의금부도사가 된 뒤 면신례를 준비하기 위해 제작한 것이다.","a":"광명 금오계첩","c":"문화유산자료","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660291.jpg"},{"q":"이 책은 테두리는 상하단변(上下單邊)으로 10행에 1행 19자이다. 책 앞머리에는 정씨(鄭氏)라는 사람의 시주로 고려(高麗) 우왕(禑王)의 극락왕생(極樂往生)을 위해 변상(變相)을 그리고 목판에 새겨 유통한다는 글이 담긴 변상도(變相圖)가 있다. 이어 송(宋)의 급남화상(及南和尙)이 쓴 ○○○○○요해서(妙法蓮華經要解書)가 나오며 본문(本文)에는 묵서(墨書)로 쓴 구결(口訣:한문 원전(漢文原典)을 읽을 때 그 뜻 및 독송(讀誦)의 편의를 위하여 각 구절 아래 달아 쓰는 문법적 요소의 총칭)과 두주(頭註:책자에서 본문 페이지의 위쪽에 넣는 주(註))가 있다.","a":"묘법연화경 권1~3","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638880.jpg"},{"q":"경은 이맹전(1392∼1480)의 학덕과 충절을 추모하기 위하여 지은 서원이다. 이맹전은 조선 단종(재위 1452∼1455)을 위하여 수절한 생육신의 한분으로, 수양대군이 어린 단종의 왕위를 탐내자 벼슬을 버리고 고향으로 돌아가 학문을 닦으며 일생을 보냈다. 정조 6년(1782)에 왕명으로 토곡동에 건립된 ○○○○은 고종 5년(1868) 흥선대원군의 서원철폐령으로 인해 노항동으로 옮겨 서당으로 사용되다가, 1976년 영천댐 건설로 인하여 지금의 위치로 옮겨졌다. 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕을 올린 누각건물이다.","a":"용계서원","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640342.jpg"},{"q":"주암리는 옥천 조씨가 500년 이상 대대로 살아온 터로, 이 재실은 맨 처음 이 곳에 자리잡은 사람인 조유를 제사 지내기 위해 문중에서 세운 건물이다. 기록에 의하면 건립 당시에는 담장 내에 재실과 서당, 행랑채를 둔 것으로 되어있어 서당과 제향의 기능을 동시에 수행하였던 것으로 보인다. 지금은 대지의 상단 동쪽에 신주를 모신 사당을, 하단 북쪽에 제사 음식을 준비하는 전사청을, 앞면에 문간채를 두어 담장을 둘렀다. 재실은 一자형 기와집 형태로, 옆면에서 보아 사람인(人)자 모양을 한 맞배지붕을 올리고 있다.","a":"순천 정헌재","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658398.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. ○○○터에 자리하고 있는 이 부도는 신라 진평왕 때의 승려인 ○○○○의 사리를 모시고 있다. ○○○○는 화랑도의 생활신조인 세속오계를 제정한 인물로, 불교사상 뿐만 아니라 문장에도 능하여『걸사표』를 지어 중국 수나라에 보내기도 하였다. 진평왕 52년(630) 황룡사에서 돌아가시어 명활산에서 장사를 지낸 후 이곳에 그의 사리탑을 세웠다. 부도는 부서진 채 일부만 남아있던 것을 최근에 새로이 복원한 것으로, 3층 석탑의 형식을 하고 있다. 널다란 바닥돌 위로.","a":"금곡사지원광법사부도탑","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662557.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○ 고인돌은 기원전 1세기 경에 축조된 것으로 전형적인 바둑판식에, 지석을 여러 매 괴거나 상석이 아치 모양을 이루는 제주 형태를 취하고 있다.","a":"신례리지석묘1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657694.jpg"},{"q":"조선 중기의 문신인 ○○○ 선생의 초상화 2폭으로, 전신상 1폭과 얼굴초상 1폭이다. ○○○는 조선 인조의 외종 사촌으로, 공조좌랑 ·공주목사 ·판중추부사 등을 지내었다. 전신상은 오른쪽을 바라보며 호랑이 가죽이 깔린 의자에 앉은 모습으로, 머리에는 사모를 쓰고 자주색 비단의 관복을 입고 있다. 가슴에는 두 마리의 학과 구름무늬를 둔 흉배가 표현되어 있고, 관대를 둘렀다. 얼굴 초상은 전신상 중에서 얼굴 부분만 따로 옮겨 그린 것으로 보인다. 전형적인 조선 중기의 공신도 모습이다.","a":"홍진도선생영정","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661424.jpg"},{"q":"○○○○○은 전통마을인 한개마을의 중심부에 남서향으로 위치한 조선후기 양반 주택으로서 정확한 건립 연대나 내력은 알 수 없으나 1630년대의 건물로 추정된다. 당호(堂號)는 현 소유자의 모친이 안동 하회(河回)에서 시집온 데서 연유한다. 가옥의 배치는 ‘ㄷ’자형 평면의 안채를 중심으로, 전면에 일자형 평면의 중문채가 튼 ‘ㅁ’자형의 배치를 이루면서 정침 우측으로 독립된 사랑채가 자리하고 있다. 사랑채와 정침이 흙담으로 분할되어 남녀 공간 구분이 확실하며, 그 사이에 협문을 내어 내외를 연결시키고 있다.","a":"성주 대산리 하회댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658986.jpg"},{"q":"조선 헌종(재위 1834-1849)이 진주 하씨 집안 대대로 충효가 지극한 것을 칭찬하고자, 학행과 효성이 지극한 하준호에게 ‘운초재’라는 호를 짓고 목판에 새겨 내려주면서 세운 건물이다. ○○○은 임금이 직접 글씨를 써서 내려준 건물이라는 뜻이다. 왕의 글씨가 담긴 목판뿐만 아니라, 당시 영의정이었던 전병국이 쓴 『운초재』서문과 신응조가 쓴 『○○○명병기』를 목판에 새겨 함께 보존하고 있다.","a":"장포리어필각","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661760.jpg"},{"q":"나주 ○○○○○은 ○○○○ 발굴조사(발굴조사기관：전남문화재연구원)에서 2001년 9월 16일 출토된 불상이다. 이 불상은 통일신라시대 불상으로 광배와 몸체와 대좌가 함께 주조되어 있는 특징이 있다. 육계는 비교적 두텁고 높게 솟아 있으며 머리는 언뜻 보면 소발처럼 보이나 자세히 보면 오랜 세월동안 마모상태가 심한 편이긴 하나 나발의 흔적이 역력하다. 더구나 이 나발은 육계부분까지를 포함하고 있다. 상호는 호형의 예리한 눈썹과 일자형의 눈모습인데 눈두덩이 두툼하게 돋아난 행인형 모습이다.","a":"나주운흥사지금동여래입상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051719101000.JPG"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 영월에 향교가 지어진 것은 태조 7년(1398)으로 전한다. 1950년 한국전쟁 때 대성전을 제외한 모든 건물이 불에 탔으며, 1973년에 대성전을 고쳤다. 현재 남아있는 건물로는 대성전과 정문인 풍화루 등이 있다. 조선시대에는 국가로부터 토지와 노비·서적을 지급 받아 학생들을 가르쳤으나 갑오개혁(1894) 이후 새로운 학문으로 인해 교육적 기능을 잃고 봄·가을 2차례에 걸쳐 공자에게 제사를 지내고 있다.","a":"영월향교","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638110.jpg"},{"q":"○○○○○은 정면 5칸, 측면 2칸의 2층 누각 형식으로 되어있는데 평면과 구조는 이 지역의 정자와 다른 독특한 모습으로 되어있다. 중앙 2칸은 모두가 수납공간(광)으로 꾸며져 있고 양측은 완전히 분리된 별도의 누마루로 구성되어 있고 누마루 3면은 모두 벽체 구성없이 열려있다. 양측 2개의 누마루에서는 규모나 부재사용면에서 다르게 구성된 특징이 있으며, ○○○은 강회정과 함께 향촌공동체의 중심공간으로서 조선후기 공동체의 조직과 운영에 관한 자료들이 전해져 향토사나 건축사적으로 연구가치가 충분한 유적이다.","a":"강진 여택정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662330.jpg"},{"q":"조선 영조 4년(1728)에 무신 ○○○에게 이인좌와 정인량의 반란을 평정한 공로로 분무공신 2등에 봉한다는 공신록 1점과 교지 2점이다. ○○○은 본관이 언양이고, 자는 원중(元重)이다. 공신록은 두루마리 형태로 표지 제첨에 “奮武功臣二等金重萬”이라 적었다. 1728년 7월에 작성되었고 1등 공신 1인, 2등 공신 7인, 3등 공신 7인 등 총 15인의 공신명단과 포상내용이 기록되어 있다. 2등공신 ○○○에게 녹훈된 구체적인 포상내용을 살펴보면, 품계는 2계급 올려주고, 적장자가 그 봉록을 세습하도록 하였고, 노비, 전답, 은자, 내구마 등을 하사하였다.","a":"김중만장군사패교지","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637552.jpg"},{"q":"조선 태종의 장남 경령군의 ○○ 청풍 ○○의 묘이다. 태종 16년(1416)에 경령군과 혼인을 하였으며, 태종 17년(1417)에 안산군○○으로 봉해졌다. 세종 32년(1450) 4월 죽어서 현 위치에 장례하였다. 세조 4년(1458) 9월에 삼한부○○으로 봉해지고 고종 9년(1872)에 청원부○○으로 봉해졌다. 이 ○○는 다른 곳에서 보기 힘든 왕족의 4각형 묘로서 봉분 아랫부분에 둘레석을 둘렀으며, 묘 앞에는 묘비가 있고 좌우에는 문인석이 있다.","a":"음성 경녕군 부인 김씨 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650377.jpg"},{"q":"초계 정씨의 시조인 정배걸이 후진을 양성하기 위해 세운 서원이다. 정배걸은 고려 전기의 학자로 고려 현종 8년(1017) 문과에 장원급제하고 제자들을 가르치는 데에 힘썼던 분이다. ○○○○을 세운 시기는 알 수 없으나, 철종 12년(1861)과 1981년에 고쳐 세워 오늘에 이르고 있다. 앞면 4칸·옆면 2칸 규모의 건물로, 가운데 2칸은 마루로 구성하고 양 옆으로 온돌방을 두었다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 양 옆 지붕 아래에는 바람을 막기 위한 풍판을 달았다.","a":"합천 옥전서원","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664321.jpg"},{"q":"○○○○○은 근래에 개금(改金) 불사를 하여 보존 상태는 매우 양호하다. 불상 바닥 면에 복장공이 있으며, 범어가 적힌 한지로 막아놓았다. 불상 조성 당시의 복장물은 도난을 당해 존재하지 않으며, 1996년 개금불사를 하면서 복장물을 새로 조성하여 봉안한 상태이다. 본 ○○○○○은 ○○○ 주불전의 본존으로 봉안된 불상으로, 양손은 결가부좌한 무릎 위에 올려 항마촉지인을 취하고 있다. 신체에 비해 머리가 크고 어깨와 무릎이 좁으며, 고개가 오른쪽으로 약간 기울어져 있다.","a":"척판암석조여래좌상","c":"문화유산자료","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659388.jpg"},{"q":"○○○ 아미타삼존불 후불벽에 걸었던 3폭으로 화기(畵記)는 박락되었지만 삼장보살도와 같은 시기인 1747년에 조성된 것으로 추정된다. 아미타불을 중심으로 관음보살과 대세지보살이 각각 독립된 폭으로, 현존 실내 봉안 불화 중 가장 규모가 크다. 중앙의 아미타불화는 아미타불을 화면 가득히 크게 묘사하고, 지장과 미륵보살, 문수와 보현보살이 협시하고 있고, 상단에는 두 벽지불(壁支佛)이 자리잡고 있다. 색채는 짙은 진홍과 녹색의 강한 보색 대비에 밝은 청색과 호분의 배합을 사용하였으며, 특히 담채로 은은한 분위기를 연출하고 있다.","a":"무량사극락전후불탱","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051415235700.jpg"},{"q":"○○ 어곡리 ○○○○○는 ○○○이 3.1운동 다음해인 1920년 ○○ 어곡리에 별장처럼 따로 지은 정자이다. ○○○은 조선 후기 의금부도사와 통정대부의 벼슬을 지낸 인물이다. ○○○○○에는 소한정과 세심당이라는 2개의 정자가 있으며, 세심당의 4벽에는 ‘소한정’·‘쌍청각’·‘세심당’·‘신선암’·‘삼미천’·‘도원’·‘죽원’이라고 새긴 현판들이 걸려 있다. 정자 주위에는 대나무·백일홍·매실나무·회화나무 등을 심어 놓았고, 시냇물이 흐르는 아름다운 자연경관에 신선사상에 입각한 12개의 이름을 각각 붙인 것이 특이하다.","a":"양산 우규동 별서","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664284.jpg"},{"q":"○○○○○는 충렬공 ○○○ 선생의 생애, 행적을 기록한 비로 귀부, 비신, 가첨석를 갖추고 있으며 건립연대는 18세기 경으로 추정되고, 비의 글은 영의정 윤두수의 아우로 형조ㆍ이조ㆍ예조판서를 지낸 윤근수(1537~1616)가 지었으며 글씨는 제봉의 7대손이며 돈녕부도정(敦寧府都正)을 지낸 수촌(水村) 고정봉이 썼다.","a":"장성 고경명 신도비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020121609540000.jpg"},{"q":"○○○은 조선 중기 문신이자 성리학자인 여헌 장현광(1554∼1637)이 임진왜란 이후에 살던 집으로 청천당과 사당인 여헌묘우로 구성된다 장현광은 조선시대 학자로 선조 9년(1576)에 벼슬에 나간 뒤 좌랑을 거쳐 공조참판을 역임하였다. 인조14년(1636) 병자호란이 일어나자 의병들의 궐기를 촉구하고 군량미를 모으는 등 적극적으로 활동하였으나 이듬해 청에게 항복했다는 소식을 듣고 입산하여 여생을 보냈다.","a":"모원당","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663277.jpg"},{"q":"조선 후기에 벼슬을 지낸 박치기가 1870년에 세운 정자이다. 박치기는 벼슬에서 물러나 심신을 단련하기 위해 이 정자를 지었다고 한다. 그래서 정자 이름을 ‘○○○’이라고 하였다. 정자 앞으로는 시냇물이 흐르고 뒤에는 암석이 높게 솟아 있다. 받침부에 사각형 주춧돌을 놓고 그 위에 원형 기둥을 세워 이층 건물을 지었다. 건물 안에는 방 한 칸을 들였다. 정자 왼쪽에 있는 관선재(觀仙齋)라는 사당은 후손들이 세운 것이다.","a":"퇴수정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661833.jpg"},{"q":"숙종 46년(1720) 평안도 화장사에서 간행한 1책의 목판본으로 본문인 ○○○은 불·보살상 조성에 따른 제반 의식과 절차에 관한 내용을 모아 체계화하였으며, 권2에 해당하는 제불보살복장단의식(諸佛菩薩腹臟壇儀式)은 불상의 방위와 안치하는 방법 등을 설명하고 있다. 지금까지 알려진 ○○○ 중 비교적 이른 시기의 알려지지 않은 간본(刊本)으로, 각 사찰에서 통일성 없이 불상을 조성하고 불단에 모시던 절차를 일정한 법칙으로 고착시키고 있는 점으로 보아 불교사 연구에 좋은 자료이다.","a":"내원정사 조상경","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636680.jpg"},{"q":"- 지정현황 : 전라남도 기념물 제231호(2005년 1월 27일 지정) - 명 칭 : 완도 ○○○○○ - 소 재 지 : 완도군 고금면 가교리 산 34-1 일원 - 내 용 : ○○○는 청동기를 대표하는 무덤 유적이다. ○○○○○은 도서지방의 최대 밀집지이다. ○○○ 일대 지젓묘에서 마제석검과 칼돌·대패날 등이 수습된 것으로 보아 내륙 지역과의 활발한 문화교류가 있었음을 알 수 있다. ○○○○○은 청동기시대 도서지역의 매장문화를 이해하는데 중요한 자료로 학술적 가치가 크다.","a":"완도고금도지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102217332200.jpg"},{"q":"부도란 승려의 시신을 화장한 후 그 유골이나 사리를 모셔두는 곳으로, 승려의 무덤을 상징한다. 구사리 마을에 자리하고 있는 이 부도는 원래 감안사의 옛 터에 있었으나, 건물이 들어서면서 1987년 이곳으로 옮겨졌다. 부도는 3단의 받침돌로 이루어진 기단(基壇) 위에 탑신(塔身)을 올린 모습이며, 각 부분이 8각을 이루고 있다. 기단은 아래받침돌의 옆면에 안상(眼象)을 얕게 새기고, 윗면에는 윗돌을 괴기위한 두터운 괴임을 두어 구름과 용 무늬를 새겨 놓았다.","a":"거창 감악사지 승탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642246.jpg"},{"q":"원래 옥구군 선연리의 동산에 있었으나, 일제시대 후기 군용비행장 안으로 편입되자 이를 상평마을로 옮기고 경현재라 하였다가 1967년 다시 지은 것이 오늘에 이르고 있다. 최치원이 당나라에서 돌아왔을 때 세상의 인심이 어지럽고 어수선하자, ○○○에 올라 책을 읽으며 근심과 걱정을 달랬다고 한다. 건물은 앞면 3칸·옆면 1칸 규모의 2층 누각이고, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 여러 가지 색으로 된 무늬를 곱게 칠해 놓았다.","a":"자천대","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661744.jpg"},{"q":"조선태조(朝鮮太祖)가 왕이 되던 해 서기 1392년에 각도의 안찰사(按察使)에게 교육을 개혁(改革)하라는 명을 내린 것을 계기로 ○○○○는 옛날 서석산(瑞石山) 현 무등산 서쪽 장원봉(壯元峰)아래에 세워졌으나, 호랑이가 자주 나타나서 성(城)의 동문(東門)안으로 옮겨 지었다. 그러나 성종(成宗)19년 서기 1488년 현감(縣監) 권수평(權守平)이 이 곳 또한 지대가 낮고 수해가 자주 일어나서 지금의 이 자리에 옮겨지었다.","a":"광주향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637145.jpg"},{"q":"인천 이씨 중시조인 이허겸의 묘 앞에 세운 건물이다. 중시조란 이름이 별로 없던 성(姓)씨를 가진 집안을 일으켜 세운 선조를 말한다. 『고려사』에 보면 그의 선조는 신라 때부터 지금의 인천인 소성현에 살았는데, 신라 사신으로 중국 당나라에 갔다가 천자로부터 성(姓)을 받았다고 한다. 그러나 인천 이씨가 고려시대 귀족대열에 낄 수 있게 된 것은 이허겸 때부터로, 그의 손녀 3명이 모두 현종의 비(妃)가 되었다. 첫째 손녀는 원성황후로 덕종과 정종 두 왕을, 둘째 손녀는 문종을 낳았다. 그 뒤 문종에서 인종에 이르기까지 7대에 걸쳐 귀족정치의 막강한 파벌을 이루었다.","a":"원인재","c":"문화유산자료","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659527.jpg"},{"q":"팔공산에 자리잡은 수릉(조선 헌종의 부친인 익종의 능)과 향탄(왕실에서 사용하는 목탄)의 보호를 위해 산의 출입을 금지하고 있는 일종의 푯말이다. 자연바위를 그대로 사용하였는데, 앞에서 볼 때 삼각형 모양이고 윗면은 튀어나와 있다. 표석에는 ‘○○○○○’라는 글자를 세로로 두 줄 새겼는데, 마지막 ‘계’자는 두 줄사이에 적어 놓았다. 근처에 있는 ‘수릉향탄금○○○’과 같은 의미로, 글자의 크기나 규격이 비슷하여 동일한 시대에 제작된 것으로 보이는데, 이는 또한 이 일대가 보호림으로 지정되었었음을 말해주는 것이다.","a":"수릉봉산계표석","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659494.jpg"},{"q":"○○○은 조선 세조 3년 김자수가 벼슬을 그만두고 낙향하여 대자암터에 세운 정자이다. 순조 8년(1808) 연재·초정 두 사람이 고쳐 지었으나 철종 2년(1851)에 홍수 피해로 고재준·고광조 등이 다시 고쳐 지었으며, 철종 9년(1858)에 서까래와 보를 수리하여 오늘에 이르고 있다. 정자는 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 올렸다.","a":"상월정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661911.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워놓은 비를 말한다. 이 비는 조선 중기의 문신인 이귀(1557∼1633) 선생을 기리고 있다. 이귀는 이이·성혼의 가르침을 받았으며, 임진왜란 때에는 군인을 모집하여 나라를 구하는데 힘썼다. 광해군을 몰아내고 인조를 왕위에 오르게 하는 인조반정때 공을 세워 일등공신이 되었으며, 그후 ○○○○○에 봉해졌다. 비는 거북받침돌 위에 한돌로 이루어진 비몸과 머릿돌을 세웠다. 거북받침돌은 머리를 수평으로 내밀고 있으며, 머릿돌에는 두 마리의 용과 구름을 사실적이고 생동감 있게 나타내었다.","a":"연평부원군신도비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639147.jpg"},{"q":"<○○○○○>은 고종 21년 11월 18일 조선과 독일 사이에 수교된 전문 13조의 ○○○○문으로 조덕수호○○○○, 부속통상장정, 세칙, 세칙장정, 선후속약의 한문 필사본 1책 32장, 영문 필사본 1책 45장, 독어 필사본 1책 45장으로 이루어져 있다. 이 책은 고종 21년(1884년) 8월 17일 창덕궁에서 조선과 ○○○ 즉 독일 사이에 이루어진 수교내용을 담은 문서로, 양국간에 우호적인 입장에서 서로 왕래하며 통상하자는 것이다.","a":"대조선국ㆍ대덕국 통상조약(한문, 영문, 독문)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587966.jpg"},{"q":"임진왜란 때 의병장으로 활약한 조헌(趙憲, 1544~1592)의 충절을 기리기 위해 세운 비이다. 경기도 김포 출생으로 본관은 배천(白川)이고 호는 중봉(重峯)이다. 1592년에 임진왜란이 일어나자 충북 옥천에서 의병을 일으켜 청주성 수복에 공을 세웠으나 금산전투에서 휘하의 의병 700명과 함께 전사하였다. 1604년(선조 37) 선무원종공신(宣武原從功臣) 1등에 봉해지고 1734년(영조 10) 영의정에 추증되었으며 1883년(고종 20) 문묘(文廟)에 배향되었다.","a":"조헌선생유허추모비","c":"시도유형문화유산","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637493.jpg"},{"q":"○○○는 높은 산봉우리에 봉화를 올릴 수 있게 설비해 놓은 곳이다. 봉수는 과거 횃불[烽]과 연기[燧]로 적의 침입을 중앙에 알리던 군사 통신 수단이었다. 천왕점 ○○○는 해안과 내륙을 한눈에 내려다 볼 수 있는 천왕산 주능선 끝부분(해발 353m)에 있다. 조선 시대의 봉수 노선은 전국의 봉수망을 연결하는 근본 노선인 직봉(直烽)을 중심으로 연결되었는데 직봉 사이에는 중간의 신호가 전달되지 못할 것을 우려하여 직봉으로 전달되는 작은 갈래인 간봉(間烽)이라는 보조 노선을 두었다.","a":"고성 곡산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657016.jpg"},{"q":"○○○는 신라시대부터 있던 절이지만 절 이름은 알 수 없고, 다만 숙종 29년(1703) 산성 수축 후 개방수호의 의미로 ○○○라 칭하고 사우(寺宇)를 크게 중건하였다. 주로 승당(僧堂)이나 선당(禪堂) 등 승려의 거처가 많이 건립되었으며, 전체가 거의 100간 규모였다. 금○○○○○은 이러한 배경 아래서 승병의 통솔 및 관할을 위하여 제작된 것으로 보인다. ≪경국대전≫ <예전 용인조(用印條)>에 의하면 모든 관리는 질품에 따라 크기가 다른 인식을 사용하였는데, 참상관 이상의 품관은 정방형 인장, 차하관이나 토관(土官)은 장방형으로 되어 있다.","a":"국청사금정산성승장인","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659396.jpg"},{"q":"○○○ 대웅전 앞에 서있는 탑으로, 2층 기단(基壇) 위에 4층의 탑신(塔身)을 올린 모습이다. 기단은 아래·위층이 거의 비슷한 높이인데 보통 아래층 기단이 낮고 위층 기단이 높은 일반적인 탑들과는 형태를 달리하고 있다. 탑신의 1층 몸돌은 면마다 불상을 조각하였다. 지붕돌은 몸돌에 비해 큰 편으로 네 귀퉁이가 위로 들려 있다. 꼭대기에는 머리장식의 일부가 놓여 있다. 통일신라 헌안왕 3년(859) 부처님의 진신사리를 모시기 위해 도선국사가 세운 탑이다. 기단에 비해 탑신이 가늘어 가냘픈 감을 주며, 탑신의 몸돌에 비해 지붕돌이 커서 불안정해 보인다.","a":"청암사다층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662631.jpg"},{"q":"선돌은 고인돌과 함께 청동기 시대 거석문화의 일종으로 자연석이나 자연석을 일부 다듬어 세워놓고 신앙의 대상으로 삼은 것이다. 선돌은 다양한 기능과 의미를 가지고 있다. 고인돌과 함께 세워진 선돌은 무덤 공간임을 알리려는 묘표석(墓表石)으로서의 기능을 하며, 마을 입구에 세워진 선돌은 벽사 또는 수구막이 역할을 하는 마을 수호의 기능을 가지고 있다. 또한 논밭이나 이를 내려다보이는 얕은 구릉에 세운 선돌은 풍요를 기원하는 의미를 가지고 있다. 이외에도 경계와 이정표의 기능도 가지고 있다.","a":"양주옥정리선돌","c":"문화유산자료","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660140.jpg"},{"q":"○○○는 신라 헌강왕 때 도선(道詵)이 창건한 고찰로 조선시대에는 대표적인 불서 간행 사찰이었다. 근세에는 해안, 만응 대종사들이 주석하면서 한벽선원, 승암강원 등을 개설하여 이 지역 불교계의 학풍을 크게 진작시켰다. 이곳에 소장되어 있는 《묘법연화경》 등 3권의 불서는 부처가 세상에 나타난 근본의 뜻을 밝힌 경전으로, 1443년에 효령대군 등 많은 왕실의 종친들이 세종대왕의 장수와 태종대왕의 극락왕생을 빌기 위하여 간행하였다. 현존하는 판본이 매우 드물어 자료적 가치가 크다.","a":"승암사소장불서","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639793.jpg"},{"q":"내후사동이라는 마을 이름이 말해주듯 옛 절터에 서 있는 탑으로, 2층 기단(基壇)에 3층의 탑신(塔身)을 올린 모습이다. 위층기단과 탑신의 몸돌에는 기둥모양이 조각되어 있다. 지붕돌은 밑면의 받침이 4단씩이며, 네 귀퉁이가 살짝 들려 있다. 꼭대기에는 동그란 보주(寶珠:꽃봉오리모양의 장식)가 남아 머리장식을 하고 있다. 전체적으로 기단부에 비해 탑신부가 왜소해 보이고, 탑신의 2층 몸돌이 1층 몸돌에 비해 급격히 줄어 들어 균형미를 잃었다. 통일신라의 일반적인 석탑양식을 따르고 있으나, 양식상의 변화를 보이고 있어 고려시대에 세웠을 것으로 보인다.","a":"운산리삼층석탑","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639374.jpg"},{"q":"법화사는 12세기∼15세기에 제주도에서 번창했던 절이다. 18세기 전기에 제주목사 이형상이 제주도의 절 3곳을 불태워 없앨때 완전히 불타버렸으며, 지금의 건물들은 1987년 다시 세운 것이다. 현재의 법당 자리에서 금당지로 보이는 건물터가 발견되었는데, 앞면 5칸·옆면 4칸에 면적이 약 100평인 대규모 건물이었음을 알 수 있다. 법화사는 건물 기단의 바닥돌이 2단으로 되어있고, 면석의 기법이 특이하며, 출토된 도자기와 기와조각 등으로 보아 10세기∼12세기 경 지어진 것으로 추측된다. 당시 규모가 매우 큰 절로 제주도 3대 사찰 중 하나인 중요한 유적이다.","a":"법화사지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657761.jpg"},{"q":"조선 순종의 장인 ○○○○○이 지은 집이다. 지금 있는 건물은 동대문구 ○○○에 있던 것을 1996년 남산골 공원을 만들면서 이곳으로 옮긴 것이다. 집 뒤에 있는 사당은 4·19 때 소실된 건물을 복원한 것이다. 본채, 행랑채, 사당 등으로 구성되어 있으며 평면은 우리나라에서 보기 드문 형식이다. 평면을 으뜸 원(元)자 모양으로 꾸민 이 집은 제일 위에 사당을 배치하고 본채를 두었으며 본채 앞에는 대문을 두고 그 옆에 행랑채를 두었다. 본채는 부엌·안방·대청·건넌방·누마루 등을 배치하였고 사당은 1칸 집으로 본채보다 두 단 높여 지었다.","a":"제기동해풍부원군윤택영재실","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658067.jpg"},{"q":"이 향약은 전래된 각종 향약의 집대성이며 ○○ 남부 지방의 특수성을 고려하여 현장성있는 향약으로 제정한 일명 남촌 사면 향약(南村四面鄕約)이라고도 부른다. 사면은 ○○ 남쪽 지방의 청남(靑南),청동(靑東),공서(功西),공동(功東)으로 현재의 청리,공성,외남 일부가 이에 속하다. 처음 이 향약은, 1634년 ○○ 목사 김상필(金商苾)이 월간(月澗) 이전(李)과 수암(修巖) 유진(柳袗)의 두 선생에게 약정을 맡아보게 하여 시행하였던 것이다.","a":"상주 증손향약","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640721.jpg"},{"q":"○○○은 누가 언제 세웠는지 알 수 없다. 조선 숙종 20년(1694)에 쓴 『○○○중수기』에 따르면 보조국사가 세운 뒤 정유재란으로 불탄 것을 선조 40년(1607)에 승려 신찬이 고쳐 지었고, 효종 1년(1650) 스님들이 힘을 모아 다시 지었다고 한다. ○○○이라고도 하는 이 암자는 1983년 주지 성묵스님이 현 법당을 복원하였다. 법당은 앞면 5칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 부리 모양으로 장식한 익공 양식으로 꾸몄다.","a":"보리암","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661925.jpg"},{"q":"향교는 성현의 위패를 모시고 제사지내며, 지방 백성들의 교육을 담당하기 위해 국가에서 세운 교육기관으로 조선시대에는 국가로부터 토지·노비·책 등을 지급받아 학생들을 가르쳤다. ○○○○가 처음 세워진 연대는 알 수 없으나 15세기 중반에 수리하였다고 전한다. 지금 남아있는 주요 건물은 조선 후기에 지은 것으로 보이며, 1976년에 대성전·명륜당·삼문 등을 고쳤다. 현재 대성전·동무·서무·명륜당·동재·서재 등이 남아있다.","a":"인천향교","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636988.jpg"},{"q":"○○○란 어떤 건물이 있던 터에 세워두는 비로, 그 건물에 얽힌 사연을 담고 있다. 조선 광해군 때의 왕실종친이었던 구천군 이수는 기울어가는 나라의 종묘사직을 구하고자 당시 권력을 휘두르던 이이첨을 탄핵하였다가 이곳 순천지역으로 유배되었다. 손수 정자를 지어 ‘○○○’이라 이름짓고 항상 북쪽(서울)을 바라보며 나라와 임금의 안위를 걱정하였다.","a":"순천망북정유지비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661902.jpg"},{"q":"경상남도 ○○군 위천면 상천리 강남사 절터에 있는 ○○○○○으로 부처의 몸에서 나오는 빛을 형상화한 광배(光背)를 가지고 있다. 얼굴은 마모가 심하며, 목에는 3줄의 주름인 삼도(三道)가 뚜렷하게 표현되었다. 양 어깨를 감싸고 입은 옷을 입고 있는 것 같으나 전체적으로 마모가 심해 형체를 알아볼 수가 없다.","a":"거창 강남사지 석조여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642244.jpg"},{"q":"조선 숙종 40년(1714)에 이덕관이 사랑채인 마호당을 짓기 시작하여, 숙종 44년(1718)에 안채, 중사랑채, 사당, 솟을대문 등을 완공하였다. 13대를 이어온 종가였으나, 중사랑채와 사당은 허물어져 없어지고 사랑채 대문만 남아 1865년 현 소유자의 증조부가 사랑채를 다시 짓고, 1937년에 안채를 고쳐 지었다. 1961년과 1989년에 사랑채와 대문을 고쳐 지어 오늘에 이르고 있다. 대부분의 가옥이 옆면 2칸 규모인데, 안채는 앞면 5칸·옆면 3칸 규모인 것이 특징이다.","a":"진주 마진리 이씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664067.jpg"},{"q":"조선 중기 성리학의 대가인 우계(牛溪) 성혼(成渾, 1535∼1598) 선생의 묘이다. 휴암 백인걸의 문하에서 학문을 배우고 율곡 이이(李珥)와 사귀면서 평생의 친구가 되었다. 묘역은 부인과 합장한 하나의 봉분 형태이다. 묘제(墓制)는 비교적 원형을 유지하고 있으며, 석물은 새것과 섞여 있다. 봉분의 정면 오른쪽에는 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)를 세웠다. 1649년(인조 27)에 건립한 것이고, 비문은 김집이 짓고 외손자인 윤순거가 글씨를 썼다.","a":"성혼선생묘","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646125.jpg"},{"q":"전체 높이 3.31m, 불상 높이 1.93m로, 원적산 산비탈의 북동쪽을 향하여 팔각대좌 위에 가부좌를 틀고 앉아 있는 ○○○○이다. 전체적으로 큰 손상 없이 비교적 양호한 보존 상태를 보여주고 있으나 광배(光背; 붓다의 몸에서 나오는 성스러운 빛을 형상화한 것)는 남아 있지 않다. 전체적으로 통일신라 말기의 조각양식을 잇고 있다. 큰 신체 표현과 특히 높고 큰 무릎, 대좌의 형식 등에서 부근에 있는 여주 포초골 미륵좌불과 매우 유사한 양식을 보이고 있어, 고려 시대 전반에 여주에서 유행한 불상 양식을 전하고 있다.","a":"여주도곡리석불좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637686.jpg"},{"q":"연미사 뒷쪽으로 난 길을 따라 오르면 이 탑이 보인다. 함께 있는 거대한 석불상(보물 제115호) 뒷편에 흩어 있던 것을 복원해 놓은 것으로, 예전에는 이곳이 연미사의 자리였다고 한다. 탑은 전체의 무게를 받치는 기단(基壇)을 1층으로 두고, 그 위로 3층의 탑신(塔身)을 올렸다. 기단과 탑신의 몸돌은 아무런 꾸밈이 없는 단조로운 모습이며, 지붕돌은 밑면에 4단씩의 받침을 두었고 네 귀퉁이에서 살짝 솟아올라 가벼움을 이끌어내었다. 주위의 자연과 아름다운 조화를 이루고 있는 탑으로, 석불상과 같은 시기인 고려시대의 작품으로 추정된다.","a":"안동이천동삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640428.jpg"},{"q":"이 지역의 옛 관아건물 정면의 양 옆에 자리하고 있는 비의 받침부분으로, 2기 모두 비몸과 머릿돌은 남아 있지 않다. 대부분의 비받침이 거북의 형상인 것에 비해 이 받침돌은 머리모양이 해태의 모습에 가깝다. 머리는 하늘을 향하고 있고 눈은 부릅뜨고 있으며 입에는 보주를 물고 힘있게 치켜든 형상을 하고 있다. 등에는 U자형을 3겹으로 조각하였다. 반대편에 있는 비받침의 거북머리는 움츠린 형태를 하고 있는데, 형식화된 느낌이다. 몸을 비교적 납작하게 만들었고 등에는 육각형 무늬를 뚜렷하게 조각하였다.","a":"읍내리귀부석","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020031916303700.jpg"},{"q":"성균관 대사성(成均館 大司成) 이정보(李鼎輔,1693년～1766년)가 태학속전(太學續典)이 완성된 것을 기념하여 9명의 참여 유생(儒生)들과 함께 만든 계첩(稧帖)이다. 능화문(菱花文) 장지로 된 표지에 묵서(墨書)로 ‘○○○○’이라는 표제가 적혀 있고 제 1면에 참여자 명단인 좌목(座目), 제 2면에 성균관의 평면도인 반궁도(泮宮圖), 제 3면과 제 4면에 진사 신석규(辛錫奎)와 박익령(朴益齡)이 쓴 발문(跋文)이 각각 수록되어 있다. 신석규의 발문에 의해 이 화첩이 영조 23년(1747년)에 제작되었음을 알 수 있다.","a":"태학계첩","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590377.jpg"},{"q":"이 건물은 慶州金氏 版圖判書 金將有의 4세손 平澤縣監 金滸의 재실로 ○○군 회남면에서 청원군 문의면 경계지점으로 이 마을 입구에 뒷산(259m)을 배산으로 남향하여 위치하고 있다. 중수기와 족보기록 등에 의하면 17세기전후 건립된 건물로 2009년 건물 보수 시 ‘康熙 三十二年 癸酉 三月 造作 瓦匠 金然麟 吳先伊 金貴範 金海信’라는 명문이 새겨진 기와가 발견되어 1694년 전후에 건립되었을 것으로 추정된다. 고종 26년(1889)에 후손 寅泰가 쓴 齋舍重修記가 편액 되어 있다.","a":"보은 고현재","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020033117114502.jpg"},{"q":"○○○○○는 평탄 대지상의 밭 한가운데에 위치하고 있음. ○○○ 주변에는 무문토기편과 석기가 발견되고 있다. 상석은 길이 205cm, 폭은 162cm, 두께 35~75cm로 상면이 다소 평평한 타원형임, 장축방향은 남서쪽으로 5도 정도 깅루어져 있음. ○○○는 남서쪽에 길이 72cm,폭 26cm, 두께 15cm인 대형판석상 지석이 남서쪽 모서리에 원상에서 벗어나 기울어지게 고여 있는데 상석무게를 못이겨 내려않은 것으로 추정됨. 따라서 상석의 남서쪽이 크게 들리어지게 축조한 것으로 판단됨.","a":"일과리지석묘","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657738.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생을 기리고 있다. ○○○은 중종 38년(1543) 진사가 되고, 명종 1년(1546)에 병과로 급제하여 한림이 된 후, 여러 관직을 거쳐 우의정과 영중추부사를 지냈다. 강홍립 장군의 할아버지이기도 한 그는 정파싸움에 휩쓸리지 않는 초연한 태도를 취하였고, 특히 외교활동에 커다란 공을 세웠다. 생을 마친 후 아들이 호성공신이 되자 영의정에 추증되기도 하였다. 비는 높직한 사각받침돌 위로 비몸을 세우고, 지붕돌을 올린 모습이다.","a":"정정공 강사상 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636287.jpg"},{"q":"백운암 고시완(1783∼1841) 선생이 가난한 집의 자제들을 모아 가르치던 서당으로 지금은 선생의 제사를 모시고 있다. 선생은 실학연구에 몰두하여 하늘과 인간의 관계를 탐구하고 이(理)와 기(氣)의 흐름을 밝히기 위해 노력하였으며 평생 학문과 교육에 전념하여 고금(古今)의 경전에 대해 막힘이 없었다.","a":"통영 백운서재","c":"문화유산자료","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663794.jpg"},{"q":"화면을 상하로 이분한 뒤 상단에 향우측으로부터 화영당, 인한당, 해경당을, 하단에 향우측으로부터 세염당, 나월당, 효월당, 송곡당을 순서대로 그리고 인물의 오른쪽 어깨위로 각각의 화제명호란을 만든 후 기입하였다. 스님들은 모두 좌안7분면에 결가부좌를 하고 있으며 손에는 염주 또는 주장자를 쥐고 있는 모습이다. 잿빛장삼에 홍가사를 걸치고 있으며 녹색, 군청색, 황토색의 매듭으로 가사를 수하고 있다. 짙은 잿빛과 옅은 잿빛 장삼을 교대로 배치하고 지물들도 변화를 주어 단조로움을 피하고 있다.","a":"남해 용문사 칠화상 진영","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001666210.jpg"},{"q":"○○○는 고려 말기의 무신으로 본관은 ○○이다. 고려 말 왜구와 홍건적의 침입을 물리치는 데 큰 공을 세웠으며, 문하시중(門下侍中)을 비롯한 여러 관직을 두루 지내고 창성부원군에 봉해졌다. 1388년(우왕 14) 요동정벌군의 좌군(左軍) 도통사(都統使)로 출정하였다가 이성계와 함께 위화도에서 회군함으로써 우왕을 폐하고 창왕을 세우는 데 중요한 구실을 하였다. 그러나 1389년 이성계 일파의 세력에 밀려 ○○으로 유배되었고, 1390년에 ○○에서 생을 마감하였다. 묘역은 봉분 1기, 화관석(花冠石) 묘표 1기, 문인석 1쌍으로 구성되어 있다.","a":"창녕 조민수 묘","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657601.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. 이 가마터는 ○○○ 후원 남쪽에 있으며, 정확히는 알 수 없으나 조선시대 ○○○의 낡은 건물이나 부서진 건물을 수리할 때, 기와나 벽돌을 직접 만들어 사용하였던 곳으로 추정된다. 보통 기와 가마가 짧고 둥근데 비해 이곳의 기와 가마는 아궁이 52㎝, 중간높이 219㎝, 길이 139㎝의 비교적 큰 규모를 보이고 있다. 가마는 부엌과 아궁이, 가마몸통 3부분으로 나누어진다. 사찰에서 쓰이는 기와를 제작하던 가마는 남아있는 예가 드물기 때문에, 당시의 가마운영과 제작기술을 이해할 수 있는 중요한 유적이다.","a":"송광사흑토기와.전도요지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654061.jpg"},{"q":"‘○○○ 오○○○’은 최근 창건된 ○○○ 관음전 앞에 건립되어 있다. 석탑은 1998년 ○○○ 신도가 기증한 것으로 처음 세워진 사찰 및 장소에 대해서는 알려져 있지 않다. 고려 초에 제작된 석탑으로, 전체 높이는 315㎝이다. 단층기단 위에 5층의 탑신부를 구성하였다. 기단은 새롭게 제작된 2매의 석재로 구성한 지대석 위에, 4매의 판석으로 결구하고 갑석을 올렸다. 면석에는 우주(隅柱)를 표현하지 않았다. 갑석 상면은 경사를 주어 물매를 표현했고, 중앙에 3단의 각호각형 탑신받침을 마련했다.","a":"우리절 5층석탑","c":"문화유산자료","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660297.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 광주 용두리 고인돌군은 남북 방향으로 3줄이 배치되어 있는데 현재 온전한 형태로 남아있는 것은 10기이며, 주위에 덮개돌을 지탱하는 받침돌이 여러 개 흩어져 있는 것으로 보아 2∼3기 정도 더 있었을 것으로 생각된다.","a":"용두동지석묘","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659598.jpg"},{"q":"임진왜란 때 순절한 다대첨사 윤흥신 장군의 충절을 기리고자 높이 마련한 단으로, 단 중앙에는 비를 세워 두어 장군의 전적을 기록하고 있다. 윤흥신은 선조 25년(1592) 부산에 상륙한 왜적이 부산진성을 함락시킨 후, 다대진을 공격하자 동생 흥제와 군관민을 이끌고 이들과 대치하다 전사하였다. 왜란이 끝난 후에도 이 일이 알려지지 않다가, 영조 37년(1761) 경사감사로 있던 조엄이 이 사연에 얽힌 자료를 찾아내어 조정에 올리니, 비로소 그의 충절이 드러나게 되었다.","a":"윤공단","c":"시도기념물","nc":"","r":"부산광역시","s":"사하구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644951.jpg"},{"q":"충청남도 홍성군 홍북면 신경리 ○○○ 입구의 서쪽에 서 있는 바위에 돋을새김한 불상이다. 바위를 불상 모양보다 크게 파내고 조각하였는데 마멸이 심하다. 머리 부분은 뚜렷하게 돌출 되었으나 아래로 내려갈수록 안정되어 있다. 민머리 위에는 상투 모양의 머리묶음이 큼직하게 솟아 있고, 얼굴은 타원형으로 양감있게 표현하였다. 눈과 입은 얼굴에 비해 가늘지만 흐뭇한 미소가 번져 있어 8세기 신라 불상의 이상적인 얼굴 특징이 많이 남아 있다. 귀는 거의 어깨에 닿을 만큼 길게 내려와 있으며, 목에는 3줄의 삼도(三道)가 있다.","a":"용봉사마애불","c":"시도유형문화유산","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639205.jpg"},{"q":"석조관음보살의상은 금왕읍 무극리 탑골사지라는 옛 절터에 세워진 ○○○에 봉안되어 있는 불상으로, 대략 고려말에서 조선 초기에 조성되었을 것으로 추정된다. l매의 화강석을 다듬어 주형형태로 만들고 불상과 광배를 정교하게 조각되어 있다. 대략 등신대로 보이며, 현존 상태가 양호한 편이다. 불상의 얼굴은 장방형에 가까우며, 머리에는 삼산형 보관을 쓰고 있으며, 보관 밑으로 소발의 형태인 머리가 나와 있다. 눈은 음각선으로 표현하여 감은 듯하다. 목에는 삼도의 흔적이 있고 법의는 우견편단이며 옷주름을 5겹의 양각선으로 나타내고 있다.","a":"음성 보현암 석조관음보살의좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638920.jpg"},{"q":"○○○○○은 1657년(효종 8)에 명현당(明玄堂) 원학대사(元學大師)가 이웃에 있던 신흥사(新興寺)를 옮겨 지은 것으로 사적비에 기록되어 있다. 그리고 처마 끝에 장식된 암막새기와에‘옹정경술(雍正庚戊)’이라는 양각글씨가 있어 1730년(영조6년)에 한차례 중수를 하였던 것으로 추정된다. 건축양식으로 보아서도 조선중기에 건립된 것으로 보이는데 정면3칸, 측면3칸의 팔작지붕 건물로 다포식이다. 자연석으로 높게 쌓은 기단 위에 자연석의 주초석을 사용하였는데 우주(隅柱)가 평주(平柱)보다 훨씬 굵고 높다.","a":"청주 월리사 대웅전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638474.jpg"},{"q":"고조부 안영제가 1906년(광무 10, 병오)에 건립한 근대한옥으로, 입산마을에 세거하는 ○○○○의 종가로 안채의 대청 종도리 받침장여 밑면에 “大韓光武十年丙午....”라고 쓴 상량 묵서가 있어 1906년에 지은 것임을 알 수 있다. 전통적인 건축형식에 근대의 합리성과 효율성을 반영한 건물로 사용한 부재가 견실하고, 치목수법이 우수하여 일제강점 이전시기의 경남지방 부농층의 정침 모습을 잘 보여주는 자료이다.","a":"의령 탐진안씨 종택","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666372.jpg"},{"q":"조선시대 불교조각사 연구에 중요한 학술적 자료로서, 조선시대 후기에 일반적으로 보이는 석종형 부도와 석비로 석비의 비문내용이 뚜렷하여 조선 후기 경남지역의 석조물과 금석문 연구에 대한 학술적 가치가 있다. 동체부의 뒤쪽 한면이 일부 훼손되었으나, 석비 등 나머지 내용은 양호한 상태이다. 석비의 내용에는 ○○○에 진영을 모셔 놓았다는 기록이 있다.","a":"산청 심적사 한암대사 승탑 및 탑비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642384.jpg"},{"q":"조선 영조(재위 1724∼1776) 때 유학자인 ○○○의 충·효 정신을 기리기 위해 칠원현감을 비롯한 유학자들의 글을 모은 ○○○이다. ○○○은 부모님이 돌아가시자 무덤가에 움막을 지어 보살피기를 3년 동안 하고, 산에 들어가 단을 쌓고 임금님(영조)이 오래 사시기를 16년 동안 빌었다고 한다.","a":"함안 배상엽 관련 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664628.jpg"},{"q":"화강암으로 된 높이 2.1m의 미륵불로서 간송미술관에 전시되어 있다. 머리에는 큰 상투 모양의 머리묶음이 있고 옷에는 주름이 사선으로 표현되어 있다. 두 손은 가슴에 올려 모으고 있으며, 몸은 긴 돌기둥 모양으로 되어 굴곡이 없는 편이다. 부처님의 마음이 과장없이 표현되었고 조각수법이 예스러운 점이 있어 토속적인 경향을 보이고 있는 이 불상은 조각수법으로 보아 고려 중기 이후의 작품으로 추정된다.","a":"석불입상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636112.jpg"},{"q":"○○○ 고인돌은 1972년에 1기가 알려져 경기도 기념물로 지정되었으나 그 이후에 자세한 보고는 없다가 1990년대 초에 『○○도 고인돌무덤(지석묘)조사연구』를 통해 이 고인돌이 있는 ○○○ 산125번지 일대를 자세하게 조사하여 잡목과 잡초가 우거진 사이에서 10기에 가까운 고인돌을 더 찾아냈다. 이 지역의 고인돌은 덮개돌은 부분적으로 손질한 흔적이 있고, 평면 형태는 모두 판돌형(板石形)이다. 덮개돌의 크기는 기념물로 지정된 내가 고인돌이 길이 335㎝로 가장 크고 나머지는 길이가 130∼260㎝로 다양한 편이다.","a":"강화 오상리 고인돌군","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645666.jpg"},{"q":"제주도 섬이라는 자연적 한계, 곧 거센 파도와 싸우며 살아야하는 특수성 때문에 신에게 의존하는 바가 컸다. 본향당, 포제단, 처녀당, 미륵당, 해신당 등 제주도에 다양한 민간 신앙의 자취가 남아있는 것은 이와 같은 모진 삶 때문이다. 제주도에는 마을마다 마을의 토지와 그 마을 사람들의 출생, 사망 등의 일을 맡아보는 신을 모셨다. 이 신이 본향신이며 본향신을 모신 곳이 본향당이다. 특히 구좌읍 송당리에는 송당 마을의 모든 일을 관장하는 것은 물론, 제주도 본향신의 원조라고 전해지는 ○○○○○이 있다.","a":"송당본향당","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659282.jpg"},{"q":"○○○ 소장 ○○○○○은 전제 7권 1질이다. 경전의발문은 봉래산인 풍계가 지었는데 1685년(강희24년 을축)에 작성된 것으로 기록되어 있어 현재 개문산방에서 소장하고 있는 연화경은 1685년에 간행된 것으로 추정된다. 경전의 판심문이 매우 다양항고 각 면마다 시주자의 이름이 새겨진 곳이 있어서 경전을 간행할 때 시주를 받아서 간행한 것을 알 수 있어서 당시 불경간행의 과정을 이해하는데 다양한 자료를 제공하고 있어서 출판문화의 단면을 이해하는 자료로서의 가치가 높다","a":"진주 법륜사 묘법연화경","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022183200.JPG"},{"q":"<○○○○○> 유적은 ○○○ 정상부에 위치하고 있다. <○○○○○>는 인접한 ○○군에 비해 규모는 작으나 성벽 기저부가 잘 남아있으며 중랑천 서쪽에서 확인된 최초의 고구려 관방유적으로서 중랑천 동쪽에 있는 아차산, 용마산, 망우산 ○○들과 축성 기법 측면에서 연관성이 높아 고대 서울지역에서 삼국의 역사적 정황을 이해할 수 있는 중요한 유적이다.","a":"배봉산 보루","c":"시도기념물","nc":"","r":"서울특별시","s":"동대문구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017021611374000.jpg"},{"q":"○○○○는 1923년 최초 설립되었고 ○○○○○은 1929년 건축되었다. 1929년 건립된 ㄱ자형 한옥식 개신교회이다. 강대를 기준으로 남녀 신자석이 분리된 형태를 취하고 있으며 출입문도 별도로 마련되어 남녀유별의 전통이 남아 있던 초기 교회의 모습이 잘 남아 있다.","a":"두동교회구본당","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661859.jpg"},{"q":"「○○」은 ○○시 ○○동에 위치한 ○○ 충렬사(사적 제 236호) 아래의 2기의 우물을 일컫는다. 위쪽 샘을 일정(日井), 아래쪽 샘을 월정(月井)이라 불렀다고하며 이를 합쳐 「○○」이라 일컫는다. 일정의 물은 이(李) 충무공의 향사에 이용하고 월정의 물은 일반 민가에서 사용했다고 하며 , 1670년 제 51대 김 경(金鏡) 통제사 때 이 우물을 팠다고 전하여지고 있다. 처음에는 우물을 하나만 팠더니 물이 탁하고 수량이 적어 하나 더 팠더니 비로소 물이 맑고 수량(水量)도 많아졌다고 한다.","a":"통영 명정","c":"시도기념물","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657559.jpg"},{"q":"경상남도 사천시 사천읍 선인리 일대에 있는 ○○○○은 돌과 흙으로 쌓은 성곽으로, 약 1.5㎞의 둘레 중 현재는 3개 부근 약 300m의 성곽이 남아있다. 『사천군지』에 의하면 사천은 조선 태종 때 ‘동성’이라 불렀으며, 그때 진을 두고 병마사로서 별현사를 겸직시켰고 세종 때에 다시 사천현감으로 불렀다. 이 성은 세종 24년(1442)에 병조참판 신인손이 왕명에 의해 쌓았다고 전해지며, 이로부터 4년 뒤 관청을 짓고 읍을 옮겼다고 한다.","a":"사천읍성","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655826.jpg"},{"q":"태실은 왕실의 왕과, 그 자손 등의 태를 묻는 곳으로, 이 태실 앞에는 태를 모신 것을 기념하는 ○○○를 세워둔다. 이곳은 조선 19대 임금인 숙종(재위 1674∼1720)의 태를 묻었던 곳이나, 고종 2년(1869) 태와 태실은 경기도 양주로 옮겨가고 현재는 2기의 ○○○만 남아있다. 2기의 비 중 조금 작은 비는 현종 2년(1661) 태실과 함께 세운 것으로, 네모난 받침돌 위에 비몸을 얹고 머릿돌을 올린 모습이다. 머릿돌은 옆면이 2단으로 동그랗게 말려 있다.","a":"공주숙종대왕태실비","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661435.jpg"},{"q":"○○○○는 사찰 입구에 설치해 두는 것으로, 절에 행사나 의식이 있을 경우 이곳에 당이라는 깃발을 달아두는데, 이 깃발을 매달아두는 길쭉한 장대를 당간이라 하고, 이를 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 보통 당은 없고 드물게 당간이 있으나 대부분은 두 기둥만 남아있다. ○○○ 도로변의 논 한가운데에 남아 있는 이 ○○○○는 높이 마련된 돌단 위에 서 있다. 전체적으로 위에서 아래로 내려올수록 약간 굵어지고 있으며, 아랫부분은 두툼해져 투박해 보인다. 두 바깥면의 양 모서리를 부드럽게 다듬어 놓았을 뿐 각 면에는 조각을 두지 않았다.","a":"상주 복룡동 당간지주","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640246.jpg"},{"q":"조선 중기의 문신인 존양재 ○○○의 시문을 모아 간행한 문집을 새긴 6권 3책의 책판이다. ○○○은 효종 6년(1655) 과거에 합격한 뒤 성균관학유, 사헌부감찰, 예조정랑 등의 벼슬을 했고, 주로 남인 계열의 사람들과 지냈다. 기장현감으로 있을 때에는 훌륭한 치적을 남기기도 했다. 문집의 서문은 당시 영남학자의 대표자인 갈암 이현일(1627-1704)이 썼다. 이 문집은 원고를 백수십여 년간 간직해 오다가 고종 때 와서 성재 허전이 발문을 붙여서 1901년 그 후손들이 간행한 것이다.","a":"송정렴 존양재문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642042.jpg"},{"q":"현재는 밭으로 사용되는 자그마한 터에 서 있는 탑으로, 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단과 탑신부의 세 몸돌은 각 면마다 기둥모양을 가지런히 새겨 놓았다. 아래층 기단에는 독특하게도 연꽃무늬를 새겨 놓아 눈길을 끌고 있다. 각 몸돌을 덮고 있는 지붕돌은 밑면에 4단씩의 받침을 두었으며, 처마는 수평을 이루다가 양끝에서 아주 서서히 들려 있다. 꼭대기에는 머리장식을 받치던 네모난 받침만 남아있다. 대체로 통일신라의 양식을 따르면서도 연꽃무늬, 지붕돌의 모습 등에서 그 전형을 벗어나고 있어 고려시대에 세운 것으로 보인다.","a":"영천정각리삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640845.jpg"},{"q":"지촌 김방걸(1623∼1695) 선생의 형인 김방형 선생이 살던 집이다. 현종 4년(1663)에 처음 지었고 수산재라고도 부르는데, 여러 차례의 수리를 거쳐 현재는 안채와 사당 그리고 외양간이 남아 있다. 안채는 전체적으로 ㅁ자형을 이루면서 앞면 왼쪽으로 사랑채가 돌출되어 있다. 안채는 대청을 중심으로 좌우에 안방과 창고방이 마련되어 있으며, 사랑채는 왼쪽에 모방과 마루방, 오른쪽에 온돌방·사랑마루·책방을 배치하였다. 이 지방의 일반적인 주택형태를 보이면서 안채의 고방이나 사랑채의 모방 구성에 독특한 면을 보여주고 있다.","a":"지예동양동댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658691.jpg"},{"q":"○○○의 ○○는 명성에 비해 그 크기와 형태가 뛰어나지 않으며 비석이 사암으로 이루어져 보존상태가 양호하지 않으나 남명이 찬술한 묘갈명이 있어 사료적으로 그 가치가 높아 문화유산자료로 지정하여 관리하고자 함","a":"하동 대곡리 조지서 묘비","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666484.jpg"},{"q":"옥천 조씨 상호정파의 종가집이다. 조선 철종 6년(1855)에 조병익이 세운 건물로 크게 사랑채, 안채, 행랑채, 별채로 구성되어 있다. 대문이 있는 행랑채를 지나 행랑마당과 나란히 사랑채가 있으며 뒤쪽 중문을 지나면 안채가 있다. 별채는 안채 옆으로 있다. 앞면 5칸·옆면 1칸 크기의 행랑채는 가운데 대문을 두고 2칸은 청지기방, 나머지 2칸은 마구간으로 쓰고 있다. 안채는 앞면 6칸 크기로 지붕은 옆면에서 볼 때 지붕선이 여덟 팔(八)자 모양과 비슷한 팔작지붕을 얹었다. 사랑채는 앞면 4칸·옆면 2칸 건물로 지붕은 안채와 같은 팔작지붕으로 꾸몄다.","a":"승주조순탁가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658397.jpg"},{"q":"매죽헌 성삼문을 모시기 위해 세운 사당이다. 성삼문은 조선 전기의 문신으로 사육신의 한사람이다. 충청남도 홍성 출신으로 세종 20년(1438)에 과거에 급제하였으며 집현전 학사로 뽑혀 세종의 지극한 총애를 받았다. 그는 명나라에 가서 음운과 교장(敎場)의 제도를 연구해와서 1446년 10월 9일에 역사적인 훈민정음을 반포하는데 크게 공헌하였다. 또한 박팽년, 허조등과 단종복위 운동을 계획하였으나 실패하고, 세조에게 모진 고문을 받다 능지처사를 당하였다.","a":"금남 문절사","c":"문화유산자료","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666853.jpg"},{"q":"조선 시대의 학자인 조욱(趙昱, 1498년-1557년)의 학문과 덕행을 기리기 위해 세운 서원이다. 서원이 언제 건립되었는지는 기록마다 차이가 있지만, 일반적으로 그의 제자들이 1654년에 세웠다고 한다. 그리고 1714년 ‘용문서원(龍門書院)’으로 사액(賜額 ;조선 시대에 임금이 사당이나 서원 등에 이름을 지어 새긴 편액(扁額)을 내리던 일)이 되었다. 이후 기록인 <○○○○지(雲溪書院誌)> 에 의하면, “1838년에 임금이 용문사(龍門寺)에 행차했다가, 용문서원이 사찰 이름과 같다고 하여 ‘○○○○’으로 이름을 바꾸게 되었다”라고 기록되어 있다.","a":"운계서원","c":"문화유산자료","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659913.jpg"},{"q":"○○○은 중종반정(中宗反正)때 정국공신(靖國功臣)인 성산군 이식(星山君 李軾)의 유업이 깃든 정자이다. 이식은 벽진인(碧珍人)으로 자(字)는 자담(子膽), 호는 동파(東坡)인데, 무과에 급제하여 사복시부정(司僕시副正), 만도첨사 등을 역임하였으나 반정이후 권신(權臣)들이 중종의 비(妃) 신씨(愼氏)를 폐출하자 정쟁(政爭)을 피해 사패지(賜牌地)인 이곳으로 내려와 주변의 절경과 풍치를 벗삼으며 유유자적하는 삶을 누렸다.","a":"밀양 곡강정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666477.jpg"},{"q":"○○○○○은 ○○○ 나한전 옆에 건립되어 있는 목조와즙 건물로 여러 번 보수가 이루어졌으나 창건 당시의 원형을 비교적 잘 유지하고 있다. 건물은 외벌대 기단을 마련하여 건립한 정면 3칸, 측면 1칸의 소규모 건물이다. 초석 위에 사각형 기둥을 올린 민도리 형식으로 창호 앞에는 디딤돌을 마련하여 문지방을 쉽게 오르내리도록 했다. 지붕은 맞배지붕이며, 정면 처마부는 겹처마이고, 후면 처마부는 홑처마로 구성되었다. 건물 양측면에는 화방벽(火防壁)이 설치되어 있다. 건물 내부는 안쪽 벽에 불단을 마련하여 칠성도와 석불좌상, 명호스님의 영정을 봉안하였다.","a":"진관사 칠성각","c":"문화유산자료","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314434100.jpg"},{"q":"‘○○○’는 유네스코 세계유산에 등재된 남한산성 내에 자리하고 있는 사찰이다. 남한산성이 만들어지던 때 같이 세워졌다. 임진왜란 때 크게 활약한 승군(僧軍 ; 전쟁과 같은 나라의 위기 때 만들어지는 승려로 구성된 군대)은 전쟁 후에도 국가의 필요에 따라 여러 일을 맡았다. 남한산성 역시 당시 북쪽에서 새롭게 힘을 키우던 후금(後金)을 대비하여 벽암 각성스님을 책임자로 하여 승군을 동원해 서울의 남쪽에 새로 쌓은 대규모 산성이다.","a":"장경사","c":"문화유산자료","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659888.jpg"},{"q":"이 영정은 ○○○ 궤붕선사의 좌안 8분면 바닥가부좌상으로, 문양 없는 벽면과 돗자리의 이단구도를 배경삼아, 돗자리위에 방석을 깔고 왼손에는 주장자를, 오른손은 무릎위에서 새끼손가락을 살짝 펼친 채 염주를 쥐고 측면을 향해 앉아 있다. 화면 향좌측에 주지묵서의 ‘부종수교○○○범붕대선사진(扶宗樹敎鷲峯堂軓鵬大禪師眞)’ 화제가 있을 뿐이다. 화면 크기는 가로 79.6cm, 세로 103.4cm이다.","a":"취봉당 궤봉 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643009.JPG"},{"q":"신라 55대 경명왕의 큰아들인 밀성대군 박안침을 모시는 재실이다. 1927년 박해철이 다른 후손들과 함께 세운 이곳은 밀성대군과 아들 박욱, 손자 박란의 비석을 세운 경덕단과 재실인 ○○○로 되어 있다. ○○○에는 박해철의 공덕을 기리기 위한 ○○○와 앙경문, 유경각, 영첩각, 경초재, 고직사 6동의 건물이 있는데 본래 재실로 건축된 것은 아니었다. 일제시대의 일반주택인 이곳을 밀성박씨 문중에서 매입하여 재실로 사용하고 있는데 고직사와 경초재, 영첩각은 후에 추가로 세워져 지금과 같은 배치를 이루고 있다.","a":"밀양 만운재","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664587.jpg"},{"q":"호명면 사고막골의 야산을 배경으로 정남향으로 자리잡고 있는 건물이다. 비탈진 대지 위에 정침이 있고, 동쪽 담장 밖에 흙담장을 쌓고 사당을 별도로 세웠다. 이곳은 소유자의 17대조인 이덕창(1569∼1616) 선생의 집으로 조선 선조 때 지은 것이다. 선생은 임진왜란 때 의병을 일으켜 내자시정이 된 학자이다. 조상의 옛 터에 집을 세우고 안채 대청에 ‘사고구려’라는 현판을 걸었다. 본채와 사당, 대문채 3동이 남향하여 놓여 있다. ㅁ자형의 안채와 서쪽에 위치한 사랑채가 본채를 이루는데, 안채에는 원래 6칸 대청이 있었으나 후에 4칸으로 줄이면서 방으로 바꾸었다.","a":"연안이씨별좌공종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658753.jpg"},{"q":"한국의 서정시 발전에 선구적 역할을 한 용아 박용철(1904∼1938) 선생의 생가이다. 김영랑·정지용·정인보 등과 문학 동인으로 활동하였으며, 1930년 순수시 전문지인 『시문학』을 발간하여 그 창간호에 대표작 『떠나가는 배』, 『밤기차에 그대를 보내고』 등을 발표하면서 등단하였다.『시문학』, 『문예월간』 등 문예지를 간행하였고 방대한 역시편 등을 통하여 해외문학을 우리나라에 소개한 것은 한국 근대 문학사에 큰 공적으로 평가되고 있다. 저서로 『박용철전집』2권이 있다.","a":"용아생가","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645753.jpg"},{"q":"구림리에서 도갑사쪽으로 1㎞쯤 되는 북쪽 숲속에 자리하고 있는 장승으로, 장승이 서 있는 이곳이 도갑사로 가는 옛길로 전하고 있어 절의 영역을 표시하는 기능을 했던 것으로 보인다. 높이 115∼125㎝, 폭 67∼70㎝, 두께 36∼42㎝ 크기의 자연석으로, 장승이라고는 하지만 사람이나 무신의 모습을 조각한 일반적인 형태와는 달리, 자연석 앞면에 두 줄의 테두리를 두르고 그 안에 ‘국장생’이란 글자를 큼지막하게 새긴 비석의 형상을 하고 있다. 왼쪽 윗부분은 비스듬하게 깨졌고, 장승의 좌·우 아랫부분에는 의미를 확실히 알 수 없는 글자가 보인다.","a":"영암죽정리국장승","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658375.jpg"},{"q":"향교는 공자와 여러 성현에 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 원래 진산면 읍내리 현 진산중학교에 있었으나, 임진,병자의 양란을 겪은 후 영조31년(1755)에 현재의 위치로 옮겨지었고, 정조 4년(1780)에 중수하였다. 이 후 여러 차례 중수하여 오늘에 이르고 있다. 남아 있는 건물로는 대성전, 명륜당, 외삼문, 전교실이 있다. 대성전은 정면 3칸, 측면 3칸이며, 명륜당은 정면 3칸, 측면 3칸의 중층건물이다. 전체적으로 다른 향교에서는 볼 수 없을 정도로 높은 경사지를 이용하였다.","a":"진산향교","c":"시도기념물","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652946.jpg"},{"q":"토성이 있는 곳의 서남쪽은 금호강에 접한 높은 절벽이며, 동북쪽의 일부만 제외하고는 전면에 가파른 경사가 형성되어 있다. 토성의 둘레는 약 350m 정도인데, 성벽의 높이와 너비가 소규모여서 군사적인 목적보다는 도피용 산성으로 판단된다. 토성의 남동쪽으로 약1㎞ 떨어진 낮은 구릉에는 봉무동 무덤들과 불로동 무덤들이 있고, 금호강을 사이에 두고 검단동 토성과도 연결되고 있다. 이를 통해 볼 때 이곳에는 팔공산과 금호강을 배경으로 하는 대규모의 집단이 형성되어 있었고, 이들 세력이 ○○○○을 축조하였을 것으로 생각된다.","a":"봉무토성","c":"시도기념물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645342.jpg"},{"q":"정읍시 이평면 면사무소 앞 도로 건너편에 위치한 ○○○○는 1894년 동학농민운동 당시 배들평 농민 수천명이 고부로 가기 전에 모였던 곳으로 제1차 백산기포를 할 때까지 장두청을 두고 진을 설치했던 장소이다. 또한 이곳에는 180년 정도 된 ○○○ 한그루가 서 있는데, 이 나무 아래에서 ○○○○에 모여든 농민들에게 전봉준이 군수 조병갑의 탐학과 농민 수탈의 실정을 알리고 농민봉기의 필요성을 역설하였다고 전한다. 이곳 주민들은 지금도 이 ○○○의 감은 따지 않는다고 한다.","a":"말목장터와감나무","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653724.jpg"},{"q":"두륜산 중턱에 자리잡은 ○○○는 신라 진흥왕 5년(544)에 아도화상이 지었다고 전하는 유서깊은 사찰이다. ○○○은 불경을 배우는 학승들이 거거하는 선방 겸 강당 건물로 조선 순조 13년(1813)에 고쳐 지었다고 한다. ○○○은 천불전 서쪽에 위치하고 있으며, 앞면 8칸·옆면 3칸의 규모이다. 오른쪽은 지붕 옆면이 사람 인(人)자 모양인 단순한 맞배지붕이고, 왼쪽은 여덟 팔(八)자 모양의 화려한 팔작지붕으로 지었다. 온돌방 3개와 부엌, 큰 선방과 작은 방 2개가 차례로 배치되어 있다.","a":"대흥사용화당","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639933.jpg"},{"q":"경상북도 청도군 운문면 ○○○의 동쪽에 있는 약수로 이름난 ○○○에 모셔져 있는 ○○○○○이다. 재질은 흔히 옥돌이라 부르는 것으로 경주 일원에서 흔히 볼 수 있는 흰 돌이다. 불상에 금칠을 다시 할 때 복장유물(復藏遺物)이 발견되었는데, 강희 20년(숙종 7년, 1681)에 만들어졌다는 기록이 나왔다. 조각 양식상으로 보아도 조선 후기 작품임이 분명하다. 이 시기의 불상 중 돌로 만든 불상은 그 예가 많지 않으므로 당시의 불상 연구에 중요한 자료가 된다.","a":"운문사내원암석조아미타불좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663178.jpg"},{"q":"○○○은 김자강(金自江)·완(琬)·영균(永均) 3대의 묘소를 수호하고 묘제를 지내기 위한 재실이다. 이 건물은 원래 김자강의 7세손 유음(1607∼1680)이 자강의 어머니인 안동 권씨의 묘하에 재사(齋舍)로 창건하여 ＇사암(思庵)＇이라고 했다가, 아들인 만휴(1625∼1694)가 1685년경에 현재의 위치로 옮기고 ＇○○○＇이라고 고쳐 불렀으며, 현재 그가 지은 「이건상량문(移建上樑文)」이 전해지고 있다고 한다. ○○○은 녹전면 소재지를 지나 오른쪽으로 올라가면 바라보이는 골짜기 깊숙한 곳에 위치하여 남향으로 앉아 있다.","a":"원사암","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658878.jpg"},{"q":"조선시대의 관청으로 숙종 8년(1682)에 왜구들의 도둑질을 막기 위해 설치한 수군진영이다. 전라도 우수영이 관리하는 구역이 너무 커서 이곳에 수군진영을 두어 가리포·고군산·법성포·군산포 등 서남 연안지방을 관리하게 하였다. 현재 지방관이 공적인 일을 처리하던 동헌만이 남아있어 본래의 모습은 찾기 어렵다. 앞면 5칸·옆면 3칸 규모로 1층이며, 지붕은 옆면이 여덟 팔(八)자 모양으로 가장 화려한 팔작지붕이다. 현재 이 건물은 면사무소로 사용하고 있다.","a":"위도관아","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639522.jpg"},{"q":"부춘정은 강진에서 영암으로 입향 한 진주강씨 문중에서 1618년(광해군 10)에 건립한 것으로 1672년경 등 몇 차례 중수하였다. 안쪽이 전부 방으로 구성된 구조로 보아 단순한 정자로서의 기능 보다는 서재와 학숙 기능도 함께 하였을 것으로 보이며, 주변풍광도 뛰어나 관련시문이 다수 전하고 있다. 특히, 건조물 구조의 희귀성 등 건축사적 가치가 있다. 부춘정은 평면 구성으로 정면 4칸, 측면 2칸으로 전면(前面)을 벽 없는 마루로 하고 배면(背面)을 벽으로 막아 방을 만들어 전후(前後)가 대칭적으로 처리되어 있다. 건축구조적인 면에 있어서 전후병렬식 겹집이다.","a":"영암부춘정","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640210.jpg"},{"q":"조선후기 선사 진영을 대표하는 작품으로 상호가 자상하고 사실적이며 전체 색조 또한 안정되어 있다. 보조국사 진영에 비해 격이 떨어지지만 한 시대를 대표할 만한 작품이다. 이 진영은 조선말기의 작품이지만 당시 시대적 특징을 잘 간직한 수작이다.","a":"동화사죽암당대선사선찰진영","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659500.jpg"},{"q":"조선 시대 명망 있는 재상으로 칭송되었던 방촌 황희(黃喜, 1363∼1452) 선생의 묘소이다. 조선 초기 국가 기반을 확립하는 데에 큰 업적을 남겼고, 4군 6진의 개척, 문예진흥 등을 지휘하여 세종성세(世宗盛世)에 공헌하였다. 묘역은 부인 청주양씨(淸州楊氏)와 합장된 하나의 봉분 형태이다. 봉분은 커다란 직사각형태에 앞부분에 ‘ㄷ’자 모양의 둘레석을 하단에 쌓은 형태로 조선초기의 독특한 묘제이다. 묘역은 계단식으로 3단으로 나누고 계체석(階砌石 ; 묘역을 구분하는 편평하고 긴 경계석)으로 구분하였는데, 고려의 묘제를 계승한 조선 초기의 묘제이다.","a":"황희선생묘","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646032.jpg"},{"q":"고(故) 박정희 대통령의 영부인 ○○○ 여사가 1925년 11월 29일에 태어난 장소이다. 현재 건물은 없지만 1600년대 김정승 이후 송정승 및 민정승이 거주하여 삼정승의 집이라 불리던 가옥을 ○○○ 여사의 부친인 육종관씨가 민정승의 자손 민대감에게서 1920년 매입하였다고 한다. 6,047㎡의 대지 위에 1970년 초에 개축된 관리사·사당 등만 남아 있으며, 주변은 울창한 산림이 형성되어 있고 본채·사랑채·별당 등 10여동의 건물이 있었다고 하나 현재 터만 남아 있으며 주변은 연못과 정원으로 이루어져 있다.","a":"옥천 육영수 생가","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651047.gif"},{"q":"『반야바라밀다심경』은 줄여서 ‘반야심경’이라고 부르는데, 여러 종파에서 공통적으로 읽고 외우는 보편적인 경전이다. 이 불경은 ○○○○이『반야바라밀다심경』을 구절마다 상세히 해설을 붙인 책으로 1책의 목판본이다. ○○○○은 당나라의 고승으로, 원성왕 7년(791) 선원을 창건하여 영산(靈山)이라 하였는데, 법을 전한 문인이 1,000명이나 되었으며 스스로 호를 ○○○○이라 하였다. 이 판본은 조선 태종 11년(1411)에 전북 고창 문수사에서 간행된 것으로서 조선 전기 불경연구 및 서지학 연구의 귀중한 자료로 평가된다.","a":"범어사 태전화상주심경","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636664.jpg"},{"q":"진산부원군 ○○은 1398년 1차 왕자의 난에 이방원을 도와 정사공신이 되고, 1400년 2차 왕자의 난에 이방원을 도와 태종으로 등극시킨 좌명공신이다. 진산부원군묘당은 ○○군 병곡면 도천리 도천마을에 있으며 외삼문인 대문간채와 내삼문, 사당, 그리고 맞배지붕으로 되어있는 문충세가 안채와 아랫채로 구성되어 있으며, 사당은 모로 단청에다가 벽면에는 벽화를 그려 넣었다.","a":"함양 하륜 부조묘","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2623297.jpg"},{"q":"용화산 동쪽 경사면의 진주 소씨 묘지 가장 위쪽에 자리하고 있는 소자파 선생의 묘비이다. 소자파 선생은 조선 성종 14년 사마시에 합격하여 의빈부도사를 거쳐 중종 19년 구례의 임지에서 73세에 순절하였다. 그의 아들 소세양이 벼슬이 올라감에 의해 가선대부 이조참판과 숭록대부 의정부좌찬성겸의금부사를 추증받았다. 묘비는 화강암으로 만든 받침돌과 대리석으로 깍은 비몸·머릿돌을 갖춘 형태이다. 4각의 받침돌은 국화무늬를 조각하였다. 머릿돌은 앞·뒷면에 연꽃과 구름무늬를 새겨 넣었는데 그 조각이 매우 섬세하고 뛰어나다.","a":"소자파묘비","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661802.jpg"},{"q":"○○○는 조선시대 병조에 소속된 기관으로 말 사육 및 전국의 목장, 왕의 가마 등을 관장하는 기구로서, 이 지도는 ○○○가 관장하던 성동구 일대의 ○○○ 목장을 그린 지도로, 제작시기는 1789년에서 1802년 사이로 추정된다. 이 지도는 ○○○ 목장의 전반적인 상황에 대해 상당히 자세한 정보를 수록하고 있으며, 현전 자료가 희소하고 마정사 연구에 자료적 가치가 높다.","a":"사복시 살곶이 목장지도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636520.jpg"},{"q":"이 마애불상은 자연바위 한쪽 면에 얕게 새긴 ○○○○으로서 머리부분은 양각(陽刻)되어 있으나 나머지 면은 선각(線刻)에 가깝게 조각되어 있다. 대좌와 광배가 생략되어 있으나 인위적인 손상이 없는 완형이며, 조각솜씨가 미숙한 면이 있으나 어수룩하고 소박한 분위기를 주는 등 고려시기 지방양식을 잘 반영하고 있다.","a":"영주휴천동마애여래좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663591.jpg"},{"q":"○○○은 ○○○의 인동장씨 입향조 사계 장여화(1566~1621)의 아들 장용경(1604~1695)이 건립했다고 전해지는 정자이다. 현재도 정자에 걸려 있는 ○○○이라는 현판에는 ○○○입각후지라 하여 내력을 짐작하게 하는 내용이 새겨져 있다. 이에 의하면 ○○○이라는 글자는 조여익이 장용경에게 써 준 것으로, 1738년(영조 14)에 글자는 장한공이 지본(紙本)이 더러워지자 판각하여 걸게 되었다.","a":"영주 금광리 만연헌","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020030409304800.jpg"},{"q":"정려란 충신·효자·열녀 등 모범이 되는 사람을 표창하고자 집 앞에 정문(旌門)을 세워 기리던 것으로, 이 비는 조선시대 사람인 박구의 효행을 기리고 있다. 박구(?∼1425)는 효성이 지극한 자로, 그의 어머니가 돌아가시자 3년간 묘곁을 지키면서 한번도 집에 돌아가지 않았다고 한다. ○○○는 높이 110㎝, 폭 43㎝, 두께 16㎝의 비석으로 앞면에 비문을 새겼다. 비를 보호하기 위한 비각은 앞면 1칸·옆면 1칸의 규모로, 옆면에서 볼 때 지붕선이 사람 인(人)자 모양과 비슷한 맞배지붕을 올리고 있다.","a":"박구효자정려비","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658846.jpg"},{"q":"○○○○ 묘소의 ○○○은 망주석 바깥에 서로 마주보고 있는 형태로 서 있는데, 그 크기는 높이 190cm, 앞면의 너비가 55cm로서 보통 사람보다는 훨씬 덩치가 큰 모습이다. 문인의 얼굴 모습은 반듯하고, 머리에 쓴 관과 입은 관복이 매우 섬세하게 표현되어 있으며, 옷의 주름이나 얼굴 곳곳의 부분 모습이 마치 실제 입은 옷을 보는 것 같고 마치 살아 있는 모습을 보는 것처럼 사실적이고 부드럽게 묘사되어 있다.","a":"산청 장수황씨 묘비 및 문인석","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665984.jpg"},{"q":"충청남도 서천군 남산 정상부를 둘러 쌓은 산성으로, 가로·세로 30∼40㎝ 크기의 자연석을 이용하여 성벽을 쌓았다. 둘레 620m의 성은 폭 2.6m의 남문터와 폭 2.5m의 서문터가 확인되었으며 성안에는 6∼9m의 통로가 성벽을 따라 돌아가고 있다. 현재 성벽은 남쪽과 북쪽에 남아있고, 벽이 붕괴된 지점에서는 삼국시대 토기조각과 기와조각이 발견되었다. 발견된 유물을 통해 삼국시대에도 이미 주거지로 사용되었음을 알 수 있다. 『신증동국여지승람』에 의하면 석축의 둘레가 1,545척이고 성안에는 우물이 1개있었으며, 세종 때 지세가 좋지 못하여 읍성을 옮겼다고 한다.","a":"서천남산성","c":"시도기념물","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652847.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 정확한 연대는 알 수 없으나, 조선 인조(재위 1623∼1649) 때 세운 것으로 전한다. 대성전은 숙종 8년(1682)에 수리하였다는 기록이 있으며 1987년에 다시 한번 보수했다. 건물 배치는 외삼문 없이 앞쪽에 바로 교육 공간인 명륜당이 있고, 뒤쪽에 제사 공간인 대성전이 있어 전학후묘의 형태를 따르고 있다. 대성전은 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"덕산향교","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653014.jpg"},{"q":"경포호수에 가까이 있는 해운정과 담 하나를 사이에 두고 있는 집이다. 지은 연대를 정확히 알 수 없으나, 안채는 350∼360년, 사랑채는 250∼260년 정도 된 것으로 보인다. ㅁ자형으로 배치되어 있으며, 대문을 중심으로 오른쪽에 ㄱ자형의 사랑채, 왼쪽에 외양간이 있다. 마당을 가운데에 두고 안채가 있는데, 사랑채와 연결되는 1칸은 비워져 통로의 역할을 하고 있다. 안채는 앞면 4칸·옆면 2칸의 겹집으로, 4개의 방을 배치하였고 안마당쪽에는 툇마루를 내었다.","a":"강릉 수리골 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638055.jpg"},{"q":"○○○이 1604년 협상 사절로 일본에 파견될 때, ‘○○○’가 내려졌던 것으로 확인된다. 그 ○○○의 명칭은 ‘대선교등계의병대장군이조판서겸지의금부사육군문도총령송운사명유정대사○○○(大禪敎登階義兵大將軍吏曹判書兼知義禁府事六軍門都摠領松雲四溟惟政大師司命旗)’로 그 실물은 현재 전하지 않는다.","a":"밀양 표충사 사명당 사명기","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642119.jpg"},{"q":"고려 후기 충숙왕(재위 1313∼1330)의 사위였던 최문한을 기념하기 위하여 세운 비(碑)와 비각(碑閣)이 있는 곳이다. 최문한은 고려 왕조의 세력이 점차 약해지고 이성계가 등극하자, 두문동(杜門洞)에 들어가 고려에 대한 충의를 지키다가 강릉으로 내려왔다. 부인과 함께 고향으로 내려온 최문한은 항상 말을 타고 송경을 왕래하며 나라 일을 걱정하였다. 하루는 송경으로부터 돌아오는 길에 이곳의 버들가지에 말을 매고 손을 씻고 있었는데, 말이 갑자기 못에 뛰어들더니 용(龍)으로 변하여 구름과 안개를 타고 사라졌다는 전설이 있어 이곳을 ○○라 하게 되었다고 한다.","a":"용지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647613.jpg"},{"q":"○○○○○는 1960년 3월 15일, 자유당 이승만 독재정권이 저지른 부정선거에 항거한 마산 3.15의거 시위 중 행방불명되었다. 그로부터 27일 후인 4월 11일, 마산 앞바다에 떠오른 ○○의 ○○은 오른쪽 눈에 최루탄이 박혀 끔찍한 모습이었다. 독재자의 하수인인 경찰들이 3.15의거 현장에서 쓰러진 ○○의 ○○에 돌을 매달아 바다에 던져버렸던 것이다. 이와 같은 독재자의 만행에 마산 시민들의 분노는 민중봉기로 폭발했다. 그리고 이날, 4.11마산민주항쟁의 불길이 전국으로 번져 마침내 4.19혁명으로 이루어졌다.","a":"창원 김주열 열사 시신 인양지","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657581.jpg"},{"q":"『삼국사기』32권에 ‘우화’라고 기록되어 있는 곳으로 해마다 봄과 가을에 기우제를 지내던 장소이다. 임진왜란 때 왜병들이 ○○○ 남쪽에 진을 쳤다가 그날 밤 신풍이 일어 몰살당했으며, 일제가 사당을 허물 때 기와장을 뜯던 인부가 피를 토하고 죽고 이 일을 지휘하였던 일본 헌병도 자살하였다는 이야기가 전하고 있다. 다른 문헌 기록에 따르면 신라시대부터 나라의 태평과 국민의 평안을 빌기 위한 제사를 해마다 음력 2월에 지냈으며, 가뭄 때 비를 빌면 특히 효험이 있었다고 전한다.","a":"양산 우불산 신사","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664280.jpg"},{"q":"○○○○○는 ○○○ 선생의 정면5칸 측면2칸 한옥의 가정집 형식으로 건축 연도가 명확하며 건축물의 보존 상태가 양호함 특히 안채가 원형의 구성을 잘 보존하여 있어 시대성을 잘 반영하면서 장식적인 구성이 매우 아름다운 주거 형태로 보존되어 교육적 역사적 자료 등으로 활용가치가 높음.","a":"진주 허만선 고가","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017092910404500.JPG"},{"q":"석가모니불과 아미타불, 약사불로 이루어진 ○○○상으로서 현재 고창 ○○○ 대웅전에 주불로 봉안되어 있다. 3구 모두 높이가 140-150cm에 이르는 거대한 불상으로, 현 대웅전의 규모에 비하여 불상이 다소 큰 듯한 것으로 볼 때 처음부터 이곳에 봉안되었던 것은 아닌 것으로 생각된다. 전언(傳言)에 의하면 이 불상은 3번이나 도난을 당하였다가 되찾아오곤 하였는데 백양사의 만암스님이 대웅전을 짓고 그곳으로 모셔가려 하였으나 움직이지 않아서 그대로 두었다고 한다.","a":"상원사목조삼세불좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639795.jpg"},{"q":"○○○ 대웅전 내에 있는 신중탱화로서, 인도의 재래적인 토속신인 신중을 그린 불교 그림이다. 신중은 불교의 토착화 과정에서 수용된 불교의 호법신들인데, 이처럼 별도로 그림을 그려 신앙의 대상을 삼기도 하였다. 비단 바탕에 채색하여 그렸으며, 크기는 가로 200㎝, 세로 140㎝의 크기이다. 화면을 상하로 구분하여 상단에 제석을 중심으로 하늘의 천인상을 그려 놓고, 하단에는 호법신인 신장을 그려 넣었다. 색상의 사용법, 인물의 표현기법, 제작연대 등이 같은 대웅전 안에 있는 영산회상도와 같다.","a":"보문사 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587794.jpg"},{"q":"관우에게 제사 지내는 사당인 보물 제142호 <동묘(東廟)>에서 치성(致誠)을 드릴 때 사용하던 백자 병으로 목이 길고, 무게 중심이 하단으로 쳐져 있어 전체적으로 안정감을 준다. 구연부(口緣部 : 입구 부분)는 살짝 밖으로 말려 있고, 푸른색을 띠는 유약을 전체적으로 발랐다. 몸체 상단부에 돋을새김으로 된 ‘東廟致誠甁 庚辰三月日(○○○○○ 경신삼월일)’이라는 한자 명문이 있다. 기형과 제작기법을 고려했을 때 이 백자가 제작된 연대를 표현해주는 경신년은 1820년(순조 20) 또는 1880년(고종 17)으로 추정된다.","a":"백자‘동묘치성병’명병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636554.jpg"},{"q":"진주 ○○○ 대웅전에 봉안되어 있는 삼존불 중 중앙의 본존불은 조선시대에 조성된 木造阿彌陀佛坐像이며, 그 좌우의 협시보살상은 근래에 조성된 것이다. 사찰 측에서 전하는 바에 의하면 이 본존불은 固城 운흥사에 있던 것을 이곳으로 옮겨온 것이라 하며, 다른 복장물은 모두 사라지고 10여종의 다라니경만이 발견되었다고 한다. 이 불상은 높이가 1m가 넘는 크기로 통견에 항마촉지인을 결한 채 결가부좌하고 있는데 양다리 사이의 군의자락과 뒷면 등의 개금이 일부 박락되었으나 이를 제외하면 상태는 대체로 양호한 편이다.","a":"진주연화사목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643070.jpg"},{"q":"○○○○○는 선사시대 유적이 다수 분포해 있고 백제시대 이래 고려시대까지 정안현-○○부-회주목으로 이어지는 고을이 있던 지역이다. 고려시대 말기에 왜구로 인해 치소를 옮긴 뒤, 고읍으로 불리게 되며 임진왜란이 지난 뒤 ○○위씨가 입향하여 집성촌을 이룬다. 전통 반가는 물론 사당과 서재를 갖추고 있고 존재 위백규 등 학자들이 활동하여 문집, 고문서, 전적류와 민속문화유산이 잘 남아 있다.","a":"장흥 방촌리 근암고택","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2020031014182000.JPG"},{"q":"<○○○○○>은 1817년(순조 17) 3월 11일 성균관에서 치러진 효명세자[孝明世子, 1809-1830, 뒤에 익종(翼宗)으로 추존]의 입학례를 기념한 화첩이다. 입학례의 과정을 다섯 장면으로 구성하고, 이튿날(3월 12일)에 있었던 진하례 장면을 마지막에 그려넣었다. 표지에는 ‘○○○출궁도(王世子出宮圖)’라고 쓰인 표제가 붙어 있으나 이 표제는 ○○○ 입학례 절차 중에서 세자가 성균관으로 가기 위해 궁궐을 나오는 처음 일부분만을 의미하므로 이 화첩의 명칭은 전체 내용을 포괄하는 <○○○○○>으로 지정한다.","a":"왕세자입학도첩","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636536.jpg"},{"q":"이 석상은 현재 ○○○ 문수전에 봉안되어 있으며, 일명 문수보살상으로 알려져 있다. 규모는 높이 167㎝, 머리높이 53㎝, 머리폭 27㎝, 신체폭 55㎝ 정도이다. 「○○○사적기」에 의하면 신라 승려 자장율사가 당나라에 건너가 청량산에서 기도를 거듭한 끝에 문수보살의 계를 깨닫고 돌아와 우연히 이 곳을 지나다 보니 산세가 당나라의 청량산과 비슷하여 굴속에 들어가 7일 기도를 하자 문수보살이 나타나서 이곳에 문수도량을 개설하였다고 한다. 석상은 돌로 만든 대좌 위에 세워져 있으나 무릎 이하 부분이 절단되었다.","a":"문수사석조승상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661865.jpg"},{"q":"○○○은 조선 숙종 10년(1684)에 가평군수 이제두(李齊杜)와 허격(許格), 백해명(白海明) 등이 명나라가 임진왜란 때 베푼 은혜와 청나라로부터 당한 굴욕을 잊지 말자는 뜻의 암각서가 새겨진 바위이다. 바위에는 허격이 가져온 명나라 마지막 임금 의종(毅宗)의 친필 '사무사(思無邪)'를 맨 위쪽에 새기고 그 아래 선조의 친필인 '만절필동(萬折必東) 재조번방(再造蕃邦)'과 효종이 송시열(宋時烈)에게 내린 글 가운데 8자인 '일모도원(日暮道遠) 지통재심(至痛在心)'을 송시열의 서체로 각자(刻字)하였다.","a":"조종암","c":"시도기념물","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645992.jpg"},{"q":"윤보선 전 대통령의 생가와 나란히 있으며, 윤씨 일가가 같이 쓰는 솟을대문을 통해 들어가도록 되어 있다. ㄱ자형의 안채와 ㄴ자형의 사랑채가 어우러져 튼 ㅁ자형의 평면구조를 이루고 있다. 안채는 넓은 대청을 중심으로 한쪽에 안방과 부엌이 있고 다른쪽에는 건넌방이 있다. 건넌방은 대청보다 높은 툇마루를 두어 변화있게 구성하였다. 사랑채의 지붕은 옆면이 여덟 팔(八)자인 팔작지붕이며 기단도 일부 남아있다. 기둥을 비롯한 나무들이 전반적으로 가늘지만 각 방들이 비교적 넓게 꾸며져 있어 조선 후기 한옥의 특징을 잘 보여주고 있으며, 중부지방의 양식을 갖추고 있는 집이다.","a":"윤일선가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658260.jpg"},{"q":"계족산성에서 동남쪽으로 1.3㎞ 떨어져 있는 해발 363m의 개머리산 또는 견두산의 꼭대기를 빙둘러 쌓은 산성으로, 성의 둘레는 280m 정도이다. 성벽은 자연 암반을 이용하면서 자연석으로 쌓았는데, 남벽의 일부를 제외하고는 성벽의 대부분이 무너져 내린 상태라 현재는 그 윤곽만을 확인할 수 있다. 성의 동쪽부분에는 지름 6m 정도를 높게 만들어 놓았는데, 지휘자가 망을 볼 수 있게 만들어 놓은 장대가 있었던 것으로 짐작된다. 산성의 바로 밑으로는 신탄진-옥천 간의 도로가 동쪽과 북쪽의 띠를 두른 듯 휘감고 지나고 있으며, 성의 동쪽으로는 대청호가 내려다 보인다.","a":"견두산성","c":"시도기념물","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645803.jpg"},{"q":"경상남도 사천시 정동면에 있는 이 산성은 일명 ‘고읍성’이라고도 한다. 옛 사천고을의 중심이 되는 읍의 소재지가 산성과 가까운 정동면 고읍리에 있었기 때문에 붙여진 이름이다. 성은 정상의 산봉우리를 둘러싼 테뫼식 산성으로, 현재는 둘레 약 1109m, 높이 3.5m의 흙으로 쌓은 성벽이 남아 있다. 그러나 남쪽 가파른 언덕에 길이 4m, 높이 3m 가량의 돌로 쌓은 벽이 남아 있어, 원래는 흙과 돌을 혼합하여 쌓은 산성으로 보인다.","a":"사천성황당산성","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655694.jpg"},{"q":"조선시대 만들어진 높이 107㎝, 입 지름 73㎝의 종이다. 종을 메다는 고리는 용이 여의주를 갖고 있는 형상이며, 옆으로 소리 울림을 도와 주는 음통이 있다. 종 윗부분에는 꽃무늬로 띠를 두르고, 아래 구슬 모양의 돌기가 한 줄 돌려 있다. 밑으로는 8개의 원을 양각하여 그 안에 범자를 새겨 넣었다. 몸통의 중심에는 머리 뒤에 둥근 광배를 두르고 보관을 쓴 보살 입상과 전패(殿牌)가 있고, 보살 입상 사이에는 사각의 유곽을 배치하였다. 유곽 안에는 9개의 꽃무늬로 된 유두가 있다. 종의 가장 아랫부분에는 덩굴무늬를 두르고 있다.","a":"송광사동종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639600.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 6년(1406)에 서문 밖에 세웠다. 그 뒤 선조 7년(1574)에 군수인 최여림이 지금 있는 자리로 옮겨 세웠다. 향교 안에 있는 건물로는 대성전, 명륜당, 동무, 서무, 동재·서재, 내삼문, 외삼문이 있다. 제사를 지내는 공간인 대성전은 앞면 3칸·옆면 3칸 규모이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 안쪽에는 공자를 비롯한 중국 유학자 7명과 우리나라 성현 18명 등 25명의 위패를 모시고 있다.","a":"서산향교","c":"시도기념물","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652904.jpg"},{"q":"원주 ○○○○○ 소장 ○○○○○경은 성종 때 인수대비가 성종의 장수를 위해 간행한 이후 여러 차례 다시 새겨 찍은 ○○○○○경 중에서 가장 우수한 판화양식을 보여주는 것으로, 권말의 간기나 관련 기록은 없으나 성종 때 간행본의 16세기 번각본으로 중요한 자료적 가치를 지니고 있다.","a":"원주고판화박물관소장불정심다라니경","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660673.jpg"},{"q":"조선 중기의 고승인 ○○○○의 초상화이다. ○○○○의 자는 현응(玄應)이며, 호는 청허이고, 다른 이름은 서산대사(西山大師)이다. 조선 선조 25년(1592) 임진왜란이 일어나자 왕의 특명을 받아 노령으로 전국에 격문을 돌려 승병 1,500여명을 모아 활약하는 등 전쟁에 공을 세웠다. 초상화는 비단 바탕에 채색하여 그려진 것으로, 향좌측을 바라보며 의자에 앉아 있는 전신교의좌상(全身交椅坐像)으로서 족좌대(足座臺)를 하고 있다. 왼손에는 짙은 갈색의 염주를 쥐고 있고, 오른손은 의자의 손잡이를 살짝 쥐고 있다.","a":"함양 용추사 청허대사 영정","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023102312352700.jpg"},{"q":"김집(1574∼1656)의 위패를 모신 사당이다. 김집은 조선 중기 유학자이며 호는 신독재이다. 많은 벼슬자리가 있었으나 나가지 아니하고 자연에서 도를 즐기고 학문에 전념한 인물이다. 저서로는 『신독재문집』, 『의례문해속』등이 있다. 조선 인조 7년(1629)에 지은 사당은 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 마루를 깔고 벽면에는 위패를 모실 수 있는 단을 높게 설치하였다.","a":"김집선생사당","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661361.jpg"},{"q":"용암 김익중(1678∼1740) 선생의 옛 집으로 영조 4년(1728)에 지었다고 전한다. 원래는 대문간과 몸채 사이 사랑마당 좌우에 부속채가 있었다고 하는데, 현재는 몸채와 대문간만 남아있는 상태다. 막돌로 쌓은 기단 위에 세운 몸채는 안방 위쪽에 창고방을 두고 접하여 대청쪽으로 곳간 1칸을 돌출시킨 것이 특색이다. 곳간의 뒷부분에는 널판을 달아 다락을 다시 꾸몄다.","a":"인양리용암종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658705.jpg"},{"q":"이 불상은 사명대사의 원불(願佛)이라 전하는 높이 9.5㎝의 소형 ○○○○○이다. 연화대좌 위에 편단우견의 대의를 입고 결가부좌하였으며, 왼손은 선정인, 오른손은 무릎 아래로 내려 촉지인을 결하고 있다. 대좌는 앙련과 복련이 연접한 2중의 연화좌인데 이는 고려시대 말에 유입된 라마교의 불상양식으로 이를 통해 제작연대를 추정해 볼 수 있다. 소규모의 불상이지만 안정적인 비례감을 지니고 있고, 손톱과 발가락, 연화좌 등 세부표현도 매우 치밀하게 이루어져 있다. 원만상일 뿐만 아니라 완형이며 보존상태도 양호하다.","a":"포항 대성사 소장 금동여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641210.jpg"},{"q":"부산진(釜山鎭)은 조선 태종 7년(1407) 낙동강의 동쪽지역인 경상좌도(慶尙左道) 수군의 사령부로서 휘하 11개의 수군진성과 함께 동남해안의 방어임무를 맡기도 하였다. 당시 수군은 배를 타고 바다에서 근무하는 것이 원칙이었다. 그러나 성종 21년(1490) 병선의 정박처로서 수군과 물자를 보호하기 위하여 둘레 2,026척의 ○○○○을 증산(甑山) 아래에 쌓게 되었다. 선조 25년(1592)의 임진왜란(壬辰倭亂) 첫 전투 때 부산진의 지휘관인 첨사(僉使) 정발(鄭撥)을 비롯한 군사와 백성들이 끝까지 싸웠으나 마침내 ○○○○이 함락되었다.","a":"부산진성","c":"시도기념물","nc":"","r":"부산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644941.jpg"},{"q":"○○○란 옛 선현의 자취가 있는 곳을 후세에 전하고 이를 계기로 그를 추모하기 위해 세워두는 비로, 이 비는 조선시대 전기의 문신이면서 사육신의 한사람인 ○○○ 선생의 공적을 적고 있다. 선생은 세종 29년(1447) 문과 중시에 장원으로 급제한 후 집현전 학사로 뽑혀 왕의 극진한 총애를 받았다. 왕이 훈민정음을 만들 때에는 정인지·최항·박팽년 등과 함께 훈민정음의 반포에 크게 공헌하였다. 수양대군이 어린 조카 단종의 왕위를 빼앗아 즉위하자 박팽년, 유응부, 허조, 이개 등과 함께 단종의 복위를 도모하다 발각되어 죽음을 당하였다.","a":"성삼문선생유허비","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661160.jpg"},{"q":"조선 선조 3년(1570)에 어은 이용이 지은 것으로 전해지는 누정이다. 원래는 와룡면 도곡동에 있던 것을 1974년 안동댐 건설로 인하여 지금의 위치로 옮겨 지은 것이다. ○○○과 재사, 부속건물이 흙담에 둘러싸여 있다. ○○○은 앞면 3칸·옆면 2칸 규모의 정자로, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 재사는 앞면 5칸·옆면 6칸의 ㅁ자형 건물이다. 안방·대청·건넌방이 ㅡ자로 배치되어 있고, 맞은편 아래채에 방·마루·대청·외양간·대문·서고·부엌·헛간이 있다.","a":"어은정및재사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640302.jpg"},{"q":"경기도 남양주시 불암사에 있는 목판으로 대부분 조선 인조 13년(1635)에서 정조 19년(1795)에 간행된 것들이다. 크기는 그 유형에 따라 다르나 대형은 가로 64㎝, 세로 35.5㎝이고, 소형은 가로 47㎝, 세로 23㎝이다. 나무질이 부드러운 자작나무판을 사용하였으며 양끝에 나무를 끼워 나무판의 뒤틀림을 방지하였다. 이 경판에는 대승경전, 위경류, 진언다리니류와 부처가 사는 세계와 관련된 문헌 등이 실려있다. 글씨에는 힘이 있고 판에 새겨진 글씨체는 그 새김이 매우 섬세하여 조선 판본의 우수성을 과시하고 있다.","a":"불암사경판","c":"시도유형문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637427.jpg"},{"q":"송천자 권득여(權得輿, 1636~1716) 선생이 영해 관어대에서 이곳으로 이거하였는데, 이 고택은 선생의 아들 칠우정 권대림선생의 주택으로 1700년대에 건립된 日자형의 가옥이다. ○○○○은 4칸 규모의 대문채를 들어서면 좁은 마당을 사이에 두고 정면5칸, 측면5칸반 규모의 口자형 정침이 자리 잡고 있다. 정침의 중문좌측에는 외양간과 곳간을 두었는데 곳간의 뒤에는 통래간과 부엌이 연접되어 좌익사를 이루면서 안채와 연결되어 있으며, 중문의 우측에는 사랑채가 자리잡고 있는데, 책방과 사랑윗방이 연접되어 있으며 사랑윗방뒤에는 사랑아랫방을 두어 우익사와 연결되어 있다.","a":"영덕 송천세려고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2018101609252500.JPG"},{"q":"○○○에 보존되어 있는 ○○○인데, ○○○는 칠성(七星)을 불교의 호법선신(護法善神)으로 수용하고 이를 의인화하여 묘사한 그림이다. 이 ○○○는 비단 바탕에 채색하여 그려진 것으로, 화면은 중앙의 여래 1구를 중심으로 좌우측에 여래 3구씩을 각각 배치하여 칠성여래를 나타내고, 칠성여래 아래쪽 하단에는 각각 동자들을 묘사하였다. 그리고 구름무늬를 경계로 칠성여래 상단에는 군상들을 3그룹으로 나누어 각각 표현하고 있다.","a":"범어사칠성도","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659359.jpg"},{"q":"○○○는 신라 문무왕 4년(664) 원효대사가 수도하기 위해 토굴의 형태로 세웠다. 통일신라 흥덕왕 3년(828)에 심지왕사가 고쳐 세운 뒤, 여러 차례 소실되고 다시 지었으며 근래에는 명부전과 누각을 고쳐 세웠다. ○○○은 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. 조선 후기에 지은 것으로 보이지만 조선 전기 건축 수법도 부분적으로 볼 수 있다.","a":"청도 적천사 대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641305.jpg"},{"q":"○○○○○(無患樹, Chinese Soapberry, Soapnut Tree)의 학명은 Sapindus mukorossi Gaertner이다. ○○○○○과(Sapindaceae：주로 열대에 약 120속 1000종 가량, 온대에도 수종, 우리나라는 2속 2종)의 ○○○○○속(Sapindus Linne：주로 열대에 약 15종, 우리나라에 1종)식물로 우리나라 남부의 절 및 마을 부근에 나는 낙엽교목이다. ○○○○○는 흉고직경(DBH) 90∼96㎝, 근원직경 110∼120㎝, 나무높이(H)는 21∼22m, 수관폭 8∼11m 크기로 나이는 600년 가량이다.","a":"진도초하리무환자나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654370.jpg"},{"q":"○○○은( 炳九, 炳來, 炳殷 ,炳周, 炳斅, 炳旼)육분을 뜻을 모아 위손(胃孫) 석우(錫佑)가 재종숙질과 더불어 논이 하여 ○○○을 건립하였으며 1960년대까지 서당으로 활용하였으며 유림의 거두이자 한학자인 춘산(春山) 이상학(李相學)과 성암(誠菴) 윤석희(尹錫熙)와 애국지사 윤중수가 ○○○에서 학문을 배워다.","a":"합천 육우당","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666796.jpg"},{"q":"○○○은 창애 이중광(1709∼1778) 선생이 지은 정자이다. 이중광 선생은 영조 18년(1742)에 추천을 받아 관직에 임명되었으나 나아가지 않고, 이곳에서 사람들과 학문을 토론하고 연구에 전념하면서 후배를 양성하였다. ○○○은 앞면 4칸·옆면 3칸 규모이며 ㄱ자형 평면을 갖춘 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"창애정","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662915.jpg"},{"q":"2층 기단(基壇)을 쌓고 그 위에 5층의 탑신(塔身)을 올린 석탑이다. 기단은 아무런 조각 장식이 없는 단조로운 모습이다. 홀쭉하고 높아 안정감이 없어 보이는 탑신부는 몸돌과 지붕돌은 각각 한돌로 쌓아 올렸다. 1층 몸돌은 지나치게 크고, 2층은 급격히 낮아졌다. 지붕돌은 밑면에 1층에서 4층까지는 3단, 5층은 2단의 받침을 두었고, 윗면에는 급한 경사가 흐르며, 네 귀퉁이는 높이 치켜 올라갔다. 간결하면서 단정한 이 탑은 지붕돌받침이 4∼2단으로 일정하지 않고, 처마의 네 귀퉁이가 많이 올라간점 등으로 보아 고려시대의 작품으로 추정된다.","a":"나주송제리오층석탑","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639922.jpg"},{"q":"함안 조씨 덕곡파 11대손 조용헌이 조선 고종 32년(1895)년에 지은 집이다. 一자형 평면을 가진 안채와 사랑채를 앞뒤로 나란히 배치하였고 안채 좌우에 곳간채와 외양간채가 직각으로 놓여 전체로는 ㅁ자형 구조이다. 안채는 앞면 5칸 규모로 대청이 2칸을 차지하고 있다. 대청 뒤쪽에 벽을 막아 제사에 쓰이는 물건을 보관하는 제청의 기능을 갖게 만들었는데, 민가에서 대청이 제사의식을 행하는 공간으로 쓰이는 전통을 잘 보여주고 있다. 경사진 대지를 이용하여 건물들을 배치하였기 때문에 기단을 높게 쌓았으며, 전형적인 남부 민가의 형식을 따르고 있다.","a":"사천환덕리조씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664081.jpg"},{"q":"경남대학교 박물관 소장 ‘데라우치문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 데라우치 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 데라우치문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 데라우치문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다.","a":"강표암선생유묵(경산이한진전서첩)","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913494100.jpg"},{"q":"○○○○○ 소장 ○○○는 교지, 망기, 명문, 분재기, 서목, 소지, 시권, 완문, 입안, 전령, 첩문, 표기, 호구단자, 준호구, 양안, 입지 등 총 122점이다. 이들 자료는 시기가 확인되지 않는 것도 있지만 대부분 15세기 말에서 20세기 초(1487년 ～ 1901년)에 이르는 것들로 산만한 경향이 있지만, 이 가문에 속한 사람들의 학문적 교유관계 뿐만 아니라 사회·경제적 동향 등을 포괄적으로 보여주는 것이라는 점에서 중요한 의미를 지닌다.","a":"울진장씨고산성파소장고문서","c":"시도유형문화유산","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641175.jpg"},{"q":"이 비석은 구산(龜山) 윤탁(尹鐸, 1554∼1593)과 추담(秋潭) 윤선(尹銑, 1559∼1640)의 학덕을 기리기 위하여 세운 2기의 ○○○이다. 구산 윤탁은 조선 선조 25년(1592)에 임진왜란이 일어나자 의병을 일으키고, 1593년에는 진주성에 들어가 왜적을 막다가 순절하였다. 추담 윤선은 임진왜란 기간 동안 세자(世子)의 막하에서 활동하였고, 광해군 때 의정부 우참찬을 지냈다. 이 2기의 비석은 모두 신축년(1901년)에 세워졌는데, 내용만 다를 뿐 재질과 모양 및 크기가 서로 같다.","a":"합천 구평윤씨 신도비","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664869.jpg"},{"q":"조선시대 충청도 관찰사가 공무를 집행하던 곳이다. 도내의 일반 행정·군사·조세 및 중요한 재판이 행해졌다. 원래 태조 4년(1395)에 충주에 설치되었으나 선조 35년(1602)에 공주로 옮겨와 충청도 전체를 관장하는 지방행정의 중심지가 되었다.『여지도서』에는 ○○○을 비롯하여 50여 채의 건물과 칸수를 기록하고 있으나, 지금은 ○○○과 포정사 및 삼문, 부속건물 1채만 남아있다. 지금의 ○○○ 건물은 순조 33년(1833)에 지은 것으로, 원래는 공주 사범대학 부속고등학교 자리에 있었으나 1932년 현재의 위치로 옮겨지었다.","a":"선화당","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639151.jpg"},{"q":"○○○○의 본관은 파평인이고 자는 덕요(德耀), 호는 팔송(八松)이다. 27세에 문과에 급제한 후 사헌부감찰, 영광군수, 전주부윤, 대사간 등을 역임하였다. 숙종 36년(1710) 영의정의 증직과 다음해 6월에 문정공(文正公)의 시호를 받았다. 재실의 건축연대는 재실의 상량문을 통하여 보면 현종 6년(1665)에 안채를 짓고 숙종 21년(1695)에 문간채와 동재, 서재를 건축한 것을 알 수 있다. 집의 구조는 ‘一’자형의 사랑채와 별도로 떨어진 ‘ㄱ’자형의 안채, 문간채 및 서재가 있어 전체적인 구조는 ‘ㅁ’자형으로 되어 있다.","a":"논산윤황선생재실","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661570.jpg"},{"q":"○○○○○ 석가○○○○○는 크기가 4미터에 달하는 대작에 속한다. 화면에는 중앙의 석가여 래를 중심으로 좌우에 문수·보현의 협시보살과 사천왕을, 뒤쪽으로 여섯 제자와 타방불 2위, 그리고 4위의 팔부신장을 나누어 배치하였다. 화면은 부분적으로 약간의 훼손이 있을 뿐 전체적으로는 상태가 양호하다. 본 작품은 ○○○○○ 삼세불상의 뒷면에 걸려 있는 석가모니후불탱화로 채색은 전통적인 녹색과 적색을 주조색으로 하여 부드러운 황토색을 넓게 채색하여 자연스러운 느낌을 주고 있다. 인물들의 비례도 조화로우며 섬세한 필선과 부드러운 채색이 마치 18세기 불화를 보는 듯하다.","a":"장안사 대웅전 영산회상도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636766.jpg"},{"q":"과거 닭실마을로 오르는 초입부분 우측편에 자리하고 있는 ○○○○은 조선 중종때 명신 충재 권벌(1478∼1548)의 학문과 덕행을 추모하기 위하여 당시 안동부사였던 김우옹이 조선 선조 21년(1588)에 건립하였다고 한다. 조선 선조 31년(1601)에 한강 정구(鄭逑)가 사당을 충정공사(忠定公祠), 당호를 정일당(精一堂), 동재를 사무사(思無邪), 서재를 무불경(毋不敬), 정문을 환성문(喚惺門), 문루를 관물루(觀物樓)라 각각 명명하였다. 그리고 현종 1년(1660)에 ○○○○으로 사액받았다.","a":"봉화삼계서원","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663351.jpg"},{"q":"신라 무염대사가 처음 지었다는 ○○○의 ○○○ 안에 모셔진 26구의 불상으로 ○○○○과 시왕 및 그 권속으로 이루어져 있다. ○○○○을 중심으로 그 양옆에 도명존자, 무독귀왕이 자리하고 있으며 주위에 시왕상 각 3구씩 6구와 동자상 3구가 있다. 또한 ○○○의 북쪽편에는 시왕상 2구, 사자상 3구, 동자상 1구가 있으며 남쪽편에는 시왕상 2구, 사자상 2구, 동자상 2구가 자리하고, 가운데 출입문 좌우에는 금강역사 2구가 자리하고 있다. 26구 모두 흙으로 만든 소조상으로서 ○○○○과 시왕상은 앉은 모습이며, 사자상, 금강역사, 동자상은 서 있다.","a":"심곡사명부전지장보살좌상및권속","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639694.jpg"},{"q":"강원특별자치도 춘천시 강원특별자치도청의 뒷산인 ○○○ 능선에 쌓은 산성으로, 가파른 지형을 이용해서 쌓았다. 원형은 많이 훼손되어 1991년에 105m를 복원하였고, 1993년에 40m를 복원하였다. 『신증동국여지승람』에는 봉산 산성의 둘레는 2,463척이고 높이는 10척이라 기록되어 있다. 『고려사절요』에 의하면 거란족의 침입으로 안찰사 노주한이 이곳에서 전사하였고, 『고려사』에는 몽고족의 4차 침입 때 춘천 주민들이 산성에 들어가 항거하였다는 기록이 있다.","a":"춘천봉의산성","c":"시도기념물","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647851.jpg"},{"q":"이 불화는 1907년 월초거연(月初巨淵)이 화주(化主), 강재희(姜在喜)가 대시주가 되어 대황제폐하 성수만세(聖壽萬歲), 황태자전하 경수천세(慶壽千歲), 황태자비전하윤씨 보령천추(寶齡千秋), 황귀비전하엄씨 보수제년(寶壽齊年), 의친왕전하 보수무강(寶壽無疆), 의친왕비전하 보록장춘(寶籙長春), 영친왕전하 보소여해(寶笑如海) 등을 기원하며 제작 봉안한 ○○○이다.","a":"수국사 현왕도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636438.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부른다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓는 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○○○의 지석묘는 ○○○ 탑평마을 중심부에 위치하며 민가에 둘러싸여 있다. 여러 개의 자연돌을 고임돌로 사용하고 그 위에 커다란 덮개돌을 올려 놓은 전형적인 바둑판식 ○○○의 형태를 갖추고 있다.","a":"충주 조동리 고인돌","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650785.jpg"},{"q":"○○○ 대웅전에 보존되어 있는 그림으로, 석가모니불의 생애를 묘사한 것이다. 가로 190.5㎝, 세로 147.5㎝ 의 크기로, 비단 바탕에 채색하였으며, 여덟 장면을 한 폭의 화면에 압축하여 그렸다. 화면을 8면으로 나누어 가장 극적인 장면만을 묘사하였는데, 각 장면에 흐르는 형식적인 형태와 탁한 색조는 19세기 말 당시의 불화양식을 잘 반영하고 있다.","a":"지장사 팔상도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588072.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안8분면 바닥가부좌상으로, 상단병풍과 하단돗자리의 이단구도를 배경으로 하여 돗자리위에 방석을 깔고 왼손에 주장자를 오른손엔 염주를 쥐고 있다. 화면 향좌측에는 ‘화엄종주○○○○○대선사지진(華嚴宗主雨潭堂有定大禪師之眞)’의 화제가 있고 그 옆으로 영찬문을 남기고 있으며, 화면 크기는 가로 85.0cm, 세로 129.6cm이다.","a":"우담당 유정 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643041.JPG"},{"q":"○○○○○는 경상남도 ○○시 하북면, ○○○ 대웅전과 금강계단 앞에 있는 비석이다. 2014년 1월 2일 경상남도의 유형문화유산으로 지정되었다. 1706년 계파대사가 금강계단을 중수하고 금강계단에 봉안된 부처님 진신○○의 유래와 역사에 대해서 기록한 비석이다.","a":"양산 통도사 석가여래 영골 사리 부도비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018111211380700.JPG"},{"q":"원래 정금사 절터라고 전해오던 곳에 있던 불상으로, 충주댐 건설로 1983년 4월 현위치로 옮겼다. 부분적으로 닳았을 뿐 비교적 완전한 모습에 속한다. 특히 오랫동안 땅에 묻혀 있었기 때문에 몸통의 밑부분이 약간 파손되었을 뿐 옷주름 등은 상태가 양호하다. 머리에는 상투 모양의 낮고 작은 머리묶음이 있으며, 얼굴은 길쭉하지만 풍만하다. 양쪽 눈은 가늘고 긴 듯 하나 닳아서 구분하기 어렵고 양쪽 귀는 길게 늘어져 어깨에 닿았다. 옷은 왼쪽 어깨에만 형식적으로 표시하고 가슴 부분이 널찍하게 드러났으며 왼쪽편에 주름이 몰려 있다.","a":"제천 덕주사 석조약사여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638709.jpg"},{"q":"전북특별자치도 남원시 송동면 ○○○ 대웅전 안에 모셔져 있는 높이 179㎝의 불상으로, 광배(光背)와 불상의 몸을 하나의 돌로 만들었다. 민머리 위에는 낮은 상투 모양의 머리묶음(육계)이 있고, 얼굴은 훼손이 심해 잘 알아볼 수가 없지만 작고 풍만한 것으로 보인다. 양 어깨를 감싸고 입은 옷은 굴곡 없이 직사각형에 가까운 몸에 평면적으로 흐르고 있다. 양 손은 가슴 앞에 들어 엄지와 검지를 맞댄 모습이다. 불상이 서 있는 사각형의 대좌(臺座)에는 연꽃잎이 새겨져 있으며, 그 아래 바닥돌에는 모서리 기둥이 새겨져 있다.","a":"가덕사석조여래입상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661804.jpg"},{"q":"1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 석탑이다. 탑신부는 1층 몸돌만 한 돌로 되어있고 그 위는 1층 지붕돌과 2층 몸돌, 2층 지붕돌과 3층 몸돌, 3층 지붕돌과 꼭대기의 머리장식 받침돌이 각각 한돌로 이루어져 있다. 1층 몸돌에는 모서리마다 기둥 모양을 새겨 놓았고, 두꺼운 지붕돌은 밑면에 3단씩의 받침을 두었다. 고려시대 중기 이후의 석탑양식을 보여주는 탑이다. 고려 때 수타사(壽陀寺)에서 세웠다고 전하고 있으며, 관(官)에서 탑을 옮기려 하다 호랑이가 나타나 길을 막는 바람에 옮기지 못하였다는 전설이 내려오고 있다.","a":"괘석리삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660329.jpg"},{"q":"영산강 유역에 펼쳐진 나주평야의 중심지에 있는 이 성은 ‘잣미’라 불리는 야산 정상부를 에워싼 테뫼식 산성이다. ○○○○이란 이름은 성을 뜻하는 우리말 ‘잣’과 산을 뜻하는 우리말 ‘메·뫼·미’가 합쳐진 말로, 성이 있는 산이란 뜻이다. 성의 둘레는 약 740m로 규모는 작으며, 말안장 모양의 산등성이를 흙으로 쌓은 후 돌로 보강한 것이다. 성 안에는 평탄한 건물터와 요왕천이란 샘터가 확인되었고, 문터는 3곳이 있으나 규모는 알 수 없다.","a":"나주자미산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654233.jpg"},{"q":"○○○ 극락전의 주불로 아미타불과 관음보살, 대세지보살의 삼존상이다. 이 불상은 법당이 1733년 화재로 소실된 이후, 1735년부터 1737년까지의 중창불사 때에 법당과 함께 조성된 상이다. 1737년(건륭 2년)에 이루어진 복장 발원문은 다시 불상에 봉안되었는지 조사 때에는 볼 수 없었고, 『寺誌』(충청북도, 1982. P.254)에 수록되어 있어 참고할 수 있다. 그 내용을 보면, 이 불상을 만든 조각장은 演機, 斗策, 守性, 超鵬, 守堅, 廣鵬 등임을 알 수 있다.","a":"보은 법주사 복천암 목조아미타여래삼존좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638947.jpg"},{"q":"○○○○은 조선시대에 백성들에게 세금을 매기거나 나라에서 필요한 노동력을 얻기 위해 작성한 호구조사 기록문서이다. ○○○○의 작성은 3년마다 만들었으며, 각 읍·면에서 감독관이 각 집안별로 호구단자(실태조사기록) 2부를 만들어 군현에 보내졌다. 군 현에서는 호구단자를 호적과 비교한 후 1부는 호주에게 교부하고 1부는 호적작성의 자료로 삼았다. 또한 군현에서는 호적을 3부로 만들어 1부는 군현에, 1부는 감영에, 1부는 호조에서 관리하여 세금을 매기는 자료로 활용했다.","a":"언양현호적대장","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637267.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 거창 ○○○ 구릉지대에 3기의 고인돌이 있다. 이 가운데 제일 남쪽에 있는 것은 탁자식으로 덮개돌의 크기는 길이 2.86m, 너비 2.50m이다.","a":"거창내오리지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655101.jpg"},{"q":"‘○○남문창의’란 조선 선조 25년(1592) 임진왜란이 일어났을 때 김경수, 김제민, 기효간, 윤진 등이 전라도 일대에서 의병을 모아, 당시 ○○현감이었던 이귀의 협력을 얻어 남문에 의병청을 설치하고 의병활동을 펼친 것을 이른다. 김경수를 맹주로 삼고, 김제민을 의병장으로 두어 북으로 진군하면서 왜적과 맞서 싸우며 큰 공을 세우는 등 많은 전과를 올리다 전사하였는데, 이러한 그들의 충절을 기리고자 이 비를 세운 것이다. 비각 안에 놓여 있는 비는 사각받침돌 위로 비몸을 세우고, 지붕돌을 올린 모습으로, 조선 후기에 나타나는 양식을 그대로 따르고 있다.","a":"장성 오산창의비와 창의사","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639982.jpg"},{"q":"○○○○○은 중국 당(唐)의 실차난타(實叉難陀)가 번역한 지장신앙의 기본경전으로 지정○○○․지장본행경(地藏本行經)․지장본서력경(地藏本誓力經)이라고도 한다. 이 책은 ○○○○이 본생(本生)에서 세웠던 서원(誓願)과 그 이익을 밝히고 이 경전 자체의 불가사의한 이익을 강조하여 이 경(經)의 일구 일게(一句 一偈)만 독송(讀誦)하거나 들어도 무량의 죄업(罪業)을 씻을 수 있다고 주장하고 있다. 본 서울역사박물관 소장본 ○○○○○은 상․중․하 3권을 1책으로 묶은 판본인데 각 권마다 장차(張次)가 표시되어 있다.","a":"지장보살본원경","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590462.jpg"},{"q":"○○○○○는 사자형 받침대와 용문초의 상하 2단 구조로 되어 있으며. 하단의 받침대는 3층으로 구분되어 맨 아래쪽은 사자형 받침, 중간은 죽절형 간주, 맨 위쪽에는 전접시가 달린 초꽂이로 되어 있다. 상단의 용문초는 목재로 만든 길쭉한 원통형이고 내부에 용문양이 새겨진 초의 형태를 갖추고 있다 푸른 사자의 받침대 아래는 안쪽으로 1cm 가량 움푹 패여 있고, 푸른 사자의 받침에만 먹으로 “畵圓 僧 勝尒”라는 명문이 새겨져 있다.","a":"온양민속박물관 소장 용문촛대","c":"시도유형문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052217222400.jpg"},{"q":"뚜껑을 포함한 총 높이가 25㎝에 이르는 조선 전기의 중형 백자항아리이다. 최대 직경이 중앙부에 있는 본 항아리는 마치 조선후기의 원호와 유사한 형태를 지니지만, 조선 후기 항아리와 비교했을 때는 높이에 비해 너비가 넓어 약간 납작하면서 타원형에 가까운 느낌을 주며 옥연형의 구연을 갖고 있다는 점에서 차이를 보인다. 본 항아리의 태토는 매우 순도 높은 백점토를 활용한 듯 잡물이 전혀 없어 최상급의 백자임을 알 수 있다. 광택이 나는 유약은 균열이 없어 매우 잘 구워졌음을 알 수 있으며 실제로 경도(硬度) 또한 매우 강하다.","a":"백자유개호","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637238.jpg"},{"q":"이계당은 조선후기 문신인 남몽뢰(南蒙賚 1620~1681)가 강학하던 서재이다. 이 건물은 정방형 평면을 가진 팔작기와집으로 평면은 전면칸을 우물마루로 꾸미고 후면칸에는 온돌방을 들였다. 온돌방의 좌측칸에는 머름없이 온연귀한 문틀을 세운 후 굼널띠살문을 설치하는 등 건립당시의 모습을 볼 수 있다.","a":"의성이계당","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663471.jpg"},{"q":"고려와 조선시대에 각 고을에 설치했던 관아건물이다. 조선 숙종 38년(1712)에 다시 지어진 것으로 전해오는데, 안동댐 건설로 1976년 지금의 위치로 옮겨졌다. 一자형 구조를 지니고 있는 이 객사는 앞면 11칸·옆면 3칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"선성현객사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640280.jpg"},{"q":"낙안읍성 내의 객사로 들어가는 입구 도로가에 있는 한채의 비각과 그 안에 서 있는 비로, ○○○ 장군의 어진 다스림을 기리고 있다. ○○○은 조선시대 중기의 명장으로, 인조 4년(1626) 이곳 전라도 낙안지역의 군수로 부임해왔다. 인조 6년(1628) 3월 서울지역으로 옮겨갈 때까지 낙안읍성을 쌓는 등 어진 다스림을 베풀었으며, 병자호란과 정묘호란 때에도 큰 공을 세웠다. 이 지역에는 그에 관한 많은 전설이 내려오고 있는데, 그를 이 지역의 수호신으로 신봉하기도 하여 매년 정월 보름이면 낙안면 주인들에 의한 큰 제사가 행하여 지고 있다.","a":"임경업장군비각","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661977.jpg"},{"q":"간송미술관에 진열되어 있는 8각 사리탑으로, 바닥돌 위로 기단(基壇)을 올리고, 탑신(塔身)을 얹은 후 머리장식으로 마무리한 모습이다. 기단은 세 부분으로 이루어져 있는데, 그 중 아래받침돌에는 도드라진 연꽃무늬가 있고, 가운데받침돌은 아무런 꾸밈이 없다. 지붕돌은 밑면에 2단의 받침을 두었으며, 여덟 귀퉁이마다 큼직한 꽃조각이 솟아 있다. 꼭대기에는 그릇을 엎어놓은 듯한 둥근 머리장식이 놓여 있다. 사리의 주인공에 대해서는 알 수 없으나, 탑의 양식이나 조각기법으로 보아 통일신라시대의 작품으로 추측된다.","a":"석조팔각승탑","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636111.jpg"},{"q":"경상북도 경주시 남산의 여러 계곡 가운데 하나인 ○○○의 ㄱ자형 바위벽에 새긴 불상이다. 동남향한 바위면에 2구, 서남향한 바위면에 1구를 새겨 삼존불(三尊佛)의 형식을 띠고 있는데, 그 배치가 매우 특이하다. 중앙의 불상은 연꽃 대좌(臺座) 위에서 앉아 있다. 정수리 부분에 있는 상투 모양의 머리묶음이 유난히 높고 크며, 얼굴은 긴 타원형을 이룬다. 턱은 각진 것처럼 표현하여 다소 완강한 느낌을 주지만, 눈을 가늘게 뜨고 입에는 미소를 띠고 있어 대체로 부드러운 인상이다.","a":"경주배리윤을곡마애불좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640680.jpg"},{"q":"무너져 흩어진 석탑의 일부분들로, 1982년 4월 19일 지금은 과수원으로 변한 ‘절골’이라는 마을의 옛 절터에서 발견되었다. 남아있는 부재는 대부분 지붕돌인데, 낙수면이 일부분 잘려 나갔다. 탑신(塔身)의 몸돌은 따로 만든 것도 보이나, 지붕돌과 몸돌을 한돌로 만든 경우도 보인다. 1988년 처음 조사하여 탑의 부재들을 한 자리에 모아 놓았는데 부재들의 상태로 보아 3층 석탑이었을 것으로 보인다.","a":"상주 낙상동 폐탑","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662645.jpg"},{"q":"신라 최초의 불교신도인 모례(毛禮)의 집안에 있던 우물이라 전해진다. 모례는 모록(毛祿)이라고도 하며, 고구려의 승려 묵호자가 불교를 전파하기 위해 신라로 왔을 때, 집 안에 굴을 파서 3년 동안 묵호자를 숨겨주었다 한다. 또한 신라에 처음으로 불교를 전한 아도화상이 수행인 3명을 데리고 신라로 왔을 때에도, 자신의 집에 머물게 하였다는 이야기도 전해온다. 우물은 길이 3m의 직사각형의 돌을 큰 단지모양으로 쌓아 만들었으며, 밑바닥은 두꺼운 나무 판자를 깔았다. 우물이 만들어진 정확한 연대는 알 수 없다.","a":"전모례가정","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663081.jpg"},{"q":"조선 중기의 대학자였던 사계(沙溪) ○○○ 선생과 광산 김씨의 중흥을 이룬 허씨 부인, 김철산, 김겸광, 김공휘 등의 묘지이다. ○○○은 송악필과 이이의 문하에서 학문을 배웠으며, 임진왜란 때에는 명나라 군대의 군량조달에 공을 세우기도 하였다. 늦은 나이에 벼슬을 시작하였고 과거를 거치지 않았기 때문에 중요한 벼슬은 맡지 않았으나 인조반정 이후로는 서인을 중심으로 한 기호학파의 중심 인물이 되어 영향력이 매우 컸다. 그는 주로 학문과 교육에 시간을 보내면서 조선 예학의 한 줄기를 형성했고 제자로 송시열과 송준길 등의 대학자를 배출했다.","a":"김장생선생묘소일원","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652755.jpg"},{"q":"1718년(숙종 44)에 왕이 지족당 조지서를 배향한 신당서원에 예조좌랑 이안국을 보내 치제하게 한 ○○○을 새긴 비석이다. 진주에서 합천으로 가는 길에 집현면 장흥리를 지나는 도로에서 약 30미터 정도에 있는 보호각 내에 세워져 있다. 비좌는 방부이고 이수는 가첨석으로 되어 있다. 비신의 규격은 가로 49㎝, 세로 130㎝, 폭 11㎝이고, 비신의 하부는 풍화가 심하여 글자를 판독할 수가 없으며, 비각은 맞배지붕의 기와지붕에 정면은 창살벽을 하였다. 좌우벽과 뒷벽은 회벽이고 비각 주위로 흙돌 담장을 둘렀는데 훼손이 심하다.","a":"진주숙종사제문비","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666026.jpg"},{"q":"○○○ 대웅전에 봉안된 이 여래상은 높이 60㎝, 폭 43㎝의 나무로 만든 조그만 불상이다. 전체적으로 불상의 상태는 아주 양호한데, 머리에 상투모양과 구슬이 표현되어 있고 입은 꼭 다문 모습이다. 옷자락은 양쪽 어깨에 걸쳐서 U자 모양으로 흘러내리고 있다. 손 모양은 아미타여래의 9가지 손모양중 하품하생인을 연출하였다. 불상의 배 안에서 불상을 만들 때 남긴 기록과 경전 등이 발견되었는데, 그 기록에 따르면 이 불상은 조선 인조 22년(1644)에 조성되었다고 한다.","a":"진주성전암목조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642305.jpg"},{"q":"조선 전기에 지어 해안 방비를 담당하였던 방답진의 군관청이다. 방답진은 전라좌수영에 속해 있던 것으로 중종 18년(1523)에 설치됐고, 고종 32년(1895)에 폐지되었다. 1896년 돌산군이 설치되면서 건물의 대부분이 돌산군 행정관아로 사용되었다. 관청을 지은 것은 1872년∼1895년 무렵으로 추정되며, 고종 9년(1872)에 쓴 『방답진지도』에는 현재의 위치에 배를 두었던 곳이 있었던 것으로 나타나 이후에 관청이 지어진 것으로 보인다. ㄷ자형 평면구성이며 지붕은 옆면에서 볼 때 지붕선이 여덟 팔(八)자 모양과 비슷한 팔작지붕이다.","a":"돌산군관청","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640056.jpg"},{"q":"양세정효각(兩世旌孝閣)은 김해김씨 ○○○와 아들 ○○○의 효행을 기리기 위하여 1855년(철종 6)에 세운 것이다. 당초 전주시 삼천동 상거마을에 세웠던 것이 1981년 전주 도시계획에 따라 삼천동이 아파트단지로 조성됨에 따라 이곳 임실읍 정월리로 이전하였다. 정효각 안에는 효자 ○○○○○와 효자 ○○○○○ 2기와 정려각 편액에는 안팎으로 효덕연경당(孝德衍慶堂), 양세정효각(兩世旌孝閣)이라 새겨있다. 모두 추사(秋史) 김정희(金正喜, 1786∼1856)의 글씨이다.","a":"김복규.김기종효자정려비및정판","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639610.jpg"},{"q":"제작 연대가 확실하고 만든 스님의 이름까지 알 수 있는 조선 시대 후기의 대표적인 중소형 나무 불상이다. 불상 바닥에 사각형의 구멍이 뚫려 있는데 속에서 불교 경전과 다라니, 후령통(候鈴筒; ○○○을 넣는 원통형 용기) 등의 ○○○(腹藏物; 불상을 만들거나 칠을 새로 하면서 가슴 안쪽에 넣은 보석과 서책 등)이 나왔다.","a":"양주 회암사 목조여래좌상 및 복장물","c":"시도유형문화유산","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101620404700.jpg"},{"q":"○○○은 대대로 순흥 지역에 살고 있는 순흥안씨의 후손들이 사용했던 우물이다. 고려 시대 말에 이곳에 살았던 인물 안석(安碩)이 오래도록 사용한 우물이라고 전한다. 안석은 임금에게 벼슬을 받았지만 벼슬길에 나아가지 않았고, 고향에서 그의 세 아들 안축(安軸), 안보(安輔), 안집(安輯)을 훌륭하게 키웠다. 이후 조선 인종 원년(1545)에 풍기군수 주세붕이 이들 네 사람의 덕을 기리게 하며, 이 곳에 ○○○이라는 이름이 적힌 비를 세웠다고 한다.","a":"사현정","c":"시도기념물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654514.jpg"},{"q":"○○○은 1562년 경북 청도에서 남해 현령을 지낸 이몽상의 아들로 출생한 것으로 알려져 있다. 임진왜란 발발 당시인 1592년 옥포만호로서 옥포대첩에서 공을 세웠다. 1604년에는 선무공신으로 식성군(息城君)에 봉해졌고, 동 9월에 삼도수군통제사가 된 인물이다. 광해군 2년(1610년 사망한 후 병조판서로 추증되었다. 이 묘는 본래 경북 청도에 있었으나, 20년 후인 1630년 그의 아들 평택현감 이암에 의해 이곳으로 옮겨졌다. 현재 이곳은 외손인 밀성손씨 문중에서 관리하고 있으며, 그 내력은 택당 이식이 쓴 그의 묘비에 자세하게 기록되어 있다.","a":"의령 이운용 묘","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657569.jpg"},{"q":"1908년 전주선 교부의 데이트(Lews Boyd Tate) 선교사기 지은 한옥교회이다. 조선 예수교 장로회의 사기(事記)에 의하면, 처음의 교회는 1905년에 5칸으로 지었으나, 1908년 지금의 자리로 옮겨 지은 것이라고 한다. 현재 ○○○○ 옆으로 1988년에 새로 지은 교회본당과 사택이 들어서 있다. 건물은 남북방향으로 5칸이며, 여기에서 동쪽으로 2칸을 덧붙여 뒤집힌 ㄱ자 형태를 이룬다. 내부는 통칸으로 이루어졌으며, 남북방향 5칸과 동쪽방향 2칸이 만나는 곳에 강단을 설치하여 남쪽으로 남자석, 동쪽으로 여자석을 분리하여 마련하였다.","a":"금산교회","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661770.jpg"},{"q":"향교는 조선시대의 공식적인 지방 교육기관으로, 교과내용은 시문을 짓는 사장학(詞章學)과 유교 경전을 공부하는 경학으로 이루어져있다. 향교 건물은 문묘(文廟)와 학당(學堂)으로 나누어진다. 문묘에는 공자를 중심으로 중국의 사성(四聖)·이현(二賢)과 우리나라 십팔현(十八賢)을 모신 대성전(大成殿)과 동·서무(東·西黛)가 있다. 학당은 학생들을 가르치는 강의실인 명륜당(明倫堂)과 기숙사인 동·서재(東·西齋)로 구성된다. ○○○○는 본래 반월산 아래에 창건되었다고 전한다. 그 뒤 현재의 위치로 이전되었다가, 다시 화장산 아래로 옮겼고, 마지막으로 현 위치로 다시 이전하였다.","a":"언양향교","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637264.jpg"},{"q":"원래 동포마을에 있었으나, 일찍이 수해로 무너져 뒤쪽 골짜기인 현위치로 이건하였다. ○○○ 정자와 정침으로 구성되어 있다. ○○○은 정면 3칸 측면 1칸 반 규모의 맞배기와집이다. 평면은 좌측에 대청 1칸을 두고 우측에 온돌방 2칸을 연접시킨 후, 전면에는 반 칸 규모의 퇴칸을 두었다. 대청 배면 상부에는 감실을 설치하였고, 좌측 벽면의 중방과 하방 사이에는 작은 쌍여닫이 판문을 설치하였다. 정침은 정면 5칸 측면 5칸 반 규모의 ㅁ자형 건물이다.","a":"영주 석포리 야일당","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020030409245300.jpg"},{"q":"○○○ 안에 있는 연못 중 하나이다. 전체적인 모습은 석축을 단이 지게 정연하게 쌓아 동서로 최대 길이 21m, 너비 12m 정도로 위를 넓게 하고, 아래는 최대 길이 9m, 너비 4m로 좁혀 쌓아 석탑을 거꾸로 세워놓은 모양을 하고있다. 서남 방향에는 잘 다듬은 돌 2매씩을 길게 쌓아 10여 개의 계단을 설치하여 출입할 수 있는 통로를 마련하였다. 바닥에는 판판한 돌을 깔았고, 동·서벽쪽에는 너비 40㎝의 배수로를 설치하여 물의 흐름을 쉽게 하였다. 이 연못은 백제 때부터 계속하여 이용되었던 것으로 추정되고 있다.","a":"공주공산성연지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652735.jpg"},{"q":"글씨 쓴 사람은 미상이나, 그 필치로 보아 중국의 장필과 미불의 글씨가 유행하였던 조선 중·후기의 글씨로 추정된다. 결구가 치밀하고 풍격이 고고한 글씨로 이 바위가 위치한 곳 역시 조선시대 문집 및 고지도에서도 확인되는 역사적 명소이다.","a":"월암동","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102315355500.jpg"},{"q":"○○○ 약사전(보물 제179호)에 보존되어 있는 후불탱인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 조선 고종 21년(1884)에 제작된 그림으로 정사각에 가까운 화폭 중앙에 약사여래좌상과 좌우협시인 일광·월광보살을 배치하고 상하 좌우에는 사천왕을, 약사불 뒤에는 가섭과 아난을 그린 병렬식 구도를 보이고 있으며, 색채는 18세기 후반의 색 배합을 계승하고 있다. 전체적으로 전통적인 도상을 계승하고 안정된 화면 구성, 꼼꼼한 필력을 갖추고 있어 19세기 불화양식 연구에 귀중한 자료이다.","a":"강화 전등사 약사여래설법도","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101610044800.jpg"},{"q":"불상을 모시기 위해 나무나 돌, 쇠 등을 깎아 일반적인 건축물보다 작은 규모로 만든 공간을 불감(佛龕)이라 한다. 불감은 그 안에 모셔진 불상의 양식뿐만 아니라, 당시의 건축 양식을 살필 수 있는 중요한 자료가 된다. 송광사의 16번째 국사인 고봉화상이 소지했던 원불(願佛)이라 전하고 있다. 이 불감은 문을 열면 바로 양편 문 내벽에 문짝이 있고, 내부벽에 불·보살 등을 양각으로 조각하였다. 중앙에 있는 주존불(主尊佛)은 대일여래불로 손모양은 통일신라시대 이후 전통적인 비로자나불이 보통 취하는 손모양이 아닌 금강권인을 하고 있다.","a":"고봉국사주자원불","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639852.jpg"},{"q":"부도는 승려의 유골이나 사리를 모셔두는 곳으로 승탑이라고도 불린다. 탑이 주로 사찰 안에 있는 반면 부도는 보통 사찰 밖에 세워진다. ○○○○○은 일주문 바로 뒤편에 자리하고 있으며, 주로 17~19세기 ○○○에서 수행한 승려들의 사리를 모시고 있다. 조선시대 대표적인 부도 형태인 종 모양 부도와 동그란 공 모양의 부도 등이 안치되어 있어 조선시대 다양한 형태의 부도를 확인할 수 있다.","a":"안심사부도군","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661886.jpg"},{"q":"이곳은 신말주 선생과 정부인 설씨를 비롯하여 ○○○ 선생 등 그의 후손들이 살았던 곳으로, 1996년부터 복원사업을 추진하고 있으며 세거지 좌측에는 보물 ○○○○권선문첩(勸善文帖)을 비롯한 여러점의 문화유산 보호각이 위치하고 있으며 보호각 뒤쪽에는 귀래정(歸來亭)과 수백년 된 노송들이 서 있다.","a":"설씨부인, 신경준선생유지(귀래정신말주후손세거지)","c":"시도기념물","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653629.jpg"},{"q":"남평문씨 시조인 문다성의 탄생 설화와 관련된 바위로, 경사면에 놓여 있어서 앞에서 보면 높이 6m, 폭 5m의 크기로 보이나, 뒤에서 보면 1m 정도로 보인다. 조선 영조 21년(1731)에 쓰인 남평문씨 창간보 『신해보』와 규장각에 소장되어 있는 『호남읍지』에는 다음과 같은 기록이 적혀 있다. 당시 이곳 현감을 지내던 자가 장자연못의 바위 위에서 울고 있는 아기를 거두어 기르게 되었다. 글에 능하다 하여 성을 ‘문’으로 짓고, 사물의 이치를 잘 깨닫는다 하여 ‘다성’이라 이름지으면서, 아기가 있던 바위를 ‘문암’이라 이름붙여 이 아기를 문씨의 시조로 삼았다.","a":"나주문바위문암","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2019051719545000.jpg"},{"q":"패총(貝塚)이란 수렵, 어로, 채집에 의하여 살아온 옛 사람들이 조개를 먹은 뒤 버린 조개껍데기와 생활쓰레기가 함께 쌓여 이루어진 유적으로 조개더미라고도 한다. ○○○○은 지표상에 흩어진 유물 분포 범위가 10,000평 이상의 대규모 유적지로 철기시대부터 조선시대에까지 이르는 연속된 패총문화층을 보여주고 있다.","a":"곽지패총","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657882.jpg"},{"q":"○○○를 세운 정확한 시기는 알 수 없으나 ○○ 안에 모시고 있는 동제관음보살상에 새긴 글로 보아 고려 목종 5년(1002)에 세운 것으로 추정한다. 지금 있는 ○○은 1970년에 새로 지은 것이다. 앞면 4칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○에는 ○○ 외에도 ○○ 앞에 있는 ○○○ 5층석탑(문화유산자료), ○○ 뒤 바위에 조각된 ○○○ 마애불(문화유산자료), 자연동굴 속 암벽에 조각된 ○○○ 석불좌상(문화유산자료), ○○ 안에 있는 ○○○ 금동불(문화유산자료) 등 많은 문화유산이 있다.","a":"만일사 법당","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661307.jpg"},{"q":"○○○○○은 탑정저수지 북쪽 끝에 위치한 고려시대 석탑으로, 전승에 의하면, 고려 태조가 남쪽으로 견훤을 정벌할 때 이곳에 주둔하여 '어린사(魚鱗寺)'라는 절에 있던 탑이라는 설과 후백제 때 대명(大明) 스님의 부도(浮屠)였다는 설이 함께 전한다. 원래의 탑은 일제강점기 저수지 조성 과정에서 원래 자리에서 약 50m 북쪽으로 옮겨진 것으로 알려져 있다. 탑의 전체적인 구조는 부도탑(浮屠塔, 사리나 유골을 안치하기 위한 묘탑)으로, 기단(基壇)과 탑신(塔身)으로 구성되어 있으나, 현재는 1층만 남아 있어 원형을 정확히 파악하기 어렵다.","a":"논산탑정리석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639101.jpg"},{"q":"경상북도 안동시 북문동에 자리잡고 있는 이곳은 고려의 개국공신인 김선평, 권행, 장정필 3명의 태사(太師)의 위패를 모신 곳이다. 930년 태조가 안동에서 견훤(甄萱)을 토벌할 때 세운 공로로, 권행과 장정필은 대상(大相)이란 벼슬을, 김선평은 대광(大匡)이란 벼슬을 받았다. 기록에 의하면 고려 성종 2년(983)에 처음으로 3명의 제사를 안동부사가 거행하였다고 한다. 현 위치의 묘우는 조선 중종 37년(1542)에 세운 것인데, 한국전쟁 때 불에 타 1960년대에 다시 세운 것이다.","a":"안동태사묘","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654417.jpg"},{"q":"○○○의 영산회괘불탱(국보 제302호)을 보관하는 함이다. 영산회괘불탱은 석가모니가 영취산에서 법화경을 설법하는 장면을 묘사한 그림으로 9구의 불·보살이 그려져 있다. 중앙에 석가불이 화면을 가득 채우며 서 있고 좌우에 문수보살과 보현보살이 연꽃가지를 들고 서 있으며, 그 뒤쪽으로 석가의 2대 제자인 가섭과 아난이 배치되어 있다. 조선 경종 2년(1722) 의겸스님이 제작한 것으로, 석가불 얼굴의 묘사 기법과 의복의 묘사에 가해진 기법 등은 당시 불화의 특징을 잘 보여준다.","a":"진주청곡사괘불함","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642087.jpg"},{"q":"경남대학교 박물관 소장 ‘○○○○문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 ○○○○ 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 ○○○○문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 ○○○○문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다.","a":"데라우치 기증 고서화 일괄","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643210.jpg"},{"q":"고려 후기의 문신인 ○○ 부부의 ○○이다. 고려 충숙왕 12년(1325) 음서로 팔관보판관이 되고 다음해 문과에 급제하였다. 그 뒤 여러 관직을 역임하였으며, 1358년 벼슬이 형부상서에 이르렀다. 공민왕의 각별한 총애를 입어 내불당 짓는 일을 감독하였으며, 공민왕이 친히 쓴 글씨 ‘탄상하교문(嘆賞下敎文)’을 받았다. 그의 친족은 모두 높은 관직에 올랐고, 이성계의 위화도 회군 이후 그의 집정기간에는 유력한 지지세력으로서 조선 건국에 크게 도움을 주었다. 묘는 고려 후기의 사다리꼴의 특징을 보여주고 있으며, 묘 앞에는 묘비·상석이 있다.","a":"진천 이정 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650305.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 숙종 3년(1677)에 처음 지었으나 모든 건물들이 조선 후기 건축 양식으로 되어 있다. 현재 남아 있는 건물로는 대성전과 명륜당, 동재, 서재, 신문(내삼문) 등이다. 대성전은 앞면 5칸·옆면 3칸 규모로，지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 안쪽에는 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 있다. 학생들이 모여 공부하는 명륜당은 앞면 5칸·옆면 2칸 규모로 이루어져 있다.","a":"영양향교","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662499.jpg"},{"q":"통일신라 후기의 승려인 ○○○○의 초상화이다. 도선은 주로 통일신라말·고려초에 활약했으며 비기(秘記:신기한 기록)나 풍수지리설과 연관되어 있어 실재 인물이라기보다 신화적 존재로 파악되기도 한다. 고려 태조 왕건의 탄생을 예언하기도 하여 태조 이후 고려의 왕들로부터 많은 존경을 받았다. 초상화는 불교의 의식 때에 왕사나 대사 등이 손에 드는 장자를 들고 의자에 걸터앉아 약간 오른쪽을 바라보고 있는 모습을 그린 전신상으로, 화폭의 윗부분에 ‘○○○○○’이라는 제목을 써 놓았다.","a":"도갑사도선국사진영","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640111.jpg"},{"q":"○○○는 신라 응진 스님이 처음 지어 국태사라 이름하였다가 고려 혜월선사를 거쳐 진관선사에 이르러 다시 고쳐 지었다고 전한다. 고려 대각국사 의천이 천태종을 다시 세울 때 기반이 된 선종 5산문 가운데 하나가 ○○○인 것으로 나타나고 있어 고려 불교계에 중요한 위치를 차지했던 사찰로 짐작된다. 조선시대에 들어서도 ○○○에 대한 기록이 각종 지리서에 나타나고 있는 것으로 보아 여전히 중심사찰로서 역할을 하였음을 알 수 있다.","a":"산청지곡사지","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656866.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. 이 부도는 보림사터에서 조금 떨어진 영축산 중턱에 자리하고 있는 것으로, 이 절을 거쳐간 승려들 중 한분이 그 주인공이 될 것이다. 낮은 받침돌 위로 배를 부풀린 듯한 종 모양의 탑몸돌을 올린 모습이며, 꼭대기에는 꽃봉오리 모양을 한 작은 머리장식이 솟아 있다. 보림사는 통일신라말 또는 고려초에 창건되어 임진왜란 이후 폐허가 되었으므로, 이 부도를 만든 시기는 고려말·조선초 즈음이었을 것으로 추정된다.","a":"창녕 보림사지 승탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642253.jpg"},{"q":"조선시대에 서당에서 고문의 연변(演變)과 체법을 익히기 위하여 교재로 쓰던 시문선집으로서 송나라 말기의 학자 황견이 편찬한 것이다. 20권 10책으로, 전국시대에서 송나라 말기까지의 시문을 전집과 후집으로 나누어 수록하였는데 전집에는 시를, 후집에는 문을 수록하였다. 이 책은 당시 서당의 교육정도를 살필 수 있는 자료로 평가된다.","a":"상설고문진보대전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636266.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 지세포는 해변에 가까이 접해있는 마을이며 이 일대에는 비교적 넓은 평야가 있다. 논둑 사이의 농로 옆에 정자나무가 있는데 그 아래에 고인돌 2기가 하나는 바닷가쪽으로, 나머지는 산쪽으로 자리잡고 있다.","a":"거제 지세포리 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656620.jpg"}]);